export const CHAPTERS: Chapter[] = [{"id":1,"num":"Ch 1","subj":"chem","title":"Chemical Reactions & Equations","oneshot":["Signs of chemical reaction: colour change, gas evolution, precipitate, temperature change","Law of Conservation of Mass: mass of reactants = mass of products (Lavoisier)","Exothermic: releases heat (burning, respiration); Endothermic: absorbs heat (photosynthesis, decomposition)","Oxidation = gain of O or loss of H; Reduction = loss of O or gain of H; both happen together (redox)"],"keypts":["Combination A+B→AB | Decomposition AB→A+B | Displacement A+BC→AC+B | Double Displacement AB+CD→AD+CB","Thermal decomp: CaCO₃→CaO+CO₂; Electrolytic: 2H₂O→2H₂+O₂; Photolytic: 2AgCl→2Ag+Cl₂ (sunlight)","Reactivity series: K>Na>Ca>Mg>Al>Zn>Fe>Pb>H>Cu>Ag>Au","Corrosion: slow metal oxidation (rust = Fe₂O₃·xH₂O); Rancidity: oxidation of fats/oils (bad smell)","Rancidity prevented by: antioxidants, airtight containers, refrigeration, nitrogen gas flushing","Mg ribbon rubbed with sandpaper to remove basic magnesium carbonate coating before burning"],"formulas":"2Mg + O₂ → 2MgO (white, exothermic)\n2Al + Fe₂O₃ → Al₂O₃ + 2Fe  (Thermite reaction — huge heat)\nZn + CuSO₄ → ZnSO₄ + Cu  (displacement — blue→colourless)\n6CO₂+12H₂O+light→C₆H₁₂O₆+6O₂+6H₂O  (photosynthesis, endothermic)\nC₆H₁₂O₆+6O₂→6CO₂+6H₂O+ATP  (respiration, exothermic)","exam":["Mnemonic: Katrina ne Car Mangi Alto Zen Ferari Phir bhi Haye Cu Mili Silver Audi","AgCl stored in dark bottles — photolytic decomposition by light","Thermite welding: 2Al+Fe₂O₃→Al₂O₃+2Fe — joins railway tracks with molten iron"]},{"id":2,"num":"Ch 2","subj":"chem","title":"Acids, Bases & Salts","oneshot":["Acids: pH<7, sour, blue litmus→red, produce H⁺ in water","Bases: pH>7, bitter/soapy, red litmus→blue, produce OH⁻ in water","Neutralisation: Acid + Base → Salt + Water (exothermic, moves pH toward 7)","pH scale: 0=strongest acid, 7=neutral, 14=strongest base"],"keypts":["Acid+Metal→Salt+H₂ | Acid+Carbonate→Salt+H₂O+CO₂ | Acid+Metal Oxide→Salt+Water","HCl gas does NOT turn litmus red — acids ionise (give H⁺) only in water","Chlor-alkali process: 2NaCl+2H₂O→Cl₂(anode)+H₂(cathode)+2NaOH(solution)","Baking powder = NaHCO₃ + tartaric acid → CO₂ released → fluffy cakes","CuSO₄·5H₂O (blue crystals) →(heat) CuSO₄ (white powder) + 5H₂O — reversible","Plaster of Paris CaSO₄·½H₂O + H₂O → Gypsum CaSO₄·2H₂O (sets hard)","pH: gastric juice 1.5–3.5; saliva 6.5–7.5; blood 7.35–7.45"],"formulas":"NaOH + HCl → NaCl + H₂O  (neutralisation)\nZn + 2HCl → ZnCl₂ + H₂↑\nNa₂CO₃ + 2HCl → 2NaCl + CO₂↑ + H₂O\n2NaOH + CO₂ → Na₂CO₃ + H₂O\nCuSO₄·5H₂O →(heat) CuSO₄ + 5H₂O","exam":["Baking soda (NaHCO₃) as antacid: neutralises excess HCl in stomach","Washing soda=Na₂CO₃·10H₂O | Baking soda=NaHCO₃ | Bleaching powder=Ca(OCl)Cl","Universal indicator gives rainbow of colours for different pH values — used in labs"]},{"id":3,"num":"Ch 3","subj":"chem","title":"Metals & Non-Metals","oneshot":["Metals: lustrous, malleable, ductile, good conductors, sonorous, high MP/BP","Non-metals: dull (except iodine), brittle, poor conductors (except graphite)","Metal oxides = basic; Non-metal oxides = acidic (CO₂+H₂O→H₂CO₃)","Reactivity: K>Na>Ca>Mg>Al>Zn>Fe>Pb>H>Cu>Ag>Au → guides extraction method"],"keypts":["K,Na react violently with cold water; Mg with hot water; Fe/Al/Zn with steam only; Cu/Ag/Au — no water reaction","Ionic compounds: high MP/BP, conduct when molten or dissolved, form crystals","Thermite: 2Al+Fe₂O₃→Al₂O₃+2Fe+huge heat (welding railway tracks)","Amphoteric metals/oxides react with BOTH acid and base: Zn, Al, Pb, Sn","Aqua regia: 3 parts conc.HCl + 1 part conc.HNO₃ — dissolves gold & platinum","Alloys: Brass=Cu+Zn | Bronze=Cu+Sn | Solder=Sn+Pb | Stainless steel=Fe+Cr+Ni","Electrolytic refining: pure metal at cathode; impure anode dissolves; precious metals in anode mud"],"formulas":"2Na+2H₂O→2NaOH+H₂↑ (violent)\nCa+2H₂O→Ca(OH)₂+H₂↑ (mild, floats)\nFe+CuSO₄→FeSO₄+Cu  (iron nail turns copper-red)\n2Al+Fe₂O₃→Al₂O₃+2Fe  (thermite)\nZn+2NaOH→Na₂ZnO₂+H₂↑  (amphoteric)","exam":["Mercury = only liquid metal at RT; stored in glass bottles","Ores vs Minerals: all ores are minerals; mineral becomes ore only if metal can be extracted profitably","Gangue = rocky impurities with ore; removed during ore dressing/concentration"]},{"id":4,"num":"Ch 4","subj":"chem","title":"Carbon & Its Compounds","oneshot":["Carbon: valency 4; catenation + tetravalency → millions of organic compounds","Allotropes: Diamond (hard, 4 bonds, insulator), Graphite (soft, 3 bonds, conductor), Fullerene (C₆₀)","Functional groups: –OH alcohol | –CHO aldehyde | –COOH carboxylic acid | C=O ketone","Homologous series: same general formula, differ by –CH₂–, similar chemical properties"],"keypts":["Alkanes (saturated): blue flame; substitution reactions with Cl₂ in sunlight","Alkenes/Alkynes (unsaturated): yellow sooty flame; addition reactions","Hydrogenation: unsaturated oil + H₂ →(Ni, 200°C) saturated fat (vanaspati ghee)","Ethanol (C₂H₅OH): fermentation of glucose by yeast; denatured = + methanol + dye (poison)","Acetic acid: 5–8% = vinegar; 100% pure = glacial acetic acid (freezes at 290K)","Saponification: fat/oil + NaOH → soap + glycerol; NaOH→hard soap; KOH→soft soap","Detergents work in hard water (sulphonate group); soaps don't (scum with Ca²⁺/Mg²⁺)","Micelle: hydrophilic head in water, hydrophobic tail surrounds oil droplet — cleansing action"],"formulas":"CH₄→C₂H₆→C₃H₈→C₄H₁₀  (alkanes, CₙH₂ₙ₊₂)\nC₂H₅OH+CH₃COOH→CH₃COOC₂H₅+H₂O  (esterification, H₂SO₄ cat.)\nCH₃COOC₂H₅+NaOH→CH₃COONa+C₂H₅OH  (saponification)\nC₂H₄+H₂→C₂H₆  (addition/hydrogenation, Ni cat.)","exam":["IUPAC: 1C=meth, 2C=eth, 3C=prop, 4C=but, 5C=pent, 6C=hex","Structural isomers: same molecular formula, different structure (n-butane & isobutane = C₄H₁₀)","Ester smell: sweet/fruity → used in perfumes, flavourings, nail polish remover"]},{"id":5,"num":"Ch 5","subj":"chem","title":"Periodic Classification","oneshot":["Döbereiner triads: middle element mass ≈ average of other two (Li–Na–K)","Newlands' Octaves: every 8th element similar to 1st — worked only up to Ca","Mendeleev (1869): arranged by atomic mass; left gaps; predicted Eka-Si=Ge","Modern Periodic Law (Moseley 1913): properties are periodic function of ATOMIC NUMBER"],"keypts":["Modern table: 18 groups (columns) + 7 periods (rows); s,p,d,f blocks","Left→right in period: atomic size decreases, metallic character decreases, IE increases","Down a group: atomic size increases, metallic character increases, IE decreases","Group 1=Alkali metals | Group 2=Alkaline earth | Group 17=Halogens | Group 18=Noble gases","Period = number of electron shells; Group (main) = number of valence electrons","Metalloids on diagonal boundary: Si, Ge, As, Sb, Te — intermediate metal/non-metal properties","Mendeleev limitations: anomalous pairs (Ar–K, Co–Ni, Te–I); no place for isotopes; H placement controversial"],"formulas":"Period 2 atomic size: Li > Be > B > C > N > O > F  (decreasing left to right)\nPeriod 2 IE: F > O > N > C > B  (increasing left to right, with exceptions)","exam":["Eka-aluminium = Gallium (Ga); Eka-silicon = Germanium (Ge) — discovered after Mendeleev","Modern law resolves anomalies: Ar(18) before K(19), Co(27) before Ni(28) ✓ by atomic number","Isotopes: same atomic number → same position in modern table (no problem)"]},{"id":6,"num":"Ch 6","subj":"bio","title":"Life Processes","oneshot":["Life processes: Nutrition, Respiration, Transportation, Excretion (NRTE)","Photosynthesis: 6CO₂+12H₂O+light→C₆H₁₂O₆+6O₂+6H₂O (chloroplast, endothermic)","Aerobic: Glucose+O₂→CO₂+H₂O+38ATP | Anaerobic muscle: Glucose→Lactic acid+2ATP","Double circulation: blood passes through heart TWICE per circuit — efficient O₂ delivery"],"keypts":["Stomata: CO₂ in, O₂ out; guard cells control opening; close at night to prevent water loss","Heterotrophic: Holozoic (humans), Saprophytic (fungi — external digestion), Parasitic (tapeworm)","Gastric juice: HCl (kills bacteria, activates pepsin) + Pepsin (proteins) + Mucus (protects lining)","Bile (liver→gall bladder→small intestine): emulsifies fats, creates alkaline medium for enzymes","Villi in small intestine: increase surface area for absorption; lacteals absorb fats","Heart: 4 chambers; left side=oxygenated; right side=deoxygenated; valves prevent backflow","Nephron: Bowman's capsule+Glomerulus (filtration)+Tubule (reabsorption)+Collecting duct","Transpiration: water loss from leaves → suction pull draws water up from roots (ascent of sap)","Hemodialysis: artificial kidney; used when kidneys fail; blood filtered through semipermeable membrane"],"formulas":"Photosynthesis: 6CO₂+12H₂O+light→C₆H₁₂O₆+6O₂+6H₂O\nAerobic: C₆H₁₂O₆+6O₂→6CO₂+6H₂O+38ATP\nAnaerobic(yeast): Glucose→2Ethanol+2CO₂+2ATP\nAnaerobic(muscle): Glucose→2Lactic acid+2ATP","exam":["Haemoglobin's affinity for CO is 200× greater than O₂ — why CO poisoning is so deadly","Muscle cramps = lactic acid buildup during anaerobic respiration (oxygen debt)","Starch test: iodine solution turns blue-black in presence of starch (photosynthesis test)"]},{"id":7,"num":"Ch 7","subj":"bio","title":"Control & Coordination","oneshot":["Neuron: basic structural and functional unit of nervous system (86 billion in brain)","Reflex arc: Receptor→Afferent nerve→Spinal cord→Efferent nerve→Effector (bypasses brain)","Hormones: chemical messengers; travel in blood; slow but long-lasting effect","Plant hormones: Auxin (cell elongation), Gibberellin (stem growth), Cytokinin (division), ABA (dormancy)"],"keypts":["Neuron parts: Dendrites (receive)→Cell body (process)→Axon (transmit)→Synapse (chemical transfer)","Myelin sheath: speeds impulse conduction; Nodes of Ranvier: gaps allowing saltatory conduction","Synapse: neurotransmitters (acetylcholine) diffuse across 20nm gap; ONE-WAY transmission","Brain: Cerebrum=thinking/memory | Cerebellum=balance/coordination | Medulla=heartbeat/breathing","Pituitary = master gland; controls all other endocrine glands; sits below hypothalamus","Thyroid→thyroxine: metabolism, growth; iodine deficiency → goitre (swollen neck)","Adrenal medulla→adrenaline: fight-or-flight; raises HR, BP, blood glucose","Pancreas: Insulin (lowers blood glucose) | Glucagon (raises blood glucose)","Diabetes mellitus: insufficient insulin → hyperglycaemia (high blood glucose)"],"formulas":"Impulse direction: Dendrites → Cell body → Axon → Synapse → Next neuron's dendrites","exam":["Nervous = fast(ms), electrical, short-lived | Endocrine = slow(min-hrs), chemical, long-lasting","Reflex arc bypasses brain → ultra-fast response → protects from injury","Adrenaline: emergency hormone → glycogen to glucose → more O₂ to muscles → 'fight or flight'"]},{"id":8,"num":"Ch 8","subj":"bio","title":"How Do Organisms Reproduce","oneshot":["Asexual: single parent, no gamete fusion, genetically identical offspring (clones)","Types: Binary fission, Budding, Fragmentation, Regeneration, Spore formation, Vegetative propagation","Sexual: male gamete + female gamete → zygote; creates genetic variation; drives evolution","DNA copying errors = mutations = source of variation = raw material for natural selection"],"keypts":["Amoeba divides in any plane; Leishmania longitudinally (fixed shape); Bacteria transversely","Vegetative: natural = roots(dahlia), stems(potato/ginger), leaves(bryophyllum); artificial = cutting, grafting","Double fertilisation (angiosperms): one gamete+egg→zygote | other+polar nuclei→endosperm (3n)","Testes outside body (in scrotum): sperm needs 2°C lower than body temperature to form","Fallopian tube = site of fertilisation; Uterus = fetal development; Placenta = exchange interface","Placenta: nutrition+O₂ to fetus; CO₂+waste from fetus; also produces HCG and progesterone","Menstrual cycle ≈28 days; ovulation day 14; menstruation if egg not fertilised","Contraception: barrier(condom), hormonal(pill), IUD(Copper-T), surgical(vasectomy/tubectomy)"],"formulas":"Sperm(n, motile, millions) + Egg(n, non-motile, 1/month) → Zygote(2n) → Embryo → Fetus → Baby","exam":["Placenta functions: nutrition, gas exchange, waste removal, immune protection, hormone production","DNA copying not perfect → mutations → variation → evolution fuel (Weismann's experiment with mice)"]},{"id":9,"num":"Ch 9","subj":"bio","title":"Heredity & Evolution","oneshot":["Mendel — Father of Genetics; used Pisum sativum (pea) 1856–1863","Monohybrid F2: 3:1 phenotype (1TT:2Tt:1tt genotype)","Dihybrid F2: 9:3:3:1 (TtRr × TtRr)","Evolution: gradual heritable change in populations over many generations; Darwin: natural selection"],"keypts":["Dominant(T): expressed in TT and Tt | Recessive(t): expressed ONLY in tt","Law of Segregation: alleles separate during gamete formation (purity of gametes)","Law of Independent Assortment: different genes on different chromosomes assort independently","Sex determination: mother's egg always X; father's sperm X(→girl) or Y(→boy)","Chromosomes: 46 = 22 pairs autosomes + 1 pair sex chromosomes (XX or XY)","Acquired traits NOT inherited: scars, muscle mass, skills — Weismann's tail-cutting experiment proved this","Homologous organs: same structure, different function → divergent evolution, common ancestry","Analogous organs: different structure, same function → convergent evolution (no common ancestor)","Fossils: older fossils in deeper rock layers; shows evolutionary history of life","Natural selection: variation → struggle for existence → survival of fittest → reproduction → trait spreads"],"formulas":"Tt×Tt → 1TT:2Tt:1tt = 3 Tall:1 Short\nTtRr×TtRr → 9T_R_:3T_rr:3ttR_:1ttrr (9:3:3:1)","exam":["Mendel's success: large samples + chose traits on different chromosomes (independent assortment)","Father determines sex: XX=girl, XY=boy; mother cannot be blamed for baby's sex!","Lamarck (wrong): acquired traits inherited | Darwin (correct): natural selection on variation"]},{"id":10,"num":"Ch 10","subj":"phy","title":"Light — Reflection & Refraction","oneshot":["Laws of Reflection: ∠i=∠r; incident ray, reflected ray, normal — all coplanar","Refraction: light bends at interface; denser medium → bends toward normal, speed decreases","Snell's Law: n₁ sinθ₁ = n₂ sinθ₂; refractive index n = c/v = sin i / sin r","Lens formula: 1/v − 1/u = 1/f | Mirror formula: 1/v + 1/u = 1/f"],"keypts":["Concave mirror (converging): virtual erect magnified inside F; real inverted outside F; uses: torch, shaving","Convex mirror (diverging): ALWAYS virtual, erect, diminished; wider FOV; uses: rear-view, security","Sign convention: object distance u always –ve; concave mirror f = –ve; convex lens f = +ve","Power of lens P = 1/f(m); unit = Dioptre (D); convex=+ve; concave=–ve; P_total=P₁+P₂","Refractive indices: water=4/3, glass≈1.5, diamond=2.42 (highest common material)","Speed of light: vacuum = 3×10⁸ m/s; v = c/n in any medium","Total Internal Reflection: denser→rarer; angle > critical angle; optical fibres, diamond brilliance"],"formulas":"Mirror: 1/v + 1/u = 1/f, f = R/2, m = –v/u\nLens: 1/v – 1/u = 1/f, m = v/u\nSnell: n₁sinθ₁ = n₂sinθ₂\nP(D) = 1/f(m); P_total = P₁+P₂","exam":["Concave mirror: beyond C→between C&F | at C→at C | at F→infinity | inside F→virtual erect mag.","Convex lens: inside F→virtual erect mag.(magnifying glass) | at 2F→real inverted same size","m>0=virtual,erect | m<0=real,inverted | |m|>1=magnified | |m|<1=diminished"]},{"id":11,"num":"Ch 11","subj":"phy","title":"Human Eye & The Colourful World","oneshot":["Eye: Cornea→Iris/Pupil→Lens→Vitreous humour→Retina→Optic nerve→Brain","Myopia (short-sight): image BEFORE retina; corrected by CONCAVE lens (–ve power)","Hypermetropia (long-sight): image BEHIND retina; corrected by CONVEX lens (+ve power)","VIBGYOR: violet deviates MOST through prism (shortest λ); red deviates LEAST"],"keypts":["Retina: rods (dim/B&W vision) + cones (colour/bright light); fovea = maximum acuity","Near point (LDDV) = 25 cm normal; Far point = infinity; presbyopia → LDDV increases with age","Rayleigh scattering: scattering ∝ 1/λ⁴ → blue light scattered ~10× more than red","Blue sky: blue light scattered by air molecules in all directions → sky looks blue","Red sunrise/sunset: long atmospheric path → blue scattered away → only red/orange survives","Stars twinkle: point sources → atmospheric fluctuations cause shimmer; planets (discs) don't twinkle","Tyndall effect: light scattering by colloidal particles (fog, smoke, milk) — beam becomes visible","Rainbow: refraction + TIR + dispersion by water droplets; violet inside, red outside"],"formulas":"Visible spectrum: Violet(400nm)→Red(700nm)  [VIBGYOR]\nScattering ∝ 1/λ⁴  (Rayleigh — shorter λ scatters far more)","exam":["Danger signals RED: longest λ → least scattered in fog/rain → visible from far","Myopia: eyeball too long OR lens too curved | Hypermetropia: eyeball too short OR lens too flat","Tyndall effect in daily life: blue sky, dusty room sunbeam, car headlights in fog"]},{"id":12,"num":"Ch 12","subj":"phy","title":"Electricity","oneshot":["Current I = Q/t (Ampere); Potential difference V = W/Q (Volt); Ohm's Law: V = IR","Series: R_total = R₁+R₂+R₃ (same I through all; one fails → all fail)","Parallel: 1/R = 1/R₁+1/R₂+... (same V; one fails → rest work; household wiring)","Joule's Law: H = I²Rt = VIt = V²t/R; Power P = VI = I²R = V²/R"],"keypts":["Ammeter: series (low R); Voltmeter: parallel (high R); never swap them!","Resistance R = ρL/A; ρ = resistivity; R increases with temp. for metals (decreases for semiconductors)","1 kWh = 3.6×10⁶ J = 1 commercial unit of electricity","Fuse: Sn+Pb alloy (low MP); melts when excess current flows; ALWAYS in live wire","MCB: can be reset; fuse must be replaced — both protect against overcurrent","Nichrome: high resistivity + very high MP → ideal for heating elements (heater, iron, toaster)","Earth wire (green): safety path for leakage current; prevents electric shock","Tungsten filament: MP = 3422°C (highest), high resistivity, ductile → incandescent bulb"],"formulas":"I=Q/t; V=W/Q; V=IR\nR=ρL/A\nH=I²Rt (Joule's Law)\nP=VI=I²R=V²/R\n1kWh = 3.6×10⁶ J","exam":["Series: same current, voltages add, R increases, one failure stops all","Parallel: same voltage, currents add, R decreases, independent operation (household use)","2 equal bulbs in parallel: each gets full 220V; in series: each gets 110V → dimmer"]},{"id":13,"num":"Ch 13","subj":"phy","title":"Magnetic Effects of Electric Current","oneshot":["Oersted (1820): current-carrying wire creates magnetic field around it","Right-hand thumb rule: thumb=current direction; curled fingers=B field direction","Fleming's Left-Hand rule (motor—FBI): Forefinger=B, Middle=I, Thumb=Force","Faraday: changing magnetic flux through a coil induces an EMF (electromagnetic induction)"],"keypts":["Field lines: closed loops N→S outside; non-intersecting; closer = stronger field","Straight conductor: concentric circular field; ∝ current; ∝ 1/distance","Solenoid: uniform field inside (like bar magnet); N pole where current anticlockwise","Electromagnet: iron core in solenoid; temporary; strength ∝ current and turns","DC motor: electrical→mechanical; split-ring commutator reverses current every half rotation","AC generator: mechanical→electrical; slip rings give continuous AC; Fleming's Right-Hand rule","Domestic AC: 220V, 50Hz; Live=red, Neutral=black, Earth=green","AC preferred for long-distance: transformers step up V → less I → less I²R losses in wires","Short circuit: live+neutral touch → huge current → fire; fuse/MCB prevents this"],"formulas":"F = BIL sinθ  (force on conductor in field)\nf = 50 Hz, V = 220V  (India domestic supply)","exam":["AC vs DC: AC alternates 50×/sec; DC flows one way; batteries=DC, generators=AC","Transformer only works with AC (changing flux needed to induce EMF in secondary coil)","MRI: superconducting electromagnets | Loudspeakers: permanent magnets with coils"]},{"id":14,"num":"Ch 14","subj":"bio","title":"Our Environment","oneshot":["Ecosystem: biotic (living) + abiotic (non-living) components interacting as a system","Lindemann's 10% Law: only 10% energy passes to next trophic level; 90% lost as heat","Biodegradable: decomposed by microbes; Non-biodegradable: persists (DDT, plastics, heavy metals)","CFCs deplete ozone layer → more UV-B → skin cancer, cataracts, crop damage"],"keypts":["Trophic levels: Producers(1st)→Herbivores(2nd)→Primary carnivores(3rd)→Top carnivores(4th)","Food web: interconnected food chains; more complex = more stable ecosystem","10% law: 10,000J at producers → 1,000 herbivores → 100 1° carnivores → 10 top carnivores","Food chains limited to 4–5 levels: too little energy remains for another level","Biomagnification: DDT/mercury concentrates at higher levels; top predators worst affected","Decomposers (bacteria+fungi): break down dead matter → return inorganic nutrients to soil","Without decomposers: dead matter piles up, nutrients locked, producers starved → ecosystem collapses","Ozone layer: O₃ in stratosphere; CFCs (from ACs/fridges) → Cl radicals → O₃ destruction","3R principle: Reduce (use less) → Reuse (use again) → Recycle (make new from old)"],"formulas":"Energy at level n = (0.1)ⁿ × Producers' energy\nFood chain: Grass→Grasshopper→Frog→Snake→Eagle","exam":["DDT biomagnification: 0.003ppm(water)→76ppm(fish-eating birds) → 25,000× concentration!","Food chain limited to 4–5 levels: 10,000J→1,000→100→10→1J — not enough for another level","Nuclear waste: most dangerous non-biodegradable waste; radioactive for thousands of years"]}];
export const MCQS: MCQ[] = [{"id":1,"ch":1,"subj":"chem","diff":"easy","q":"Magnesium ribbon is rubbed with sandpaper before burning to:","opts":["Make it lighter","Remove the basic magnesium carbonate coating","Increase its surface area","Improve conductivity"],"ans":1,"exp":"Magnesium ribbon is coated with basic magnesium carbonate which would react differently. Rubbing removes this coating, allowing pure Mg to burn cleanly with a bright white flame."},{"id":2,"ch":1,"subj":"chem","diff":"easy","q":"CaCO₃ →(heat) CaO + CO₂ is an example of:","opts":["Combination reaction","Double displacement","Thermal decomposition","Redox reaction"],"ans":2,"exp":"A single compound (CaCO₃) breaks down into simpler products on heating. This is thermal decomposition. Used industrially to make quicklime (CaO) for construction."},{"id":3,"ch":1,"subj":"chem","diff":"medium","q":"Photosynthesis is which type of reaction?","opts":["Exothermic and displacement","Endothermic and combination","Exothermic and combination","Endothermic and decomposition"],"ans":1,"exp":"Photosynthesis requires solar energy (endothermic) and combines CO₂+H₂O into glucose (combination reaction). Energy is stored in chemical bonds of glucose."},{"id":4,"ch":1,"subj":"chem","diff":"easy","q":"In Zn + CuSO₄ → ZnSO₄ + Cu, we can conclude that:","opts":["Cu is more reactive than Zn","Zn is MORE reactive than Cu","Both are equally reactive","Reaction is endothermic"],"ans":1,"exp":"Zinc displaces copper from copper sulphate solution because Zn is higher in the activity series (more reactive). Only a more reactive metal can displace a less reactive one from its salt solution."},{"id":5,"ch":1,"subj":"chem","diff":"easy","q":"Rancidity in foods CANNOT be prevented by:","opts":["Adding antioxidants","Airtight packaging","Adding large amounts of water","Refrigeration"],"ans":2,"exp":"Water does not prevent rancidity — it can even accelerate hydrolytic rancidity. Antioxidants, airtight containers (exclude O₂), refrigeration (slow oxidation), and nitrogen flushing all help prevent rancidity."},{"id":6,"ch":2,"subj":"chem","diff":"easy","q":"Which acid is present in vinegar?","opts":["Hydrochloric acid","Acetic acid (ethanoic acid)","Sulphuric acid","Citric acid"],"ans":1,"exp":"Vinegar contains 5–8% acetic acid (ethanoic acid, CH₃COOH). Pure acetic acid is called glacial acetic acid and freezes at 290K (17°C). It is a weak acid."},{"id":7,"ch":2,"subj":"chem","diff":"easy","q":"The pH of a neutral solution is:","opts":["0","14","7","1"],"ans":2,"exp":"pH 7 = neutral. [H⁺] = [OH⁻] = 10⁻⁷ mol/L. pH below 7 = acidic; above 7 = basic/alkaline. pH scale runs 0–14 at 25°C. Pure water is neutral (pH 7)."},{"id":8,"ch":2,"subj":"chem","diff":"medium","q":"Baking powder contains baking soda plus:","opts":["NaOH","Tartaric acid","Na₂CO₃","CaCO₃"],"ans":1,"exp":"Baking powder = NaHCO₃ + tartaric acid. When heated, NaHCO₃ + H⁺ → CO₂ gas released → batter rises and becomes fluffy. The acid prevents the soapy taste that NaHCO₃ alone would give."},{"id":9,"ch":2,"subj":"chem","diff":"medium","q":"The formula of Plaster of Paris is:","opts":["CaSO₄·2H₂O","CaSO₄·½H₂O","Ca(OH)₂","CaCO₃"],"ans":1,"exp":"Plaster of Paris = CaSO₄·½H₂O (calcium sulphate hemihydrate). PoP + H₂O → Gypsum (CaSO₄·2H₂O) which sets hard. Gypsum is heated to 120°C to make PoP. Used in plaster casts and moulds."},{"id":10,"ch":2,"subj":"chem","diff":"easy","q":"Phenolphthalein indicator turns _____ in a basic solution:","opts":["Red","Yellow","Pink/Magenta","Blue"],"ans":2,"exp":"Phenolphthalein: colourless in acidic/neutral solutions, turns pink/magenta in basic solutions. Used in titrations. Litmus turns blue in base but phenolphthalein gives sharper endpoint detection."},{"id":11,"ch":3,"subj":"chem","diff":"easy","q":"Which non-metal conducts electricity?","opts":["Sulfur","Phosphorus","Iodine","Graphite"],"ans":3,"exp":"Graphite (allotrope of carbon) is the only non-metal that conducts electricity. Each C atom forms 3 bonds; the 4th electron is delocalised and free to carry charge. Used as electrodes and in pencils."},{"id":12,"ch":3,"subj":"chem","diff":"easy","q":"Sodium is stored in kerosene because:","opts":["Kerosene increases sodium's density","Sodium catches fire on contact with air/water","Sodium dissolves in kerosene","Kerosene prevents tarnishing"],"ans":1,"exp":"Sodium is extremely reactive — it ignites spontaneously in air and reacts explosively with water (2Na+2H₂O→2NaOH+H₂). Kerosene is a non-reactive alkane that keeps Na isolated from air and moisture."},{"id":13,"ch":3,"subj":"chem","diff":"medium","q":"The most abundant metal in Earth's crust is:","opts":["Iron","Silicon","Aluminium","Calcium"],"ans":2,"exp":"Aluminium makes up ~8% of Earth's crust — the most abundant metal. Its ore is bauxite (Al₂O₃·2H₂O). It is extracted by electrolysis (Hall-Héroult process) because it's too reactive for carbon reduction."},{"id":14,"ch":3,"subj":"chem","diff":"medium","q":"Thermite reaction (2Al + Fe₂O₃ → Al₂O₃ + 2Fe) occurs because:","opts":["Al has lower MP than Fe","Al is MORE reactive than Fe and displaces it","Al is amphoteric","Fe₂O₃ is unstable"],"ans":1,"exp":"Aluminium is above iron in the activity series. More reactive metals displace less reactive metals from their oxides. The tremendous heat produced in this redox reaction melts the iron, which is used to weld railway tracks."},{"id":15,"ch":3,"subj":"chem","diff":"medium","q":"Copper does NOT react with dilute H₂SO₄ because:","opts":["Cu is a noble metal","Cu is BELOW hydrogen in the activity series","Cu forms a protective layer","Cu is too dense"],"ans":1,"exp":"Only metals ABOVE hydrogen in the activity series can displace H⁺ from dilute acids. Since Cu < H in reactivity, it cannot produce H₂ from dilute acids. Cu reacts with concentrated HNO₃ or hot conc. H₂SO₄."},{"id":16,"ch":4,"subj":"chem","diff":"easy","q":"The functional group –CHO is:","opts":["Alcohol","Aldehyde","Carboxylic acid","Ketone"],"ans":1,"exp":"–CHO (terminal carbonyl) = aldehyde. –OH = alcohol; –COOH = carboxylic acid; –CO– (non-terminal) = ketone. Ethanal (CH₃CHO) has –CHO and is oxidised to acetic acid by KMnO₄."},{"id":17,"ch":4,"subj":"chem","diff":"easy","q":"Soap does not lather well in hard water because:","opts":["Hard water is acidic","Ca²⁺/Mg²⁺ form insoluble scum with soap","Soap dissolves too readily","Hard water is alkaline"],"ans":1,"exp":"Ca²⁺ and Mg²⁺ in hard water react with soap (sodium stearate) → insoluble calcium/magnesium stearate (white scum). This wastes soap and leaves residue on clothes/skin. Detergents avoid this."},{"id":18,"ch":4,"subj":"chem","diff":"medium","q":"Catalyst used in hydrogenation of vegetable oils is:","opts":["Platinum","Palladium","Nickel","Iron"],"ans":2,"exp":"Nickel (Ni) at ~200°C is the industrial catalyst for hydrogenating vegetable oils into saturated fats (vanaspati ghee). Pt and Pd also work but are too expensive. This is an addition reaction."},{"id":19,"ch":4,"subj":"chem","diff":"medium","q":"Esterification is the reaction between:","opts":["Two alcohols","Alcohol + carboxylic acid","Alcohol + aldehyde","Two acids"],"ans":1,"exp":"Esterification: alcohol + carboxylic acid →(H⁺, heat) ester + water. Example: C₂H₅OH + CH₃COOH → CH₃COOC₂H₅ (ethyl acetate, sweet fruity smell) + H₂O. Catalyst: conc. H₂SO₄."},{"id":20,"ch":4,"subj":"chem","diff":"medium","q":"The simplest alkyne is:","opts":["Methane","Ethene","Ethyne (acetylene)","Propyne"],"ans":2,"exp":"Ethyne (acetylene, C₂H₂) is the simplest alkyne with a C≡C triple bond. Alkynes: CₙH₂ₙ₋₂. Methane = alkane; ethene = alkene. Acetylene burns at 3500°C — used in oxy-acetylene welding."},{"id":21,"ch":5,"subj":"chem","diff":"easy","q":"Modern Periodic Law states properties are periodic function of:","opts":["Atomic mass","Atomic radius","Atomic number","Valency"],"ans":2,"exp":"Moseley (1913) showed atomic number (number of protons) is the true basis. This resolved anomalies in Mendeleev's table — Ar(18) before K(19), Co(27) before Ni(28), Te(52) before I(53) all correct by atomic number."},{"id":22,"ch":5,"subj":"chem","diff":"easy","q":"Mendeleev arranged elements by:","opts":["Atomic number","Increasing atomic mass","Electronic configuration","Density"],"ans":1,"exp":"Mendeleev (1869) arranged 63 known elements by increasing atomic mass and noticed periodic repetition of properties. He placed elements with similar properties in the same vertical groups."},{"id":23,"ch":5,"subj":"chem","diff":"easy","q":"Atomic size across a period (left to right):","opts":["Increases","Stays same","Decreases","First decreases then increases"],"ans":2,"exp":"Across a period: atomic number increases → more protons → stronger nuclear pull on same shells → electrons drawn closer → atomic radius decreases. Smallest in Period 2 is fluorine (F)."},{"id":24,"ch":5,"subj":"chem","diff":"medium","q":"Mendeleev's Eka-silicon prediction corresponds to:","opts":["Silicon","Gallium","Germanium","Arsenic"],"ans":2,"exp":"Mendeleev predicted Eka-silicon in 1871 (mass≈72, density≈5.35). Germanium (Ge) was discovered in 1886 with properties matching almost exactly — vindicating the periodic table and Mendeleev's genius."},{"id":25,"ch":5,"subj":"chem","diff":"easy","q":"Group 17 elements are called:","opts":["Noble gases","Alkali metals","Halogens","Alkaline earth metals"],"ans":2,"exp":"Group 17 = Halogens (F, Cl, Br, I, At). 'Halogen' = salt-former. They have 7 valence electrons, are highly reactive non-metals, and form –1 ions. Group 18 = Noble gases (very stable, rarely react)."},{"id":26,"ch":6,"subj":"bio","diff":"easy","q":"Photosynthesis takes place in:","opts":["Mitochondria","Nucleus","Chloroplast","Ribosome"],"ans":2,"exp":"Chloroplasts contain chlorophyll which captures light energy. Light reactions (splitting water, O₂ production) occur in thylakoids; dark reactions (Calvin cycle, CO₂ fixation) occur in the stroma."},{"id":27,"ch":6,"subj":"bio","diff":"easy","q":"Which enzyme starts starch digestion in the mouth?","opts":["Pepsin","Trypsin","Salivary amylase","Lipase"],"ans":2,"exp":"Salivary amylase (ptyalin) in saliva breaks starch → maltose. Digestion begins in the mouth. Pepsin = stomach (proteins); trypsin and lipase = pancreatic juice (proteins and fats in small intestine)."},{"id":28,"ch":6,"subj":"bio","diff":"easy","q":"The basic filtering unit of the kidney is:","opts":["Alveolus","Villus","Glomerulus","Nephron"],"ans":3,"exp":"Nephron is the structural and functional unit of the kidney (~1 million per kidney). Structure: Bowman's capsule → glomerulus (filtration) → tubule (selective reabsorption) → collecting duct → urine."},{"id":29,"ch":6,"subj":"bio","diff":"easy","q":"During vigorous exercise muscles produce:","opts":["Ethanol + CO₂","Lactic acid","Only glucose","Pyruvate"],"ans":1,"exp":"When O₂ is insufficient, muscles respire anaerobically: Glucose → Lactic acid + 2ATP. Lactic acid accumulates → muscle fatigue and cramps. This is why you feel sore after intense exercise (oxygen debt)."},{"id":30,"ch":6,"subj":"bio","diff":"medium","q":"Pulmonary veins carry blood that is:","opts":["Deoxygenated from body","Oxygenated from lungs to left atrium","Deoxygenated from heart to lungs","Oxygenated from left ventricle to body"],"ans":1,"exp":"Pulmonary veins (4) carry OXYGENATED blood FROM lungs TO left atrium. Key exception: veins don't always carry deoxygenated blood! Pulmonary arteries carry deoxygenated blood TO the lungs."},{"id":31,"ch":7,"subj":"bio","diff":"easy","q":"Which brain part controls balance and coordination?","opts":["Cerebrum","Cerebellum","Medulla oblongata","Hypothalamus"],"ans":1,"exp":"Cerebellum (back/bottom of brain) coordinates voluntary movements, balance, and posture. Damage causes ataxia (unsteady, uncoordinated movements). Cerebrum = thinking; Medulla = heartbeat/breathing."},{"id":32,"ch":7,"subj":"bio","diff":"easy","q":"Insulin is produced by:","opts":["Liver","Kidney","Pancreas","Adrenal gland"],"ans":2,"exp":"Insulin is produced by beta cells of the Islets of Langerhans in the pancreas. It lowers blood glucose by promoting cellular uptake. Insufficient insulin → Diabetes mellitus (hyperglycaemia)."},{"id":33,"ch":7,"subj":"bio","diff":"easy","q":"Iodine deficiency causes:","opts":["Diabetes","Goitre","Dwarfism","Anaemia"],"ans":1,"exp":"Iodine is essential for making thyroxine (thyroid hormone). Without iodine, the thyroid gland enlarges trying to produce more hormone → goitre (swollen neck). Prevention: iodised salt."},{"id":34,"ch":7,"subj":"bio","diff":"medium","q":"The 'fight-or-flight' emergency hormone is:","opts":["Thyroxine","Insulin","Adrenaline","Growth hormone"],"ans":2,"exp":"Adrenaline (epinephrine) from adrenal medulla: increases heart rate, breathing rate, blood pressure, blood glucose; diverts blood to muscles; dilates pupils. Prepares body for emergency action."},{"id":35,"ch":7,"subj":"bio","diff":"medium","q":"Myelin sheath around axons functions to:","opts":["Produce neurotransmitters","Provide nutrition","Speed up nerve impulse conduction","Anchor the neuron"],"ans":2,"exp":"Myelin sheath (made by Schwann cells) electrically insulates the axon. Impulse jumps between Nodes of Ranvier (saltatory conduction) — much faster than unmyelinated fibres. Multiple sclerosis = myelin damage."},{"id":36,"ch":8,"subj":"bio","diff":"easy","q":"Budding as asexual reproduction is seen in:","opts":["Amoeba","Planaria","Hydra","Spirogyra"],"ans":2,"exp":"Hydra reproduces by budding — a bud forms on the parent body, develops tentacles, and detaches as a new individual. Yeast also buds. Amoeba = binary fission; Planaria = regeneration; Spirogyra = fragmentation."},{"id":37,"ch":8,"subj":"bio","diff":"easy","q":"Sex of a human baby is determined by:","opts":["Mother's X chromosome","Father's X or Y in sperm","Both parents equally","Environmental temperature"],"ans":1,"exp":"Mother's egg always carries X. Father's sperm carries X (→XX=girl) or Y (→XY=boy). So the FATHER determines sex. The mother cannot be blamed for having daughters — a scientifically important fact!"},{"id":38,"ch":8,"subj":"bio","diff":"easy","q":"Human fertilisation normally occurs in the:","opts":["Uterus","Ovary","Fallopian tube","Cervix"],"ans":2,"exp":"Fertilisation (sperm + egg → zygote) occurs in the upper fallopian tube. The zygote travels to the uterus over ~7 days while dividing, then implants in the uterine wall as a blastocyst."},{"id":39,"ch":8,"subj":"bio","diff":"hard","q":"Amoeba's binary fission differs from Leishmania's because:","opts":["Amoeba divides only longitudinally","Amoeba divides in ANY plane","Amoeba undergoes multiple fission","Leishmania is faster"],"ans":1,"exp":"Amoeba has no fixed shape → binary fission in any plane. Leishmania has a definite shape with a flagellum at one end → divides LONGITUDINALLY only. Paramecium divides transversely."},{"id":40,"ch":8,"subj":"bio","diff":"easy","q":"Main function of the placenta is:","opts":["Produce sperm","Site of fertilisation","Exchange of nutrients/gases/waste between mother and fetus","Store eggs"],"ans":2,"exp":"Placenta is attached to uterine wall, connected to fetus by umbilical cord. Allows: glucose/amino acids/O₂/antibodies from mother to fetus; CO₂/urea from fetus to mother. Blood supplies remain separate."},{"id":41,"ch":9,"subj":"bio","diff":"easy","q":"Phenotypic ratio in F2 of Tt × Tt is:","opts":["1:1","1:2:1","3:1","9:3:3:1"],"ans":2,"exp":"Tt × Tt → 1TT + 2Tt + 1tt. TT and Tt both = Tall (T dominant); tt = Dwarf. Phenotypic ratio = 3 Tall : 1 Dwarf = 3:1. Genotypic ratio = 1:2:1. This confirmed Mendel's Law of Segregation."},{"id":42,"ch":9,"subj":"bio","diff":"easy","q":"Total chromosomes in a normal human cell are:","opts":["46","44","48","23"],"ans":0,"exp":"46 chromosomes = 23 pairs. 22 pairs = autosomes; 1 pair = sex chromosomes (XX female or XY male). Gametes (haploid) have 23 chromosomes. Fertilisation restores diploid (2n=46) number."},{"id":43,"ch":9,"subj":"bio","diff":"medium","q":"Homologous organs indicate which type of evolution?","opts":["Convergent","Divergent (common ancestry)","No evolutionary link","Parallel"],"ans":1,"exp":"Homologous organs (same basic structure, different function — e.g., human arm, bat wing, whale flipper) show divergent evolution from a COMMON ANCESTOR. Analogous organs = convergent evolution (no common ancestor)."},{"id":44,"ch":9,"subj":"bio","diff":"easy","q":"Theory of Natural Selection was proposed by:","opts":["Mendel","Lamarck","Charles Darwin","Hugo de Vries"],"ans":2,"exp":"Darwin (1859, 'On the Origin of Species'): natural variation → struggle for existence → better-adapted individuals survive and reproduce more → traits spread in population over generations."},{"id":45,"ch":9,"subj":"bio","diff":"medium","q":"Weismann's tail-cutting experiment in mice proved:","opts":["Lamarck's theory of acquired traits","Acquired traits are NOT inherited","Mutations cause evolution","Natural selection is correct"],"ans":1,"exp":"Weismann cut mouse tails for 22 generations. Offspring always had normal tails. This proved that acquired characteristics (changes during lifetime) are NOT encoded in germ cells and CANNOT be inherited."},{"id":46,"ch":10,"subj":"phy","diff":"easy","q":"A concave mirror with R=40cm has focal length:","opts":["40 cm","20 cm","80 cm","10 cm"],"ans":1,"exp":"f = R/2 = 40/2 = 20 cm. Focal length is always half the radius of curvature for spherical mirrors. For a concave mirror, this is a real focus where parallel rays converge after reflection."},{"id":47,"ch":10,"subj":"phy","diff":"easy","q":"Convex mirrors are used as rear-view mirrors because they:","opts":["Give magnified real images","Give virtual, erect, diminished images with wide FOV","Give real same-size images","Give virtual inverted images"],"ans":1,"exp":"Convex mirrors always produce virtual, erect, diminished images regardless of object position. The smaller image captures a wider field of view — driver can see more of the road behind in a small mirror."},{"id":48,"ch":10,"subj":"phy","diff":"easy","q":"SI unit of power of a lens is:","opts":["Metre","Watt","Dioptre","Newton"],"ans":2,"exp":"Power P = 1/f(metres). SI unit = Dioptre (D) = m⁻¹. Convex lens = +ve power; concave = –ve. A +2D lens has f = 0.5m = 50cm. P_combined = P₁+P₂ for lenses in contact."},{"id":49,"ch":10,"subj":"phy","diff":"medium","q":"Light going from glass(n=1.5) to air(n=1):","opts":["Goes straight","Bends toward normal","Bends AWAY from normal","Is totally absorbed"],"ans":2,"exp":"Denser→rarer medium: light bends AWAY from normal (angle of refraction > angle of incidence). If angle exceeds critical angle (~42° for glass-air), total internal reflection occurs — no refraction at all."},{"id":50,"ch":10,"subj":"phy","diff":"medium","q":"A convex lens of f=25cm has power:","opts":["+4 D","-4 D","+0.04 D","-0.04 D"],"ans":0,"exp":"P = 1/f(m) = 1/0.25 = +4 D. Positive because convex lens is converging. f = 25cm = 0.25m. A person with +4D glasses has hypermetropia (long-sightedness). P is always in Dioptres."},{"id":51,"ch":11,"subj":"phy","diff":"easy","q":"Cannot see distant objects clearly — this defect is:","opts":["Hypermetropia","Presbyopia","Myopia","Astigmatism"],"ans":2,"exp":"Myopia (short-sightedness): image forms BEFORE retina. Cannot see far clearly; near objects fine. Cause: eyeball too long OR lens too curved. Correction: concave (diverging) lens with –ve power."},{"id":52,"ch":11,"subj":"phy","diff":"easy","q":"Sky appears blue because:","opts":["Sky absorbs all except blue","Blue light scattered MORE by air particles (Rayleigh)","Blue has lowest energy","Water vapour is blue"],"ans":1,"exp":"Rayleigh scattering: scattering ∝ 1/λ⁴. Blue light (λ≈450nm) scattered ~10× more than red (λ≈700nm) by air molecules. This scattered blue light comes from all sky directions → sky appears blue."},{"id":53,"ch":11,"subj":"phy","diff":"easy","q":"Colour that deviates LEAST through a prism:","opts":["Violet","Green","Yellow","Red"],"ans":3,"exp":"Red has longest wavelength (700nm) → smallest refractive index → least refraction → least deviation. VIBGYOR: Violet deviates most (400nm), Red least (700nm). Remember: longer wavelength = less deviation."},{"id":54,"ch":11,"subj":"phy","diff":"easy","q":"Least distance of distinct vision (LDDV) for normal eye:","opts":["10 cm","25 cm","50 cm","100 cm"],"ans":1,"exp":"LDDV = 25 cm = near point of normal eye. Objects closer than 25 cm cannot be focused clearly even with maximum accommodation. LDDV increases with age (presbyopia) — reading glasses needed."},{"id":55,"ch":11,"subj":"phy","diff":"hard","q":"Stars twinkle but planets don't because:","opts":["Stars are brighter","Stars appear as point sources; planets as small discs","Planets emit their own light","Stars are moving"],"ans":1,"exp":"Stars are so far away they appear as point sources. Tiny atmospheric fluctuations randomly shift their light path → twinkling. Planets appear as tiny discs — fluctuations from different disc points average out → no twinkle."},{"id":56,"ch":12,"subj":"phy","diff":"easy","q":"SI unit of electric resistance:","opts":["Ampere","Volt","Coulomb","Ohm (Ω)"],"ans":3,"exp":"Ohm (Ω), named after Georg Simon Ohm. 1 Ω = 1 V/A (from V=IR). Resistance opposes flow of electric current. Resistivity (ρ) is the material property; R = ρL/A depends on geometry too."},{"id":57,"ch":12,"subj":"phy","diff":"medium","q":"Three 6Ω resistors in parallel have effective resistance:","opts":["18 Ω","6 Ω","3 Ω","2 Ω"],"ans":3,"exp":"1/R = 1/6+1/6+1/6 = 3/6 = 1/2 → R = 2Ω. For n equal resistors in parallel: R_eff = R/n = 6/3 = 2Ω. Parallel effective R is ALWAYS less than the smallest individual resistance."},{"id":58,"ch":12,"subj":"phy","diff":"medium","q":"1 kilowatt-hour equals:","opts":["1000 J","1000 W","3.6 × 10⁶ J","3.6 × 10³ J"],"ans":2,"exp":"1 kWh = 1000 W × 3600 s = 3.6×10⁶ J. This is the commercial 'unit' of electricity. A 1000W appliance running 1 hour uses 1 unit = ₹ whatever the tariff is."},{"id":59,"ch":12,"subj":"phy","diff":"medium","q":"Tungsten is used in bulb filaments because:","opts":["Low resistivity and MP","Very high MP (3422°C), high resistivity, doesn't oxidise","Low cost","Perfect conductor"],"ans":1,"exp":"Tungsten: MP=3422°C (highest of all metals), high resistivity (heats up), ductile (drawn into thin wire), doesn't oxidise in argon gas fill. Perfect for glowing at ~2500°C without melting."},{"id":60,"ch":12,"subj":"phy","diff":"easy","q":"The green wire in household wiring is:","opts":["Live wire (220V)","Neutral wire (0V)","Earth wire (safety)","Fuse wire"],"ans":2,"exp":"Colour code: Live = Red (220V, dangerous), Neutral = Black (0V), Earth = Green (safety). Earth wire connects metal body of appliances to ground. Leakage current flows safely to earth → prevents electric shock."},{"id":61,"ch":13,"subj":"phy","diff":"easy","q":"Electromagnetic induction was discovered by:","opts":["Michael Faraday","Oersted","Maxwell","Nikola Tesla"],"ans":0,"exp":"Faraday (1831): changing magnetic flux through a conductor induces an EMF. This is the basis of generators, transformers, and electric power distribution. Lenz's law describes the direction of induced current."},{"id":62,"ch":13,"subj":"phy","diff":"easy","q":"An electric motor converts:","opts":["Mechanical → Electrical","Electrical → Mechanical","Chemical → Electrical","Heat → Mechanical"],"ans":1,"exp":"Electric motor converts electrical energy → mechanical energy (rotation). Principle: force on current-carrying conductor in magnetic field (F=BIL, Fleming's Left-Hand rule). Used in fans, pumps, EVs."},{"id":63,"ch":13,"subj":"phy","diff":"easy","q":"Frequency of AC supply in India is:","opts":["60 Hz","100 Hz","50 Hz","25 Hz"],"ans":2,"exp":"India: 50 Hz, 220V AC. Current alternates direction 50 times per second (50 complete cycles). USA uses 60 Hz, 110V. The frequency affects motor speeds and transformer design."},{"id":64,"ch":13,"subj":"phy","diff":"medium","q":"Fleming's Left-Hand Rule finds the direction of:","opts":["Induced current in generator","Magnetic field around a wire","Force on current-carrying conductor in field","EMF"],"ans":2,"exp":"Fleming's Left-Hand Rule (for MOTORS): Forefinger=Field(B), Middle finger=Current(I), Thumb=Force/Thrust. Mnemonic: FBI. Fleming's Right-Hand Rule is for generators (finding induced current direction)."},{"id":65,"ch":13,"subj":"phy","diff":"medium","q":"AC is preferred for long-distance power transmission because:","opts":["AC has higher voltage","Transformers easily step up/down AC, reducing I²R losses","AC is safer","DC can't travel far"],"ans":1,"exp":"Step-up transformer raises AC to very high voltage (400kV) for transmission → lower current → much less I²R heat loss in wires. Step-down at destination. Transformers ONLY work with AC (changing current needed)."},{"id":66,"ch":14,"subj":"bio","diff":"easy","q":"Energy transferred to next trophic level is:","opts":["90%","50%","10%","1%"],"ans":2,"exp":"Lindemann's 10% Law: only 10% of energy at one level transfers to the next. 90% is lost as heat through respiration, movement, excretion, and undigested material. This limits food chain length."},{"id":67,"ch":14,"subj":"bio","diff":"easy","q":"Ozone layer is mainly depleted by:","opts":["Carbon dioxide","Sulphur dioxide","CFCs","Methane"],"ans":2,"exp":"CFCs (from ACs, fridges, aerosols) rise to stratosphere → UV breaks them → Cl radicals released → Cl+O₃→ClO+O₂. One Cl atom can destroy up to 100,000 O₃ molecules! Montreal Protocol (1987) banned CFCs."},{"id":68,"ch":14,"subj":"bio","diff":"easy","q":"Decomposers in an ecosystem are mainly:","opts":["Plants and animals","Bacteria and fungi","Insects and worms","Algae"],"ans":1,"exp":"Decomposers (saprotrophs) — bacteria and fungi — break down dead organic matter externally into simple inorganic molecules. They return nutrients (N, P, K) to soil, completing nutrient cycles essential for producers."},{"id":69,"ch":14,"subj":"bio","diff":"medium","q":"Biological magnification means:","opts":["Organisms grow larger up food chain","Non-biodegradable chemicals become MORE concentrated at higher trophic levels","Energy increases up food chain","Biodiversity increases upward"],"ans":1,"exp":"Biomagnification: non-biodegradable fat-soluble chemicals (DDT, Hg, PCBs) accumulate in organisms and multiply at each level as each eats many of the lower level. Top predators get highest concentrations."},{"id":70,"ch":14,"subj":"bio","diff":"medium","q":"Food chains are rarely longer than 4–5 levels because:","opts":["Top predators eat all","Only 10% energy passes to each level — too little energy remains","Plants can't support more","All top predators are huge"],"ans":1,"exp":"10% law: 10,000J(producers)→1,000(herbivores)→100(1°carnivores)→10(top carnivores)→1J(5th level). Such tiny amounts cannot sustain a viable population at a 5th or 6th level. Energy simply runs out."},{"id":1001,"ch":10,"subj":"phy","diff":"medium","q":"An object is placed 20cm from a concave mirror of focal length 15cm. The image forms at:","opts":["-60cm (real, beyond C)","-12cm (virtual)","+60cm (behind mirror)","-30cm (at C)"],"ans":0,"exp":"1/v = 1/f – 1/u = 1/(–15) – 1/(–20) = –4/60+3/60 = –1/60 → v=–60cm. Object is between F(15cm) and C(30cm), so image forms beyond C: real, inverted, magnified — matches v=–60cm."},{"id":1002,"ch":10,"subj":"phy","diff":"medium","q":"Speed of light in a glass slab of refractive index 1.5 is (c = 3×10⁸ m/s):","opts":["2×10⁸ m/s","4.5×10⁸ m/s","1.5×10⁸ m/s","3×10⁸ m/s"],"ans":0,"exp":"n = c/v → v = c/n = (3×10⁸)/1.5 = 2×10⁸ m/s. Light always slows down entering a denser medium — speed in glass is 2/3 its speed in vacuum/air."},{"id":1003,"ch":10,"subj":"phy","diff":"easy","q":"Dentists use concave mirrors to examine teeth because concave mirrors, when the object is within the focal length, give:","opts":["A virtual, erect, magnified image","A real, inverted, diminished image","A virtual, diminished image","No image at all"],"ans":0,"exp":"Placing the tooth within F of a concave mirror produces a virtual, erect, MAGNIFIED image — exactly what's needed for a close, detailed view. Same principle used in shaving/makeup mirrors."},{"id":1004,"ch":10,"subj":"phy","diff":"medium","q":"When a convex lens forms a REAL image of an object, the magnification (m = v/u) is always:","opts":["Negative","Positive","Zero","Undefined"],"ans":0,"exp":"A real image from a single convex lens is always inverted relative to the object. Since v is +ve (real, other side) and u is –ve (object distance), m=v/u is always negative — confirming inversion, regardless of how magnified or diminished."},{"id":1005,"ch":10,"subj":"phy","diff":"medium","q":"Total internal reflection can occur only when light travels from:","opts":["A denser medium to a rarer medium, beyond the critical angle","A rarer medium to a denser medium","Any medium to any medium at any angle","Vacuum to any medium"],"ans":0,"exp":"TIR needs TWO conditions together: (1) light going denser→rarer, AND (2) angle of incidence exceeding the critical angle. Missing either condition means normal refraction occurs instead."},{"id":1006,"ch":10,"subj":"phy","diff":"easy","q":"Optical fibres, used to transmit telephone/internet signals as light pulses, work on the principle of:","opts":["Total internal reflection","Simple refraction","Dispersion","Diffused reflection"],"ans":0,"exp":"Light entering the fibre's core hits the core-cladding boundary at an angle greater than the critical angle every time, so it's totally internally reflected along the entire fibre length with almost no signal loss."},{"id":1007,"ch":10,"subj":"phy","diff":"medium","q":"A concave LENS, no matter where the object is placed, always forms an image that is:","opts":["Virtual, erect, and diminished","Real, inverted, and magnified","Virtual, inverted, and magnified","Real, erect, and diminished"],"ans":0,"exp":"A concave (diverging) lens always produces a virtual, erect, diminished image between the optical centre and F, on the same side as the object — regardless of object distance. This is why concave lenses correct myopia without ever forming a confusing inverted view."},{"id":1008,"ch":10,"subj":"phy","diff":"hard","q":"Two thin lenses of power +5D and –2D are placed in contact. The focal length of the combination is:","opts":["+33.3 cm (converging)","–33.3 cm (diverging)","+20 cm (converging)","+50 cm (converging)"],"ans":0,"exp":"P_total = P₁+P₂ = 5+(–2) = +3D. f = 1/P = 1/3 m ≈ +0.333m = +33.3cm. Positive power → still a converging (convex-like) combination overall."}];
export const SHORT_QA: QA[] = [{"id":1,"ch":1,"subj":"chem","marks":2,"q":"What is a redox reaction? Give one example.","a":"A redox reaction is one in which oxidation and reduction occur SIMULTANEOUSLY.\n• Oxidation = gain of oxygen / loss of hydrogen / loss of electrons\n• Reduction = loss of oxygen / gain of hydrogen / gain of electrons\n\nExample: ZnO + C → Zn + CO\n• C is oxidised (gains O to become CO)\n• ZnO is reduced (loses O to give Zn)\n\nAnother example: 2Mg + O₂ → 2MgO\nMg is oxidised; O₂ is reduced."},{"id":2,"ch":1,"subj":"chem","marks":2,"q":"Differentiate between corrosion and rancidity.","a":"CORROSION:\n• Slow chemical deterioration of metals by reaction with environment (O₂, moisture)\n• Example: Rusting of iron — Fe + O₂ + H₂O → Fe₂O₃·xH₂O\n• Prevented by: painting, galvanising (Zn coating), electroplating, alloying\n\nRANCIDITY:\n• Oxidation of fats and oils causing unpleasant smell and taste\n• Example: Butter becoming stale; old cooking oil\n• Prevented by: antioxidants, airtight containers, refrigeration, N₂ flushing\n\nKey difference: Corrosion affects METALS; Rancidity affects FOOD (fats/oils)."},{"id":3,"ch":2,"subj":"chem","marks":2,"q":"What is neutralisation? Write the equation for NaOH + HCl.","a":"Neutralisation: Reaction between an acid and a base producing a salt and water. It is exothermic and is a double displacement reaction.\n\nH⁺ (from acid) + OH⁻ (from base) → H₂O\n\nEquation:\nNaOH + HCl → NaCl + H₂O\n(Sodium hydroxide + Hydrochloric acid → Sodium chloride + Water)\n\nApplications:\n• Antacids neutralise excess stomach acid (HCl)\n• Lime (Ca(OH)₂) neutralises soil acidity\n• Toothpaste (basic) neutralises mouth acids"},{"id":4,"ch":2,"subj":"chem","marks":2,"q":"What is water of crystallisation? Give an example.","a":"Water of crystallisation = the fixed, definite number of water molecules chemically incorporated into a salt's crystal lattice structure.\n\nExample: Copper sulphate pentahydrate — CuSO₄·5H₂O\n• Forms beautiful blue crystals\n• CuSO₄·5H₂O →(heat) CuSO₄ (white/colourless) + 5H₂O\n• Adding water to white CuSO₄ → turns blue again (reversible)\n• This test detects presence of water\n\nOther examples:\n• Washing soda: Na₂CO₃·10H₂O\n• Gypsum: CaSO₄·2H₂O\n• Plaster of Paris: CaSO₄·½H₂O"},{"id":5,"ch":3,"subj":"chem","marks":2,"q":"Why does calcium float on water when it reacts with it?","a":"Reaction: Ca + 2H₂O → Ca(OH)₂ + H₂↑\n\nExplanation: Hydrogen gas is produced as bubbles during the reaction. These bubbles attach to the calcium surface, reducing its effective density below that of water. As a result, calcium floats while reacting.\n\nComparison:\n• Sodium: reacts so vigorously that it zooms around the surface (violent)\n• Calcium: reacts more gently, bubbles formed, floats and eventually sinks as Ca(OH)₂ dissolves\n\nThe milky turbidity is due to slightly soluble Ca(OH)₂ (slaked lime)."},{"id":6,"ch":3,"subj":"chem","marks":2,"q":"What are alloys? Give 2 examples with composition and use.","a":"Alloy = a homogeneous mixture of two or more metals (or metal + non-metal), prepared by melting and mixing, then solidifying.\n\nAdvantages over pure metals: greater hardness, corrosion resistance, desired MP, better workability.\n\nExample 1: BRASS = Copper + Zinc\n• Uses: Utensils, electrical fittings, musical instruments, coins\n• Harder than pure copper\n\nExample 2: STAINLESS STEEL = Iron + Chromium + Nickel\n• Uses: Cutlery, surgical instruments, kitchen equipment\n• Highly resistant to rust (Cr forms protective Cr₂O₃ layer)"},{"id":7,"ch":4,"subj":"chem","marks":2,"q":"What is esterification? Write equation for ethanol + acetic acid.","a":"Esterification = reaction between a carboxylic acid and an alcohol to form an ester + water. Catalyst: concentrated H₂SO₄. Condition: heat. It is REVERSIBLE.\n\nEquation:\nC₂H₅OH + CH₃COOH ⇌ CH₃COOC₂H₅ + H₂O\n(Ethanol + Acetic acid ⇌ Ethyl acetate + Water)\n\nEthyl acetate has a sweet fruity smell and is used in:\n• Perfumes and food flavourings\n• Nail polish remover\n• Industrial solvent\n\nReverse reaction (saponification): ester + NaOH → salt of acid + alcohol"},{"id":8,"ch":4,"subj":"chem","marks":2,"q":"Distinguish between soaps and detergents.","a":"SOAPS:\n• Sodium/potassium salts of long-chain fatty acids (RCOONa)\n• Made by saponification (fat + NaOH → soap + glycerol)\n• Do NOT work in hard water — form insoluble scum with Ca²⁺/Mg²⁺\n• Biodegradable ✓; Mild on skin ✓\n\nDETERGENTS:\n• Sodium salts of sulphonic acids (RSO₃Na) — synthetic\n• Made from petroleum products\n• WORK in hard water (–SO₃⁻ doesn't react with Ca²⁺/Mg²⁺)\n• May not be biodegradable (environmental concern)\n• Used in laundry powders, shampoos, dishwashing liquids"},{"id":9,"ch":5,"subj":"chem","marks":2,"q":"State Modern Periodic Law. How did it improve on Mendeleev?","a":"Modern Periodic Law (Moseley, 1913):\n'Physical and chemical properties of elements are periodic functions of their atomic number.'\n\nImprovements over Mendeleev (who used atomic mass):\n\n1. ANOMALOUS PAIRS RESOLVED:\n• Ar(39.9) before K(39.1) — wrong by mass but right by atomic number (18 before 19) ✓\n• Te before I, Co before Ni — all correct by atomic number ✓\n\n2. ISOTOPES HANDLED:\n• Isotopes have SAME atomic number → same position ✓\n• Mendeleev couldn't explain this\n\n3. MORE FUNDAMENTAL:\n• Atomic number (proton count) is unique and unchanging for each element"},{"id":10,"ch":5,"subj":"chem","marks":2,"q":"How does atomic size vary across a period and down a group?","a":"ACROSS A PERIOD (left to right): Atomic size DECREASES\nReason: Atomic number increases → more protons → stronger nuclear pull → same electron shells → electrons drawn closer → smaller atom.\nExample: Li > Be > B > C > N > O > F (Period 2)\n\nDOWN A GROUP (top to bottom): Atomic size INCREASES\nReason: Each new period adds a new electron shell → greater distance from nucleus → larger atom. Also, inner shells shield outer electrons from nuclear pull (screening effect).\nExample: Li < Na < K < Rb < Cs (Group 1)"},{"id":11,"ch":6,"subj":"bio","marks":2,"q":"What is the role of bile in digestion?","a":"Bile = greenish-yellow alkaline fluid made by LIVER, stored in GALL BLADDER, released into duodenum (small intestine).\n\nRoles:\n1. EMULSIFICATION of fats: Bile salts break large fat globules into tiny droplets — massively increases surface area for lipase enzyme to work on.\n\n2. CREATES ALKALINE MEDIUM (pH~8): Neutralises acidic chyme from stomach. Pancreatic enzymes work best in alkaline conditions.\n\n3. BILE PIGMENTS: Bilirubin/biliverdin from broken-down RBCs — excreted in faeces (gives faeces brown colour).\n\nBile does NOT contain enzymes — it works physically/chemically."},{"id":12,"ch":6,"subj":"bio","marks":2,"q":"What is a nephron? Describe its function briefly.","a":"Nephron = basic structural and functional unit of the kidney (~1 million per kidney).\n\nStructure: Bowman's capsule → Glomerulus → Proximal tubule → Loop of Henle → Distal tubule → Collecting duct\n\nFunctions:\n1. ULTRAFILTRATION: Blood filtered under high pressure in glomerulus. Small molecules (glucose, urea, water, salts) pass into Bowman's space.\n\n2. SELECTIVE REABSORPTION: Useful substances (ALL glucose, amino acids, 99% water, essential salts) reabsorbed back into blood in tubules.\n\n3. SECRETION: Excess H⁺, K⁺, some drugs actively secreted into filtrate.\n\nFinal product = urine (water + urea + excess salts) → ureter → bladder → excreted."},{"id":13,"ch":7,"subj":"bio","marks":2,"q":"What is a synapse? What is its role in nerve impulse transmission?","a":"Synapse = microscopic junction/gap (~20nm) between axon terminal of one neuron and dendrite/cell body of the next.\n\nRole in transmission:\n1. Action potential reaches axon terminal → Ca²⁺ influx\n2. Synaptic vesicles release NEUROTRANSMITTERS (e.g., acetylcholine) into synaptic cleft\n3. Neurotransmitters diffuse across the gap\n4. Bind to receptors on postsynaptic membrane\n5. Generate new action potential in next neuron\n6. Neurotransmitters broken down by enzymes (reset for next impulse)\n\nKey importance:\n• Ensures ONE-WAY transmission (vesicles only on presynaptic side)\n• Allows signal amplification, inhibition, and integration"},{"id":14,"ch":7,"subj":"bio","marks":2,"q":"Differentiate between voluntary and involuntary actions.","a":"VOLUNTARY ACTIONS:\n• Performed consciously and deliberately\n• Controlled by CEREBRUM (cerebral cortex)\n• Person can choose to start/stop\n• Examples: Writing, running, speaking, eating\n• Pathway: Sense organ → Brain (cerebrum) → Muscle\n\nINVOLUNTARY ACTIONS:\n• Occur automatically without conscious control\n• Controlled by MEDULLA OBLONGATA or spinal cord\n• Cannot easily be stopped even if you want to\n• Examples: Heartbeat, breathing, peristalsis, sneezing, knee-jerk reflex\n\nKey difference: Voluntary = cerebrum decides; Involuntary = brain stem/spinal cord handles automatically"},{"id":15,"ch":8,"subj":"bio","marks":2,"q":"What is vegetative propagation? Give 2 advantages and 1 disadvantage.","a":"Vegetative propagation = asexual reproduction in plants where new plants grow from vegetative parts (roots, stems, leaves) without seeds.\n\nNatural: Potato (stem tuber), Ginger (rhizome), Bryophyllum (leaf buds), Dahlia (root tuber)\nArtificial: Cutting (rose), Grafting (mango), Layering (jasmine), Tissue culture\n\nADVANTAGES:\n1. Faster reproduction — reaches maturity more quickly than seeds\n2. Exact copy of parent — preserves desirable traits (no variation)\n\nDISADVANTAGE:\nNo genetic variation — all plants are clones → entire crop susceptible to same disease/stress → population collapse risk"},{"id":16,"ch":8,"subj":"bio","marks":2,"q":"What is the placenta? List its four main functions.","a":"Placenta = disc-shaped vascular organ embedded in uterine wall, connected to fetus by umbilical cord.\n\nKey feature: Fetal and maternal blood supplies are SEPARATE — exchange occurs by diffusion across thin membrane.\n\nFour main functions:\n1. NUTRITION: Transfers glucose, amino acids, vitamins, minerals from mother to fetus\n2. GAS EXCHANGE: O₂ from mother to fetus; CO₂ from fetus to mother\n3. EXCRETION: Removes urea and other waste from fetal blood to maternal blood\n4. IMMUNE PROTECTION: Transfers maternal antibodies (IgG) to fetus — passive immunity\n\nAlso produces hormones: HCG (maintains pregnancy), progesterone, oestrogen"},{"id":17,"ch":9,"subj":"bio","marks":2,"q":"Distinguish between inherited and acquired traits with examples.","a":"INHERITED TRAITS:\n• Transmitted from parents to offspring through GENES in DNA\n• Present in germ cells (eggs/sperm) from birth\n• Passed to next generation\n• Examples: Eye colour, blood group, earlobe shape, sickle cell anaemia, colour blindness\n\nACQUIRED TRAITS:\n• Developed during lifetime due to environment, use, or injury\n• NOT encoded in germ cell DNA\n• CANNOT be passed to offspring\n• Examples: Scars, muscular body from exercise, tanned skin, learned skills (playing guitar)\n\nWEISMANN'S PROOF: Cut tails of mice for 22 generations → offspring always had normal tails. Acquired trait NOT inherited."},{"id":18,"ch":9,"subj":"bio","marks":2,"q":"What is natural selection? How does it drive evolution?","a":"Natural selection (Darwin, 1859): Process where individuals with favourable traits survive longer and reproduce more, passing those traits to offspring.\n\nSteps:\n1. VARIATION: Individuals in a population naturally vary (mutations, sexual reproduction)\n2. STRUGGLE: Resources are limited; more offspring born than can survive\n3. SURVIVAL: Individuals with favourable variations survive and reproduce more\n4. INHERITANCE: Favourable traits passed to offspring\n5. ACCUMULATION: Over generations, favourable traits increase in frequency\n\nResult: Population gradually changes → eventually a new species may form (SPECIATION).\n\nExample: Antibiotic resistance in bacteria — random mutations → some survive antibiotic → reproduce → resistant strain spreads."},{"id":19,"ch":10,"subj":"phy","marks":2,"q":"State the two laws of reflection of light.","a":"FIRST LAW:\nThe angle of incidence (∠i) is EQUAL to the angle of reflection (∠r).\n∠i = ∠r\n\nSECOND LAW:\nThe incident ray, the reflected ray, and the normal to the surface at the point of incidence all lie in the SAME PLANE (they are coplanar).\n\nImportant notes:\n• Angles are always measured from the NORMAL (perpendicular to surface), NOT from the surface itself\n• These laws apply to all reflecting surfaces: plane, concave, convex\n• The normal bisects the angle between incident and reflected rays\n\nApplications: Plane mirrors, periscopes, kaleidoscopes, searchlights"},{"id":20,"ch":10,"subj":"phy","marks":2,"q":"An object 4cm tall is 30cm from a convex lens (f=10cm). Find image position and magnification.","a":"Given: u = –30cm (sign convention), f = +10cm (convex), h = 4cm\n\nLens Formula: 1/v – 1/u = 1/f\n1/v – 1/(–30) = 1/10\n1/v + 1/30 = 1/10\n1/v = 1/10 – 1/30 = 3/30 – 1/30 = 2/30\nv = +15 cm ✓ (positive → real image, on other side)\n\nMagnification: m = v/u = 15/(–30) = –0.5\nImage height: h' = m × h = –0.5 × 4 = –2cm\n\nConclusion:\n• Image at 15cm on other side of lens → REAL\n• m = –0.5 → INVERTED\n• |m| = 0.5 < 1 → DIMINISHED (half the object size)"},{"id":21,"ch":11,"subj":"phy","marks":2,"q":"What is power of accommodation? What is LDDV?","a":"POWER OF ACCOMMODATION:\nThe ability of the eye's crystalline lens to change its focal length by changing its curvature to focus on objects at different distances.\n\nMechanism:\n• Near objects: ciliary muscles CONTRACT → lens more convex → shorter focal length → higher power\n• Far objects: ciliary muscles RELAX → lens flatter → longer focal length → lower power\n\nLDDV (Least Distance of Distinct Vision):\n= the minimum distance at which the normal eye can see objects clearly without strain\n= 25 cm for a normal adult eye\n\nWith age, lens loses elasticity → maximum converging power decreases → LDDV increases → PRESBYOPIA"},{"id":22,"ch":11,"subj":"phy","marks":2,"q":"Why is the sky blue? Why is the sun red at sunrise/sunset?","a":"BLUE SKY:\nRayleigh scattering: scattering ∝ 1/λ⁴. When sunlight passes through atmosphere, air molecules scatter shorter wavelengths (blue, λ≈450nm) ~10× more than longer wavelengths (red, λ≈700nm). Blue light scattered in all directions from every part of the sky → sky appears blue.\n\nRED SUNRISE/SUNSET:\nAt sunrise/sunset, sunlight travels a MUCH LONGER path through the dense lower atmosphere. Blue and violet light get scattered away multiple times and don't reach our eyes. Only red and orange (longest wavelengths, least scattered) survive the long journey → sun appears red/orange at the horizon."},{"id":23,"ch":12,"subj":"phy","marks":2,"q":"State Ohm's Law. What is its limitation?","a":"OHM'S LAW:\n'The potential difference (V) across a conductor is directly proportional to the current (I) through it, when temperature and physical conditions are constant.'\nV ∝ I → V = IR (R = constant resistance, in Ohm Ω)\n1 Ω = 1 V/A\n\nLIMITATIONS — Ohm's Law is NOT obeyed by:\n• Semiconductor diodes (non-linear I-V curve)\n• Electrolytes\n• Vacuum/gas discharge tubes\n• Conductors at high temperatures (R changes)\n• Thermistors, LEDs, photodiodes\n\nMaterials that DO obey Ohm's Law = ohmic conductors (metallic wires at constant temp.)"},{"id":24,"ch":12,"subj":"phy","marks":2,"q":"State Joule's Law of heating. Give 2 applications.","a":"JOULE'S LAW: H = I²Rt = VIt = V²t/R\nHeat produced is:\n• ∝ I² (square of current)\n• ∝ R (resistance)\n• ∝ t (time)\n\nDERIVATION:\nW = VQ = V·It = (IR)·It = I²Rt\n\nAPPLICATIONS:\n1. ELECTRIC HEATER/IRON:\n   Nichrome wire (high R + very high MP) → H = I²Rt → converts electrical to heat\n\n2. ELECTRIC FUSE:\n   Sn+Pb alloy (low MP) → excess current → rapid heating → melts → circuit breaks → protects appliances\n\nAlso: Electric bulb (tungsten filament glows at ~2500°C), electric kettle, room heater"},{"id":25,"ch":13,"subj":"phy","marks":2,"q":"State Fleming's Left-Hand Rule. Where is it used?","a":"FLEMING'S LEFT-HAND RULE:\nStretch thumb, index finger, and middle finger of LEFT hand mutually at right angles (perpendicular to each other):\n• Index/Fore finger (F) = direction of magnetic Field (B)\n• Middle finger (M) = direction of conventional Current (I)\n• Thumb (T) = direction of Thrust/Force on conductor (Motion)\nMemory aid: FBI (Fore=B, Middle=I, Thumb=Force)\n\nAPPLICATION IN ELECTRIC MOTOR:\nCurrent-carrying coil in magnetic field → force acts (F = BIL) → torque → coil rotates. Split-ring commutator reverses current every half rotation → continuous rotation in same direction.\nConverts: Electrical energy → Mechanical energy"},{"id":26,"ch":13,"subj":"phy","marks":2,"q":"What is electromagnetic induction? Who discovered it? Give one use.","a":"ELECTROMAGNETIC INDUCTION:\nThe phenomenon of generating an EMF in a conductor when the magnetic flux linked with it CHANGES.\n\nDiscovery: Michael Faraday (1831) and independently Joseph Henry.\n\nFaraday's Laws:\n1. EMF is induced whenever magnetic flux through a coil changes.\n2. Magnitude of induced EMF ∝ rate of change of magnetic flux (EMF = –dΦ/dt)\n\nWays to change flux:\n• Move magnet in/out of coil\n• Change current in adjacent coil\n• Rotate coil in magnetic field\n\nAPPLICATION:\nAC Generator (Dynamo): Coil rotates in magnetic field → flux changes continuously → AC EMF induced → electrical power generated. This is how ALL power stations work!"},{"id":27,"ch":14,"subj":"bio","marks":2,"q":"State Lindemann's 10% law. Why are food chains limited to 4–5 levels?","a":"LINDEMANN'S 10% LAW (1942):\nOnly 10% of the energy available at one trophic level is transferred to the next trophic level. The remaining 90% is lost as heat through respiration, movement, excretion, and undigested material.\n\nENERGY CALCULATION (producers = 10,000 J):\n→ Herbivores: 1,000 J (10%)\n→ 1° carnivores: 100 J (1%)\n→ Top carnivores: 10 J (0.1%)\n→ 5th level: only 1 J (0.01%)\n\nWHY LIMITED TO 4–5 LEVELS:\n1 J cannot sustain a viable population at a 5th level. Energy simply becomes insufficient to support another group of organisms. Hence food chains are naturally short."},{"id":28,"ch":14,"subj":"bio","marks":2,"q":"What is biological magnification? Give an example.","a":"BIOLOGICAL MAGNIFICATION:\nProgressive increase in concentration of non-biodegradable, fat-soluble chemicals (DDT, Hg, PCBs) at each successive higher trophic level.\n\nWhy it happens:\n• Chemical cannot be broken down by enzymes\n• Stored in fat tissue\n• Higher organisms eat MANY of the lower level → concentration multiplies\n\nDDT EXAMPLE in aquatic food chain:\nWater: 0.003 ppm\n→ Plankton: 0.04 ppm (13×)\n→ Small fish: 2 ppm\n→ Large fish: 25 ppm\n→ Fish-eating birds: 76 ppm (25,000× from water!)\n\nEffect: Caused thin eggshells in eagles/pelicans → reproductive failure → near-extinction → DDT banned in USA 1972"},{"id":1001,"ch":10,"subj":"phy","marks":2,"q":"Two thin lenses of focal length +20cm and –25cm are placed in contact. Find the power and focal length of the combination.","a":"P₁ = 1/f₁ = 1/0.20 = +5D\nP₂ = 1/f₂ = 1/(–0.25) = –4D\n\nP_combined = P₁ + P₂ = 5 + (–4) = +1D\n\nf_combined = 1/P = 1/1 = 1m = 100cm\n\nSince P is positive, the combination behaves as a CONVERGING (convex-like) system overall, with focal length 100cm."},{"id":1002,"ch":10,"subj":"phy","marks":2,"q":"Why are concave mirrors preferred for shaving/makeup mirrors and by dentists?","a":"When the face (or tooth) is held WITHIN the focal length of a concave mirror, the mirror produces a virtual, erect, and MAGNIFIED image.\n\nThis lets the user see fine detail clearly and closely — exactly what's needed for shaving or a dental check-up.\n\nA plane mirror would only give a same-size image, and a convex mirror would give a diminished image — neither is as useful for this close-up work."},{"id":1003,"ch":10,"subj":"phy","marks":2,"q":"Differentiate between a real image and a virtual image, with one example each.","a":"REAL IMAGE:\n• Formed by ACTUAL convergence of light rays\n• CAN be obtained/captured on a screen\n• Always inverted (for a single mirror/lens)\n• Example: Image formed beyond C by a concave mirror when the object is beyond C\n\nVIRTUAL IMAGE:\n• Formed by APPARENT divergence of light rays (rays only seem to meet when extended backward)\n• CANNOT be obtained on a screen — only seen by looking into the mirror/lens\n• Always erect (for a single mirror/lens)\n• Example: Image formed by a plane mirror, or by a convex mirror, or by a convex lens used as a magnifying glass"}];
export const LONG_QA: QA[] = [{"id":1,"ch":1,"subj":"chem","marks":5,"q":"Explain all five types of chemical reactions with balanced equations and real-life examples.","a":"FIVE TYPES OF CHEMICAL REACTIONS:\n\n1. COMBINATION REACTION: A + B → AB\nTwo or more substances combine into ONE product.\n• 2Mg + O₂ → 2MgO  (Mg burns brightly)\n• CaO + H₂O → Ca(OH)₂  (quicklime + water → slaked lime; exothermic)\n\n2. DECOMPOSITION REACTION: AB → A + B\nA single compound breaks into simpler substances.\n• Thermal: CaCO₃ →(Δ) CaO + CO₂  (limestone → quicklime)\n• Electrolytic: 2H₂O → 2H₂ + O₂  (electrolysis of water)\n• Photolytic: 2AgCl →(sunlight) 2Ag + Cl₂  (photography)\n\n3. DISPLACEMENT REACTION: A + BC → AC + B\nMore reactive displaces less reactive from its compound.\n• Zn + CuSO₄ → ZnSO₄ + Cu  (blue→colourless)\n• Fe + CuSO₄ → FeSO₄ + Cu  (iron nail turns red)\n\n4. DOUBLE DISPLACEMENT: AB + CD → AD + CB\nTwo compounds exchange ions; precipitate or gas forms.\n• Na₂SO₄ + BaCl₂ → BaSO₄↓ + 2NaCl  (white precipitate)\n• Na₂CO₃ + 2HCl → 2NaCl + H₂O + CO₂↑\n\n5. REDOX REACTIONS: Simultaneous oxidation + reduction.\n• ZnO + C → Zn + CO  (ZnO reduced; C oxidised)\n• 2Al + Fe₂O₃ → Al₂O₃ + 2Fe  (Thermite; Al oxidised, Fe₂O₃ reduced)\n\nCorrosion and rancidity are examples of slow oxidation in daily life."},{"id":2,"ch":2,"subj":"chem","marks":5,"q":"Describe the Chlor-Alkali process. What are the three products and their important uses?","a":"CHLOR-ALKALI PROCESS:\n\nProcess: Electrolysis of aqueous NaCl (brine) solution\n\nOverall Equation:\n2NaCl(aq) + 2H₂O(l) → Cl₂(g) + H₂(g) + 2NaOH(aq)\n\nAt ANODE (+): 2Cl⁻ → Cl₂ + 2e⁻  (oxidation — chlorine gas)\nAt CATHODE (–): 2H₂O + 2e⁻ → H₂ + 2OH⁻  (reduction — hydrogen gas)\nIn SOLUTION: Na⁺ + OH⁻ → NaOH forms near cathode\n\nName: 'Chlor' (chlorine) + 'Alkali' (NaOH) = chlor-alkali\n\nPRODUCT 1 — CHLORINE (Cl₂):\n• Water disinfection (chlorination of drinking water, swimming pools)\n• Manufacturing PVC plastic\n• Bleaching powder: Ca(OH)₂ + Cl₂ → Ca(OCl)Cl + H₂O\n• Making HCl and solvents\n\nPRODUCT 2 — HYDROGEN (H₂):\n• Hydrogenation of vegetable oils → vanaspati ghee\n• Fuel (hydrogen economy)\n• Making ammonia (Haber process) → fertilisers\n\nPRODUCT 3 — SODIUM HYDROXIDE (NaOH):\n• Soap and detergent manufacturing (saponification)\n• Paper industry (dissolving lignin)\n• Artificial fibres (rayon, nylon)\n• Degreasing and drain cleaners"},{"id":3,"ch":3,"subj":"chem","marks":5,"q":"Explain the reactivity series and how it guides extraction of metals from ores.","a":"REACTIVITY SERIES (decreasing order):\nK > Na > Ca > Mg > Al > Zn > Fe > Pb > H > Cu > Hg > Ag > Au\n\nIMPORTANCE:\n• Predicts displacement reactions\n• Guides extraction method\n• Explains corrosion susceptibility\n\nEXTRACTION METHODS:\n\nA. HIGHLY REACTIVE METALS (K, Na, Ca, Mg, Al):\n• Too reactive — C cannot reduce their oxides\n• Method: ELECTROLYSIS of molten ionic compounds\n• Na: 2NaCl(l) →(electrolysis) 2Na + Cl₂  (Downs cell)\n• Al: 2Al₂O₃(l) →(electrolysis, cryolite) 4Al + 3O₂  (Hall-Héroult)\n\nB. MODERATE REACTIVITY (Zn, Fe, Pb):\n• Method: REDUCTION with coke (C) at high temperature\n• ZnO + C → Zn + CO  (1200°C)\n• Fe₂O₃ + 3CO → 2Fe + 3CO₂  (blast furnace)\n\nC. LOW REACTIVITY (Cu, Hg, Ag, Au):\n• Found as free metals OR reduced simply by heating\n• 2HgS + 3O₂ → 2HgO + 2SO₂; then 2HgO → 2Hg + O₂\n• Gold found as native metal\n\nREFINING: Electrolytic refining for all metals\n• Impure metal = anode → dissolves\n• Pure metal = cathode → deposits\n• Precious metals (Ag, Au) collect in anode mud"},{"id":4,"ch":4,"subj":"chem","marks":5,"q":"What is a homologous series? Define alkane, alkene, alkyne with general formulas and examples.","a":"HOMOLOGOUS SERIES:\nA series of organic compounds with: (1) same general formula, (2) same functional group, (3) similar chemical properties, (4) each member differs by –CH₂– (14u) from the next.\nPhysical properties (MP, BP) increase gradually with chain length.\n\nALKANES (Saturated hydrocarbons):\n• General formula: CₙH₂ₙ₊₂\n• All C–C single bonds\n• Burn with BLUE flame\n• Undergo SUBSTITUTION: CH₄ + Cl₂ →(sunlight) CH₃Cl + HCl\n• Members: Methane(CH₄)→Ethane(C₂H₆)→Propane(C₃H₈)→Butane(C₄H₁₀)\n• Uses: Fuel (LPG, CNG), industrial solvents\n\nALKENES (Unsaturated — one C=C double bond):\n• General formula: CₙH₂ₙ\n• Burn with YELLOW SOOTY flame\n• Undergo ADDITION: C₂H₄ + H₂ →(Ni) C₂H₆\n• Members: Ethene(C₂H₄)→Propene(C₃H₆)→Butene(C₄H₈)\n• Uses: Making polyethylene, PVC, ethanol\n\nALKYNES (Unsaturated — one C≡C triple bond):\n• General formula: CₙH₂ₙ₋₂\n• Members: Ethyne/Acetylene(C₂H₂)→Propyne(C₃H₄)\n• Uses: Oxy-acetylene welding (3500°C), synthetic rubber\n\nIsomers: Same molecular formula, different structure\nC₄H₁₀ = n-butane (straight) and isobutane (branched)"},{"id":5,"ch":5,"subj":"chem","marks":5,"q":"Compare Mendeleev's periodic table with the Modern Periodic Table. Explain limitations and how they were resolved.","a":"MENDELEEV'S PERIODIC TABLE (1869):\n• Arranged by INCREASING ATOMIC MASS\n• Periodic law: Properties periodic function of atomic mass\n• Left gaps for undiscovered elements\n• Predicted Eka-Al (=Gallium), Eka-Si (=Germanium) — brilliant!\n\nLIMITATIONS:\n1. Anomalous pairs: Ar(39.9)>K(39.1) but Ar placed first; Te>I but Te placed first\n2. No place for isotopes (same element, different mass)\n3. H placement controversial (Group 1 or 17?)\n4. Some similar elements separated; dissimilar elements placed together\n\nMODERN PERIODIC TABLE (Moseley, 1913):\n• Arranged by INCREASING ATOMIC NUMBER\n• Modern Periodic Law: Properties periodic function of ATOMIC NUMBER\n• 7 periods, 18 groups; s,p,d,f blocks\n\nHOW LIMITATIONS RESOLVED:\n1. Anomalous pairs: Ar(18) before K(19) ✓; Co(27) before Ni(28) ✓; Te(52) before I(53) ✓\n2. Isotopes: Same atomic number → same position — no problem!\n3. Atomic number is more fundamental (unique to each element)\n4. Electronic configuration directly explains group and period placement"},{"id":6,"ch":6,"subj":"bio","marks":5,"q":"Trace the path of food through the human digestive system, naming enzymes and their functions at each stage.","a":"HUMAN DIGESTION — COMPLETE PATHWAY:\n\n1. MOUTH:\n• Teeth: mechanical breakdown\n• Salivary AMYLASE: starch → maltose (partial)\n• Mucus: lubricates food → forms bolus\n• pH ~6.8\n\n2. OESOPHAGUS:\n• No digestion; PERISTALSIS moves food down\n\n3. STOMACH:\n• HCl: kills bacteria; activates pepsinogen → pepsin; acidic medium (pH 1.5–2)\n• PEPSIN: proteins → peptones and peptides\n• MUCUS: protects stomach lining\n• Products → acidic CHYME\n\n4. SMALL INTESTINE:\n\nDUODENUM:\n• Bile (from liver): emulsifies fats + creates alkaline medium (pH 8)\n• Pancreatic AMYLASE: remaining starch → maltose\n• Pancreatic TRYPSIN: proteins → smaller peptides\n• Pancreatic LIPASE: emulsified fats → fatty acids + glycerol\n\nJEJUNUM/ILEUM:\n• Intestinal MALTASE: maltose → glucose + glucose\n• Intestinal PEPTIDASES: peptides → amino acids\n• Complete digestion occurs here\n\nABSORPTION:\n• VILLI + MICROVILLI: increase surface area ~600-fold\n• Glucose + amino acids → blood capillaries in villi → portal vein → liver\n• Fatty acids + glycerol → lacteals (lymph vessels) → lymph → blood\n\n5. LARGE INTESTINE:\n• Absorbs remaining water, forms faeces"},{"id":7,"ch":7,"subj":"bio","marks":5,"q":"Describe the structure of a neuron and explain how a nerve impulse travels from one neuron to another.","a":"STRUCTURE OF A NEURON:\n\n1. CELL BODY (Soma/Cyton):\n• Contains nucleus and Nissl granules (ribosomes for protein synthesis)\n• Metabolic control centre\n\n2. DENDRITES:\n• Multiple short branched projections\n• RECEIVE impulses from other neurons/receptors\n\n3. AXON:\n• Single long fibre (up to 1 metre)\n• Covered by MYELIN SHEATH (Schwann cells) — insulation, speeds conduction\n• NODES OF RANVIER: gaps in myelin — impulse jumps between them (saltatory conduction, ~100×faster)\n• Ends in AXON TERMINALS with synaptic vesicles\n\nTRAVEL OF NERVE IMPULSE:\n\nA. WITHIN NEURON (electrical):\n• Resting: Na⁺ outside, K⁺ inside (–70mV)\n• Stimulus: Na⁺ channels open → Na⁺ rushes in → +40mV (action potential)\n• Depolarisation wave travels along axon\n• Repolarisation: K⁺ moves out → resting potential restored\n\nB. ACROSS SYNAPSE (chemical):\n1. Action potential reaches axon terminal → Ca²⁺ influx\n2. Synaptic vesicles release NEUROTRANSMITTERS (acetylcholine) into synaptic cleft\n3. Diffuse across 20nm gap\n4. Bind to receptors on postsynaptic membrane\n5. New action potential generated\n6. Neurotransmitters broken down by enzymes (reset)\n\nSynapse ensures ONE-WAY transmission and allows signal modulation."},{"id":8,"ch":8,"subj":"bio","marks":5,"q":"Explain sexual reproduction in flowering plants from pollination through fertilisation to seed and fruit formation.","a":"SEXUAL REPRODUCTION IN FLOWERING PLANTS:\n\n1. FLOWER STRUCTURE:\n• STAMEN (male): Anther (pollen sacs) + Filament\n• CARPEL (female): Stigma + Style + Ovary (contains ovules with egg cells)\n\n2. POLLINATION: Transfer of pollen from anther to stigma\n• Self-pollination: same flower/plant → less variation\n• Cross-pollination: different plant → more variation\n• Agents: Wind (light dry pollen), Insects (colourful flowers, nectar), Water\n\n3. POLLEN GERMINATION:\n• Pollen lands on stigma → stigma secretes sugary solution → pollen germinates\n• Pollen tube grows down through style to ovary\n• Enters ovule through MICROPYLE\n\n4. DOUBLE FERTILISATION (unique to angiosperms):\n• Two male gametes travel down pollen tube\n• FIRST: male gamete(n) + egg(n) → ZYGOTE(2n) → EMBRYO\n• SECOND: male gamete(n) + 2 polar nuclei(n+n) → ENDOSPERM(3n) → food store\n\n5. POST-FERTILISATION:\n• Zygote → Embryo (by mitosis)\n• Ovule → SEED (embryo + endosperm + seed coat)\n• Ovary wall → FRUIT (pericarp)\n• Petals, stamens, style wither and fall\n\n6. SEED DISPERSAL: Wind, water, animals, explosive mechanisms\n\n7. GERMINATION: Water + O₂ + warmth → seedling → new plant"},{"id":9,"ch":9,"subj":"bio","marks":5,"q":"Explain Mendel's laws of inheritance using a monohybrid cross between tall (TT) and dwarf (tt) pea plants.","a":"MENDEL'S MONOHYBRID CROSS:\n\nPARENTS (P): TT (Tall, pure-breeding) × tt (Dwarf, pure-breeding)\nGametes: T and T × t and t\n\nF₁ GENERATION: All Tt (TALL)\nConclusion: T is DOMINANT (masks t which is RECESSIVE)\n→ LAW OF DOMINANCE: When two contrasting characters are crossed, only dominant trait appears in F₁.\n\nF₁ × F₁ CROSS: Tt × Tt\nGametes from Tt: T or t (equal probability)\n\nPUNNETT SQUARE:\n       T      t\n  T  [TT]  [Tt]\n  t  [Tt]  [tt]\n\nF₂ GENOTYPIC RATIO: TT : Tt : tt = 1 : 2 : 1\nF₂ PHENOTYPIC RATIO: Tall(TT+Tt) : Dwarf(tt) = 3 : 1\n\n→ LAW OF SEGREGATION: The two alleles of a gene SEPARATE during gamete formation. Each gamete receives only ONE allele.\n→ LAW OF INDEPENDENT ASSORTMENT (from dihybrid TtRr × TtRr → 9:3:3:1): Genes on different chromosomes assort independently.\n\nTEST CROSS: Tt × tt → 1 Tall : 1 Dwarf (1:1)\nUsed to determine unknown genotype.\n\nWHY MENDEL SUCCEEDED:\n• Large sample sizes (thousands of plants)\n• Chose 7 traits on different chromosomes\n• Pure-breeding lines established first\n• Mathematical/quantitative analysis"},{"id":10,"ch":10,"subj":"phy","marks":5,"q":"Describe image formation by a concave mirror for all 6 object positions with nature, position, and size of image.","a":"CONCAVE MIRROR IMAGE FORMATION:\nSign convention: distances from pole P; concave mirror f and R are negative.\n\n1. OBJECT AT INFINITY:\n• Image: At F (focal point)\n• Nature: Real, Inverted\n• Size: Highly diminished (point)\n• Use: Finding focal length, solar furnace\n\n2. OBJECT BEYOND C (u > 2f):\n• Image: Between F and C\n• Nature: Real, Inverted\n• Size: Diminished\n• Use: Film cameras\n\n3. OBJECT AT C (u = 2f = R):\n• Image: At C itself\n• Nature: Real, Inverted\n• Size: Same size (m = –1)\n• Use: Determine radius of curvature\n\n4. OBJECT BETWEEN F AND C (f < u < 2f):\n• Image: Beyond C\n• Nature: Real, Inverted\n• Size: Magnified (larger than object)\n• Use: Slide projectors, cinema projectors\n\n5. OBJECT AT F (u = f):\n• Image: At infinity (parallel reflected beam)\n• Size: Infinitely large\n• Use: Searchlights, car headlights, torches, lighthouse\n\n6. OBJECT BETWEEN P AND F (u < f):\n• Image: Behind the mirror (virtual)\n• Nature: Virtual, Erect\n• Size: Magnified\n• Use: Shaving/make-up mirrors, dentist mirrors, ENT doctors\n\nFormulas:\nMirror: 1/v + 1/u = 1/f; f = R/2; m = –v/u\nm > 0 → virtual, erect | m < 0 → real, inverted"},{"id":11,"ch":11,"subj":"phy","marks":5,"q":"What are the three common defects of vision? Give their causes and corrections.","a":"THREE COMMON DEFECTS OF VISION:\n\n1. MYOPIA (Short-sightedness):\nCauses:\n• Eyeball too LONG (anteroposterior)\n• Eye lens too CURVED (excess converging power)\nEffect: Image forms BEFORE retina → blurred distant vision\nCorrection: CONCAVE (diverging) lens\nThe –ve power lens diverges incoming rays → shifts focus point back onto retina\nPower: Negative (e.g., –2.5 D)\n\n2. HYPERMETROPIA (Long-sightedness):\nCauses:\n• Eyeball too SHORT\n• Eye lens too FLAT (insufficient converging power)\nEffect: Image would form BEHIND retina → blurred near vision\nCorrection: CONVEX (converging) lens\nThe +ve lens converges rays before entering eye → brings focus onto retina\nPower: Positive (e.g., +3 D)\n\n3. PRESBYOPIA (Old-age sight):\nCauses:\n• Gradual loss of lens ELASTICITY with age (45–50 years)\n• Weakening of ciliary muscles\nEffect: Cannot accommodate for both near AND far distances\nCorrection: BIFOCAL LENSES\n• Upper half: concave (for distant vision)\n• Lower half: convex (for reading)\n\nBonus — ASTIGMATISM:\nCause: Uneven corneal curvature\nCorrection: CYLINDRICAL lenses"},{"id":12,"ch":12,"subj":"phy","marks":5,"q":"Derive Joule's Law. Calculate monthly bill for a 2kW heater used 3 hours/day at ₹5 per unit.","a":"DERIVATION OF JOULE'S LAW:\n\nLet a resistor R have potential difference V across it.\nCurrent I flows for time t.\n\nWork done to move charge: W = V × Q = V × (It) = VIt\nAll work converts to heat: H = VIt\nSubstitute V = IR: H = (IR)(It) = I²Rt  ← Joule's Law\nAlso: H = V(V/R)t = V²t/R\n\nH = I²Rt = VIt = V²t/R\n\nH is: ∝ I², ∝ R, ∝ t\n\nAPPLICATIONS:\n• Electric heater (Nichrome wire): high R → large H\n• Fuse: low-MP wire → I²Rt → melts → breaks circuit\n• Bulb: tungsten glows at 2500°C\n\nELECTRICITY BILL:\nGiven: P = 2 kW, t = 3 hours/day, 30 days, rate = ₹5/unit\n\nEnergy per day = P × t = 2 kW × 3 h = 6 kWh\nMonthly energy = 6 × 30 = 180 kWh = 180 units\nMonthly cost = 180 × ₹5 = ₹900\n\nIn SI units: 180 kWh = 180 × 3.6×10⁶ = 6.48×10⁸ J\n\nAnswer: Monthly electricity bill = ₹900"},{"id":13,"ch":13,"subj":"phy","marks":5,"q":"Explain the working of an AC generator with each component's role. Why does it produce alternating current?","a":"AC GENERATOR (Dynamo):\n\nPRINCIPLE: Electromagnetic induction (Faraday) — rotating coil in magnetic field → changing flux → induced EMF.\n\nCOMPONENTS:\n1. ARMATURE COIL (ABCD):\n• Many turns of insulated copper wire on laminated iron core\n• The part that ROTATES between magnets\n• Laminated core reduces eddy current losses\n\n2. PERMANENT MAGNETS (N and S poles):\n• Provide strong uniform magnetic field\n• The coil rotates between these poles\n\n3. SLIP RINGS (R₁ and R₂):\n• Two separate metallic rings rotating with the coil\n• Each end of coil connected to one ring\n• Allow continuous connection between rotating coil and external circuit\n• KEY: Slip rings (not split-ring commutator) → alternating output\n\n4. CARBON BRUSHES (B₁ and B₂):\n• Stationary; press against slip rings\n• Transfer current to external circuit\n• Carbon: good conductor + self-lubricating\n\nWHY AC IS PRODUCED:\nAs coil rotates one full turn:\n• Position 1 (coil horizontal): maximum flux change → EMF = maximum\n• Position 2 (coil vertical): zero flux change → EMF = 0\n• Position 3 (horizontal again): maximum change in OPPOSITE direction → EMF = –maximum\n• Position 4 (vertical): zero again → EMF = 0\n\nOne rotation → EMF goes: 0 → +max → 0 → –max → 0 = ONE AC CYCLE\nFrequency = 50 Hz in India (50 rotations per second)\n\nFleming's Right-Hand Rule: finds direction of induced current in generator."},{"id":14,"ch":14,"subj":"bio","marks":5,"q":"Explain energy flow in an ecosystem. Why is it unidirectional? What is the role of decomposers?","a":"ENERGY FLOW IN AN ECOSYSTEM:\n\nSUN = primary energy source for all ecosystems.\nOnly ~1% of solar energy is captured by photosynthesis.\n\nTROPHIC LEVELS:\nLevel 1 — PRODUCERS (Plants):\n• Capture solar energy; convert to chemical energy (glucose)\n\nLevel 2 — PRIMARY CONSUMERS (Herbivores):\n• Receive 10% of producers' energy\n• 90% lost as heat (respiration, excretion, undigested matter)\n\nLevel 3 — SECONDARY CONSUMERS:\n• Receive 10% of herbivores' energy = 1% of original\n\nLevel 4 — TERTIARY CONSUMERS:\n• Receive 0.1% of original energy\n\nLINDEMANN'S 10% LAW: 10,000J → 1,000 → 100 → 10 → 1J\nFood chains rarely exceed 4–5 levels (insufficient energy remains).\n\nWHY ENERGY FLOW IS UNIDIRECTIONAL:\n1. Heat energy lost at each level CANNOT be recycled (Second Law of Thermodynamics)\n2. Once dissipated as heat, energy cannot re-enter food chain\n3. Matter/nutrients cycle but energy flows ONE WAY: Sun → producers → consumers → heat (lost)\n\nROLE OF DECOMPOSERS (bacteria + fungi):\n1. Break down complex organic molecules in dead organisms into simple inorganic compounds\n2. Release CO₂ → atmosphere (carbon cycle)\n3. Release N, P, K → soil (mineral cycling)\n4. Plants absorb these → producers can grow → cycle continues\n5. Complete the NUTRIENT CYCLE making ecosystem self-sustaining\n6. WITHOUT decomposers: dead matter piles up, nutrients locked, producers starved → ecosystem COLLAPSES\n\nFood web (interconnected chains) is more stable than a single food chain."},{"id":1001,"ch":10,"subj":"phy","marks":5,"q":"Describe image formation by a CONVEX LENS for different object positions, stating the nature, position, and relative size of the image in each case.","a":"CONVEX LENS IMAGE FORMATION (sign convention: f is +ve for convex lens):\n\n1. OBJECT AT INFINITY\n→ Image: at F₂ (focus), real, inverted, highly diminished (point-sized)\n\n2. OBJECT BEYOND 2F₁\n→ Image: between F₂ and 2F₂, real, inverted, diminished\n\n3. OBJECT AT 2F₁\n→ Image: at 2F₂, real, inverted, same size as object\n\n4. OBJECT BETWEEN F₁ AND 2F₁\n→ Image: beyond 2F₂, real, inverted, magnified\n\n5. OBJECT AT F₁\n→ Image: at infinity, real, inverted, highly magnified\n\n6. OBJECT BETWEEN F₁ AND OPTICAL CENTRE\n→ Image: on same side as object, virtual, erect, magnified (magnifying-glass case)\n\nGeneral rule: as the object moves from infinity toward the lens, the image moves from F₂ further away (real) until the object crosses F₁, after which the image becomes virtual, erect, and magnified on the same side as the object."},{"id":1002,"ch":10,"subj":"phy","marks":5,"q":"A 5cm tall object is placed 30cm from a concave lens of focal length 20cm. Find the position, nature, and size of the image, and the magnification produced.","a":"Given: h = 5cm, u = –30cm, f = –20cm (concave lens, always negative)\n\nLens formula: 1/v – 1/u = 1/f\n1/v = 1/f + 1/u = 1/(–20) + 1/(–30)\n1/v = –3/60 – 2/60 = –5/60 = –1/12\nv = –12cm\n\nMagnification: m = v/u = (–12)/(–30) = +0.4\n\nImage height: h' = m × h = 0.4 × 5 = 2cm\n\nCONCLUSION:\n• v = –12cm → image forms 12cm from the lens, on the SAME side as the object\n• m = +0.4 (positive, magnitude < 1) → image is VIRTUAL, ERECT, and DIMINISHED\n• Image height = 2cm\n\nThis confirms the general rule: a concave lens always forms a virtual, erect, diminished image, no matter where the object is placed."}];
export const FLASHCARDS: Flashcard[] = [{"ch":1,"q":"What are the 5 signs that a chemical reaction has occurred?","a":"1. Change in colour (CuSO₄ + Fe → blue turns green)\n2. Evolution of gas (Zn + HCl → H₂ bubbles)\n3. Formation of precipitate (AgNO₃ + NaCl → AgCl white ppt)\n4. Change in temperature (CaO+H₂O → hot; decomposition needs heat)\n5. Change in smell (food cooking; acid fumes)"},{"ch":1,"q":"Define exothermic and endothermic reactions with one example each.","a":"EXOTHERMIC: Releases heat to surroundings; products have less energy than reactants.\nExample: 2Mg+O₂→2MgO (burns brightly); respiration; CaO+H₂O→Ca(OH)₂\n\nENDOTHERMIC: Absorbs heat from surroundings; products have more energy than reactants.\nExample: CaCO₃→CaO+CO₂ (needs heating); photosynthesis; cooking food"},{"ch":2,"q":"What are the uses of baking soda (NaHCO₃)?","a":"1. ANTACID: Neutralises excess HCl in stomach (relieves heartburn)\n2. BAKING: With tartaric acid → CO₂ → fluffy cakes (baking powder)\n3. FIRE EXTINGUISHER: CO₂ produced smothers fire\n4. SODA WATER: Dissolved CO₂ under pressure\n5. CLEANING agent (mild abrasive)\n\nFormula: NaHCO₃ (sodium hydrogen carbonate)"},{"ch":2,"q":"What are the 3 products of the chlor-alkali process and their uses?","a":"2NaCl + 2H₂O → Cl₂ + H₂ + 2NaOH\n\n1. CHLORINE (anode): Water disinfection; PVC; bleaching powder; HCl\n2. HYDROGEN (cathode): Hydrogenation of oils; fuel; ammonia → fertilisers\n3. NaOH (near cathode): Soap/detergent; paper industry; artificial fibres; drain cleaner"},{"ch":3,"q":"What are amphoteric oxides? Give 4 examples.","a":"Amphoteric oxides react with BOTH acids AND bases.\n\nExample — ZnO:\n• ZnO + 2HCl → ZnCl₂ + H₂O (reacts with acid)\n• ZnO + 2NaOH → Na₂ZnO₂ + H₂O (reacts with base)\n\n4 Examples: ZnO, Al₂O₃, PbO, SnO\nThese metals (Zn, Al, Pb, Sn) are also called amphoteric metals."},{"ch":3,"q":"Why is Al extracted by electrolysis and not carbon reduction?","a":"Al is placed ABOVE carbon in the reactivity series.\nCarbon can only reduce metal oxides of metals LESS reactive than C.\nSince Al > C in reactivity, carbon CANNOT reduce Al₂O₃.\n\nMethod: Hall-Héroult electrolysis\n2Al₂O₃(l + cryolite) → 4Al + 3O₂\n\nCryolite (Na₃AlF₆): lowers MP of Al₂O₃ from 2050°C to 1000°C; increases conductivity."},{"ch":4,"q":"What is the cleansing action of soap? Explain the micelle.","a":"Soap molecule: hydrophilic (–COONa) HEAD + hydrophobic (hydrocarbon chain) TAIL\n\nCleansing:\n1. Tails dissolve in oil/grease droplet\n2. Heads point outward into water\n3. Form a spherical MICELLE (oil trapped inside, water-soluble outside)\n4. Micelles suspended in water (colloid)\n5. Rinsing with water washes away micelles + dirt\n\nDetergents: same mechanism but –SO₃Na group → works in hard water too"},{"ch":4,"q":"Distinguish between saponification and esterification.","a":"ESTERIFICATION:\nAlcohol + Carboxylic acid →(H₂SO₄, heat) Ester + Water  (reversible ⇌)\nC₂H₅OH + CH₃COOH → CH₃COOC₂H₅ + H₂O\n(sweet fruity smell; perfumes, flavours)\n\nSAPONIFICATION:\nFat/Oil + NaOH → Soap (RCOONa) + Glycerol  (irreversible)\nNaOH → hard soap; KOH → soft soap\nUsed in soap manufacturing"},{"ch":5,"q":"How do properties change across a period and down a group?","a":"ACROSS A PERIOD (left → right):\n↓ Atomic size DECREASES (more protons, same shells)\n↓ Metallic character DECREASES\n↑ Non-metallic character INCREASES\n↑ Ionisation energy INCREASES\n↑ Electronegativity INCREASES\n\nDOWN A GROUP (top → bottom):\n↑ Atomic size INCREASES (new shell added each period)\n↑ Metallic character INCREASES\n↓ Non-metallic character DECREASES\n↓ Ionisation energy DECREASES\n↓ Electronegativity DECREASES"},{"ch":5,"q":"Give Mendeleev's 3 achievements and 3 limitations.","a":"ACHIEVEMENTS:\n1. Organised 63 elements by atomic mass systematically\n2. Left gaps for undiscovered elements; predicted Eka-Al(=Ga), Eka-Si(=Ge)\n3. Corrected atomic masses based on expected properties\n\nLIMITATIONS:\n1. Anomalous pairs (Ar>K, Co>Ni, Te>I — placed wrongly by mass)\n2. No place for isotopes (same element, different mass)\n3. H's position controversial (properties of both Group 1 and Group 17)"},{"ch":6,"q":"Differentiate aerobic and anaerobic respiration (3 points each).","a":"AEROBIC (with O₂):\n• Cytoplasm + mitochondria\n• C₆H₁₂O₆+6O₂ → 6CO₂+6H₂O + 38 ATP\n• Complete oxidation; CO₂+H₂O released\n• High ATP yield — very efficient\n\nANAEROBIC (without O₂):\n• Cytoplasm only\n• Muscles: Glucose → 2 Lactic acid + 2 ATP\n• Yeast: Glucose → 2 Ethanol + 2CO₂ + 2 ATP\n• Incomplete oxidation; low ATP\n• Lactic acid → muscle cramps (oxygen debt)"},{"ch":6,"q":"Explain double circulation in humans.","a":"Double circulation: Blood passes through the HEART TWICE per complete circuit.\n\nPULMONARY CIRCUIT:\nRight atrium → Right ventricle → Pulmonary arteries → LUNGS (oxygenation) → Pulmonary veins → Left atrium\n\nSYSTEMIC CIRCUIT:\nLeft atrium → Left ventricle → Aorta → BODY (O₂ delivery) → Vena cava → Right atrium\n\nIMPORTANCE:\n• Oxygenated and deoxygenated blood NEVER MIX\n• High pressure to body → efficient O₂ delivery\n• Supports high metabolic rate of warm-blooded mammals"},{"ch":7,"q":"Name 5 hormones, their glands, and functions.","a":"1. THYROXINE (Thyroid): Controls metabolism & growth; iodine needed; deficiency→goitre\n2. INSULIN (Pancreas β-cells): Lowers blood glucose; promotes uptake; deficiency→diabetes\n3. GLUCAGON (Pancreas α-cells): Raises blood glucose; glycogen→glucose\n4. ADRENALINE (Adrenal medulla): Fight-or-flight; raises HR, BP, blood glucose\n5. GROWTH HORMONE (Pituitary): Body growth; deficiency→dwarfism; excess→gigantism"},{"ch":7,"q":"What is a reflex arc? Trace the path for touching a hot object.","a":"REFLEX ARC: Neural pathway for fast, automatic response. BYPASSES brain (processed in spinal cord).\n\nPATH (touching hot object):\n1. RECEPTOR: Pain/heat receptors in finger skin\n2. AFFERENT (sensory) nerve: Impulse to spinal cord\n3. SPINAL CORD: Relay neuron — immediate processing\n4. EFFERENT (motor) nerve: Impulse to muscle\n5. EFFECTOR: Arm muscle contracts → hand withdraws\n\nBrain receives the signal AFTER the reflex — you feel pain consciously later.\nWhy bypass brain? Speed — even 0.01s delay could cause serious injury."},{"ch":8,"q":"Differences between sperm and egg (ovum).","a":"SPERM:\n• Very small (head ~5μm + tail)\n• MOTILE — flagellum for swimming\n• Produced in MILLIONS daily in testes\n• Carries X OR Y chromosome\n• Haploid (n = 23)\n\nEGG (OVUM):\n• Large (~100μm, visible to naked eye)\n• NON-MOTILE — moves passively\n• ONE produced per month (~28-day cycle)\n• ALWAYS carries X chromosome\n• Haploid (n = 23)\n\nFertilisation: Sperm + Egg → Zygote (2n = 46)"},{"ch":8,"q":"What is vegetative propagation? Give 3 natural and 2 artificial examples.","a":"VEGETATIVE PROPAGATION: New plants from vegetative parts (roots, stems, leaves) without seeds.\n\nNATURAL:\n1. Stems: Potato (tubers), Ginger (rhizomes), Onion (bulbs)\n2. Roots: Sweet potato, Dahlia (root tubers)\n3. Leaves: Bryophyllum (adventitious buds on leaf margins)\n\nARTIFICIAL:\n1. CUTTING: Stem cut planted → roots develop (Rose, Sugarcane)\n2. GRAFTING: Scion (desired variety) joined to rootstock (Mango, Apple)"},{"ch":9,"q":"Explain the monohybrid cross Tt × Tt with Punnett square.","a":"PARENTS: Tt × Tt (both Tall heterozygous)\nGAMETES: Each parent → T or t gametes\n\nPUNNETT SQUARE:\n      T      t\n T  [TT]  [Tt]\n t  [Tt]  [tt]\n\nGENOTYPIC RATIO: 1TT : 2Tt : 1tt\nPHENOTYPIC RATIO: 3 Tall : 1 Dwarf (3:1)\n\nLAW OF DOMINANCE: T masks t; only T expressed in Tt\nLAW OF SEGREGATION: T and t separate during gamete formation; rejoin at fertilisation"},{"ch":9,"q":"Distinguish analogous and homologous organs. Which indicates common ancestry?","a":"HOMOLOGOUS ORGANS:\n• SAME basic structure, DIFFERENT function\n• Result of DIVERGENT evolution\n• Indicates COMMON ANCESTRY ← this one\nExample: Human arm + Bat wing + Whale flipper + Horse leg (all have humerus-radius-ulna)\n\nANALOGOUS ORGANS:\n• DIFFERENT structure, SAME function\n• Result of CONVERGENT evolution\n• No common ancestry implied\nExample: Butterfly wing (chitin) + Bird wing (bones+feathers) — both fly but structurally unrelated"},{"ch":10,"q":"State mirror formula and sign convention. What does positive magnification mean?","a":"MIRROR FORMULA: 1/v + 1/u = 1/f  (f = R/2)\n\nSIGN CONVENTION (New Cartesian):\n• All distances from POLE (P)\n• Direction of incident light = POSITIVE (+ve)\n• Opposite to incident light = NEGATIVE (–ve)\n• Object always in front → u always –ve\n• Concave mirror: f = –ve; Convex mirror: f = +ve\n\nMAGNIFICATION: m = –v/u = h'/h\n+ve m: Virtual and ERECT image\n–ve m: Real and INVERTED image\n|m| > 1: Magnified | |m| < 1: Diminished | |m| = 1: Same size"},{"ch":10,"q":"What is total internal reflection (TIR)? Give 2 applications.","a":"TIR: When light travels from DENSER to RARER medium and angle of incidence EXCEEDS the critical angle, all light is reflected back into the denser medium (no refraction).\n\nConditions:\n1. Light: denser → rarer medium\n2. Angle of incidence > critical angle (glass-air ≈ 42°)\n\nAPPLICATIONS:\n1. OPTICAL FIBRES: Light bounces along glass/plastic core by TIR → internet cables; endoscopy\n2. DIAMOND BRILLIANCE: Very high n (2.42) → very small critical angle (~24°) → many TIRs inside → exceptional sparkle"},{"ch":11,"q":"What is myopia? Cause and correction?","a":"MYOPIA (Short-sightedness / Near-sightedness):\n\nWHAT: Image of distant object forms BEFORE the retina\nRESULT: Blurred distant vision; near objects seen clearly\n\nCAUSES:\n1. Eyeball too LONG anteroposteriorly\n2. Eye lens too CURVED (excess converging power)\n\nCORRECTION:\n• CONCAVE (diverging) lens\n• Diverges incoming parallel rays from infinity before they enter the eye\n• Shifts focal point backward onto the retina\n• Power: NEGATIVE (e.g., –2.0 D means f = –50 cm)"},{"ch":11,"q":"Explain the Tyndall effect with 3 examples.","a":"TYNDALL EFFECT:\nScattering of light by colloidal particles (size 1–100nm). The path of a light beam becomes visible as a bright cone.\n\nNamed after: John Tyndall (1869)\n\n3 EXAMPLES:\n1. BLUE SKY: Air molecules scatter sunlight; blue (short λ) scattered 10× more than red (Rayleigh scattering)\n2. HEADLIGHTS IN FOG: Fog/mist droplets scatter headlight beam → visible cone of light\n3. SUNBEAM IN DUSTY ROOM: Dust particles scatter sunlight → bright shaft of light visible\n\nAlso: Milk (fat droplets scatter light), cigarette smoke"},{"ch":12,"q":"Compare series and parallel circuits on 4 parameters.","a":"PARAMETER | SERIES | PARALLEL\nCurrent | SAME through all | Divides at branches\nVoltage | Divides (V=V₁+V₂) | SAME across all\nResistance | R=R₁+R₂ (INCREASES) | 1/R=1/R₁+1/R₂ (DECREASES)\nFault effect | One fails → ALL fail | One fails → rest still work\n\nUSES:\nSeries: Fuse connections; decorative lights (some)\nParallel: ALL household wiring; appliances connected independently"},{"ch":12,"q":"If 100W and 200W bulbs are connected in parallel to 220V, which is brighter?","a":"PARALLEL: Same voltage (220V) across each bulb.\n\n100W bulb: P=100W → R = V²/P = 220²/100 = 484 Ω\n200W bulb: P=200W → R = 220²/200 = 242 Ω\n\nEach bulb gets full 220V in parallel:\n• 100W bulb → consumes 100W\n• 200W bulb → consumes 200W\n\nANSWER: 200W bulb is BRIGHTER (consumes more power)\n\nIf connected in SERIES:\nCurrent = V/(484+242) = 220/726 = 0.303 A\n100W bulb: P = I²R = 0.303² × 484 = 44.4W (actually BRIGHTER than 200W bulb in series!)"},{"ch":13,"q":"State Faraday's laws of electromagnetic induction. Give 2 applications.","a":"FARADAY'S LAWS:\n\n1st Law: An EMF is induced in a conductor whenever the magnetic flux linked with it CHANGES.\n\n2nd Law: The magnitude of induced EMF is directly proportional to the RATE OF CHANGE of magnetic flux.\nEMF = –dΦ/dt  (Lenz's law sign — direction opposes change)\n\nAPPLICATIONS:\n1. AC GENERATOR: Coil rotates in field → flux changes → alternating EMF induced → electrical power\n2. TRANSFORMER: Changing AC in primary coil → changing flux → EMF induced in secondary → voltage stepped up/down"},{"ch":13,"q":"Difference between AC and DC. Why is AC used for long-distance transmission?","a":"DC (Direct Current):\n• Flows in ONE direction only; constant\n• Source: batteries, solar cells, fuel cells\n• Example: 1.5V battery\n\nAC (Alternating Current):\n• Reverses direction periodically (50 times/sec in India)\n• Source: generators, dynamos\n• Example: 220V, 50Hz household supply\n\nWHY AC FOR LONG-DISTANCE:\n1. Transformers STEP UP AC voltage to ~400,000V\n2. Higher V → lower I (P=VI, power same)\n3. Less I → far less I²R heat loss in wires\n4. Step-down transformer at destination reduces to 220V\n\nTransformers ONLY work with AC!"},{"ch":14,"q":"What is the 10% law? Calculate energy at each trophic level if producers have 20,000J.","a":"LINDEMANN'S 10% LAW:\nOnly 10% of energy at one trophic level transfers to the next; 90% lost as heat.\n\nCalculation (producers = 20,000 J):\n• Level 1 — Producers: 20,000 J\n• Level 2 — Herbivores: 2,000 J  (10%)\n• Level 3 — 1° Carnivores: 200 J  (1%)\n• Level 4 — 2° Carnivores: 20 J  (0.1%)\n• Level 5 — Top carnivores: 2 J  (0.01%)\n\nConclusion: 2J cannot sustain a viable population → food chains limited to 4–5 levels!"},{"ch":14,"q":"What is biomagnification? Give a real-world DDT example.","a":"BIOMAGNIFICATION:\nProgressive concentration of non-biodegradable fat-soluble chemicals at higher trophic levels.\n\nReason: Chemical cannot be metabolised; stored in fat; higher organisms eat MANY of lower level → concentration multiplies.\n\nDDT EXAMPLE (aquatic food chain):\nWater: 0.003 ppm → Plankton: 0.04 ppm → Small fish: 2 ppm → Large fish: 25 ppm → Fish-eating birds (eagle): 76 ppm\n\nTotal concentration: 76/0.003 = 25,000× from water to top predator!\n\nEffect: Thin eggshells → eggs crack → reproductive failure → eagle population crashed\nResult: DDT banned globally"},{"ch":10,"q":"Quick sign convention recap for mirrors and lenses (New Cartesian Convention)?","a":"• All distances measured from the pole (mirror) / optical centre (lens)\n• Distances measured in the direction of incident light = POSITIVE\n• Distances measured against incident light = NEGATIVE\n• Heights above the principal axis = POSITIVE; below = NEGATIVE\n• u is always negative (object is always placed to the left, against incident light direction)\n• Concave mirror & concave lens: f is NEGATIVE\n• Convex mirror & convex lens: f is POSITIVE"},{"ch":10,"q":"What is refractive index and how is it defined?","a":"Refractive index (n) measures how much a medium slows down and bends light.\n\nn = speed of light in vacuum / speed of light in medium = c/v\n\nAlso, by Snell's Law: n = sin(i)/sin(r)\n\nHigher n → light bends more and travels slower in that medium. Diamond (n≈2.42) has one of the highest refractive indices of any natural material — part of why it sparkles so much."},{"ch":10,"q":"One-line memory trick for mirror/lens image behaviour?","a":"CONCAVE = converging = can form BOTH real and virtual images depending on object position (SOMETIMES flips).\n\nCONVEX = diverging (as a mirror) = ALWAYS virtual, erect, diminished — no exceptions, ever.\n\nMirror rule of thumb: object inside F → virtual & magnified; object outside F → real (concave only)."}];
export const FORMULA_DATA: FormulaData = {"phy":[{"cat":"⚡ Light — Reflection & Refraction (Ch 10)","icon":"bolt","formulas":[{"title":"Mirror Formula","text":"1/v + 1/u = 1/f","note":"v = image distance, u = object distance, f = focal length. Concave: f < 0. Convex: f > 0. All measured from pole P."},{"title":"Focal Length & Radius","text":"f = R/2","note":"R = radius of curvature. Concave mirror: both f and R are negative. Convex mirror: both positive."},{"title":"Magnification (Mirror)","text":"m = h’/h = −v/u","note":"m > 0 → virtual, erect. m < 0 → real, inverted. |m| > 1 → magnified. |m| < 1 → diminished. m = −1 → same size (object at C)."},{"title":"Refractive Index","text":"n = c/v = sin i / sin r\n(Snell’s Law: n₁ sin i = n₂ sin r)","note":"n = refractive index. c = 3×10⁸ m/s. Denser medium: larger n, slower light, bends toward normal."},{"title":"Lens Formula","text":"1/v − 1/u = 1/f","note":"Convex lens: f > 0. Concave lens: f < 0. Same sign convention: object u always negative."},{"title":"Magnification (Lens)","text":"m = h’/h = v/u","note":"No negative sign (unlike mirrors). m = +ve → virtual erect. m = −ve → real inverted."},{"title":"Power of a Lens","text":"P = 1/f (f in metres)\nUnit: Dioptre (D) = m⁻¹","note":"Convex: +D. Concave: −D. Lenses in contact: P_total = P₁ + P₂ + P₃..."}]},{"cat":"👁 Human Eye & Colourful World (Ch 11)","icon":"eye","formulas":[{"title":"LDDV / Near Point","text":"LDDV = 25 cm (normal adult eye)","note":"Least Distance of Distinct Vision. Below this, objects cannot be focused clearly. Increases with age → presbyopia."},{"title":"Rayleigh Scattering","text":"Scattering ∝ 1/λ⁴","note":"Blue (400nm) scattered ~10× more than red (700nm). Blue sky, red sunset/sunrise explained."},{"title":"Visible Spectrum (VIBGYOR)","text":"Violet(400nm) → Blue → Green → Yellow → Red(700nm)","note":"Violet: smallest λ → most bending (greatest deviation) in prism. Red: largest λ → least deviation."}]},{"cat":"💡 Electricity (Ch 12)","icon":"bolt","formulas":[{"title":"Electric Current & Charge","text":"I = Q/t\n(Ampere = Coulomb/second)","note":"Conventional current flows + to −. Electron flow is opposite. 1 A = 1 C passing per second."},{"title":"Ohm’s Law","text":"V = IR\n(1 Ω = 1 V/A)","note":"Valid for ohmic conductors at constant temperature. Non-ohmic: diodes, electrolytes, thermistors."},{"title":"Resistance Formula","text":"R = ρL/A","note":"ρ = resistivity (Ω·m) depends on material. R increases with length L; decreases with area A."},{"title":"Series Circuit","text":"R_eq = R₁ + R₂ + R₃\nSame current; voltages add","note":"Total R > any individual R. One break stops all current. Household: NOT used for appliances."},{"title":"Parallel Circuit","text":"1/R_eq = 1/R₁ + 1/R₂\nSame voltage; currents add","note":"R_eq < smallest R. Each appliance works independently. Household wiring uses parallel."},{"title":"Joule’s Law of Heating","text":"H = I²Rt = VIt = V²t/R (Joules)","note":"Electric heater, iron, fuse, bulb all use this. H ∝ I² means doubling current quadruples heat!"},{"title":"Electric Power","text":"P = VI = I²R = V²/R (Watts)","note":"1 W = 1 J/s. Power = rate of energy consumption. Higher wattage = more energy used per second."},{"title":"Commercial Unit of Energy","text":"1 kWh = 1000 W × 3600 s = 3.6 × 10⁶ J","note":"1 ‘unit’ = 1 kWh on electricity bill. Bill = units × rate (INR per unit)."}]},{"cat":"🧲 Magnetic Effects (Ch 13)","icon":"magnet","formulas":[{"title":"Force on Current-Carrying Conductor","text":"F = BIL sinθ","note":"B = magnetic flux density (T), I = current (A), L = length (m), θ = angle B and I. Max when θ = 90°."},{"title":"Indian Domestic AC","text":"V = 220 V (rms), f = 50 Hz","note":"Live = Red (dangerous, 220V), Neutral = Black (0V), Earth = Green (safety). Fuse always in LIVE wire."}]}],"chem":[{"cat":"🧪 Chemical Reactions (Ch 1)","icon":"flask","formulas":[{"title":"Five Types of Reactions","text":"Combination: A + B → AB\nDecomposition: AB → A + B\nDisplacement: A + BC → AC + B\nDouble Displacement: AB + CD → AD + CB\nRedox: simultaneous oxidation + reduction","note":"Know one balanced equation for each type. Corrosion and rancidity = slow oxidation (redox)."},{"title":"Key Balanced Equations","text":"2Mg + O₂ → 2MgO (bright white flame)\nCaCO₃ →(Δ) CaO + CO₂ (thermal decomp.)\n2H₂O →(electro.) 2H₂ + O₂\n2AgCl →(light) 2Ag + Cl₂ (photolytic)\nZn + CuSO₄ → ZnSO₄ + Cu (displacement)","note":"ALWAYS balance equations in board exam. Unbalanced = partial marks only."}]},{"cat":"🧪 Acids, Bases & Salts (Ch 2)","icon":"flask","formulas":[{"title":"Key Neutralisation Equations","text":"NaOH + HCl → NaCl + H₂O\nCa(OH)₂ + 2HCl → CaCl₂ + 2H₂O\nNa₂CO₃ + 2HCl → 2NaCl + CO₂ + H₂O","note":"Acid + Base → Salt + Water. Always exothermic. Acid + Carbonate → Salt + CO₂ + H₂O."},{"title":"Chlor-Alkali Process","text":"2NaCl + 2H₂O →(electrolysis) Cl₂ + H₂ + 2NaOH","note":"Anode: Cl₂ gas. Cathode: H₂ gas. Solution: NaOH (alkali). Products: bleaching powder, soap, plastics."},{"title":"Important pH Values","text":"Gastric juice: 1.5–2.5\nBlood: 7.35–7.45\nSaliva: 6.5–7.5\nSea water: ~8.2\nNeutral pure water: 7.0","note":"Memorise these for board! Slight deviation in blood pH → severe health consequences."},{"title":"Salts with Water of Crystallisation","text":"CuSO₄·5H₂O → Blue crystals (copper sulphate)\nNa₂CO₃·10H₂O → Washing soda\nCaSO₄·2H₂O → Gypsum\nCaSO₄·½H₂O → Plaster of Paris","note":"PoP + water → gypsum (sets hard, slight expansion). CuSO₄ heated: blue crystals → white anhydrous powder."}]},{"cat":"⚡ Metals & Non-Metals (Ch 3)","icon":"bolt","formulas":[{"title":"Reactivity Series","text":"K > Na > Ca > Mg > Al > Zn > Fe > Pb > H > Cu > Hg > Ag > Au","note":"Mnemonic: Katrina Ne Car Mangi Alto Zinc Ferrari Phir Humne Copper Haye Silver Audi"},{"title":"Key Metal Reactions","text":"2Na + 2H₂O → 2NaOH + H₂↑ (violent)\nCa + 2H₂O → Ca(OH)₂ + H₂↑ (floats)\n3Fe + 4H₂O(steam) → Fe₃O₄ + 4H₂\nFe + CuSO₄ → FeSO₄ + Cu","note":"More reactive = more vigorous reaction with water. Cu, Ag, Au don’t react with water at all."},{"title":"Thermite Reaction","text":"2Al + Fe₂O₃ → Al₂O₃ + 2Fe + heat","note":"Temperature exceeds 2500°C. Used for thermite welding of railway tracks. Al is above Fe in reactivity series."}]},{"cat":"🌱 Carbon & Compounds (Ch 4)","icon":"leaf","formulas":[{"title":"Homologous Series","text":"Alkanes: CnH(2n+2) — CH₄,C₂H₆,C₃H₈...\nAlkenes: CnH(2n) — C₂H₄,C₃H₆...\nAlkynes: CnH(2n-2) — C₂H₂,C₃H₄...\nAlcohols: CnH(2n+1)OH — CH₃OH,C₂H₅OH...","note":"Each consecutive member differs by -CH₂- (14u). IUPAC: 1C=meth, 2C=eth, 3C=prop, 4C=but, 5C=pent."},{"title":"Important Organic Reactions","text":"Esterification: RCOOH + ROH ⇌ RCOOR' + H₂O\nHydrogenation: C=C + H₂ →(Ni) C-C\nCombustion: CH₄ + 2O₂ → CO₂ + 2H₂O\nSaponification: Ester + NaOH → Soap + Glycerol","note":"Esterification is reversible (⇌). Saponification produces hard soap (NaOH) or soft soap (KOH)."}]},{"cat":"🗓 Periodic Classification (Ch 5)","icon":"table-cells","formulas":[{"title":"Periodic Trends","text":"Atomic size: Increases ↓ down group; Decreases → across period\nMetallic character: Increases ↓ down; Decreases → across\nIonisation energy: Decreases ↓ down; Increases → across\nElectronegativity: Decreases ↓ down; Increases → across","note":"Remember: down a group = bigger atoms (more shells) = easier to lose electrons = more metallic."},{"title":"Key Groups","text":"Group 1: Alkali metals (Li, Na, K)\nGroup 2: Alkaline earth (Mg, Ca)\nGroup 17: Halogens (F, Cl, Br, I)\nGroup 18: Noble gases (He, Ne, Ar)","note":"Group number (1-18) = number of valence electrons (for groups 1-2 and 13-18). Period = number of electron shells."}]}],"bio":[{"cat":"🌿 Life Processes (Ch 6)","icon":"leaf","formulas":[{"title":"Photosynthesis","text":"6CO₂ + 12H₂O + light → C₆H₁₂O₆ + 6H₂O + 6O₂\n(Endothermic, in chloroplasts)","note":"O₂ released comes from H₂O (not CO₂)! Chlorophyll absorbs red and blue light, reflects green. Occurs in 2 stages: Light reactions + Dark reactions (Calvin cycle)."},{"title":"Aerobic Respiration","text":"C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + 38 ATP\n(Exothermic, in mitochondria)","note":"Mitochondria = powerhouse. 38 ATP per glucose molecule. Glucose fully oxidised. Efficient energy release."},{"title":"Anaerobic Respiration","text":"Yeast: C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂ + 2 ATP\nMuscle: C₆H₁₂O₆ → 2 Lactic acid + 2 ATP","note":"Only 2 ATP (vs 38 in aerobic). Lactic acid causes muscle cramps. Yeast fermentation used in bread, alcohol, vinegar."},{"title":"Normal Blood Pressure & Values","text":"Blood pressure: 120/80 mmHg (systolic/diastolic)\nRBC lifespan: 120 days\nNormal heart rate: 70–80 beats/min\nBlood pH: 7.35–7.45","note":"Hypertension: BP > 140/90. Hypotension: BP < 90/60. Heart pumps ~5 litres of blood per minute."}]},{"cat":"🦠 Heredity & Evolution (Ch 9)","icon":"dna","formulas":[{"title":"Monohybrid Cross Ratios","text":"F₁: ALL dominant phenotype\nF₂ phenotype ratio: 3 Dominant : 1 Recessive\nF₂ genotype ratio: 1 TT : 2 Tt : 1 tt\nTest cross: 1 Dominant : 1 Recessive","note":"ALWAYS draw Punnett square in boards. Show gametes from each parent. Label clearly."},{"title":"Dihybrid Cross","text":"F₂ phenotype ratio: 9 : 3 : 3 : 1\n(Round Yellow : Round Green : Wrinkled Yellow : Wrinkled Green)","note":"Law of Independent Assortment — valid when genes on different chromosomes. Very commonly asked in boards!"},{"title":"Sex Determination","text":"Mother: always XX (contributes only X)\nFather: XY (contributes X OR Y)\nXX = daughter; XY = son\n50:50 probability each pregnancy","note":"Father determines sex of child. Blaming the mother is scientifically incorrect. Important for boards and general knowledge."}]},{"cat":"🌍 Our Environment (Ch 14)","icon":"globe","formulas":[{"title":"10% Energy Law (Lindemann, 1942)","text":"Producers: 10,000 J\nHerbivores: 1,000 J (10%)\n1° Carnivores: 100 J (1%)\nTop Carnivores: 10 J (0.1%)","note":"Only 10% transfers to each level; 90% lost as heat, movement, waste. Limits food chains to 4–5 trophic levels."},{"title":"DDT Biomagnification","text":"Water: 0.003 ppm\nPlankton: 0.04 ppm\nSmall fish: 2 ppm\nLarge fish: 25 ppm\nFish-eating birds: 76 ppm (×25,000 of water!)","note":"Non-biodegradable + fat-soluble = accumulates at each level. DDT thinned eagle eggshells → near-extinction. Banned in many countries."}]}]};

export const SSC_CHAPTERS: SscChapter[] = [{"id":1,"num":"Ch 1","subj":"hist","title":"Rise of Nationalism in Europe","oneshot":["French Revolution (1789): liberty, equality, fraternity; abolished monarchy and feudal privileges","Napoleon's Code Civil (1804): legal equality, property rights, abolished serfdom — spread across Europe","1848 Year of Revolutions: liberals demanded constitutions and unified nation-states across Europe","Romanticism: emphasized folk culture, vernacular languages, local traditions over Enlightenment reason"],"keypts":["German unification (1866-71): Bismarck's Realpolitik — wars with Denmark, Austria, France; Prussia led","Italian unification: Mazzini (Young Italy), Cavour (Piedmont diplomacy), Garibaldi (Red Shirts captured Sicily & Naples)","Zollverein (1834): Prussian customs union removed tariff barriers — economic unity before political unity","Frankfurt Parliament (1848): liberal initiative to unite Germany failed — relied on aristocracy, no mass support","Female allegories: Marianne (France), Germania (Germany), Britannia (UK) gave abstract nations human identity","Metternich (Austria): called Germany and Italy 'geographical expressions'; suppressed nationalist movements","Frederic Sorrieu (1848): painted vision of democratic republics united in a 'United States of Europe and the World'","Balkan crisis: Ottoman decline + ethnic nationalisms → instability → triggered World War I"],"formulas":"KEY DATES:\n1789 — French Revolution\n1815 — Congress of Vienna\n1831 — Mazzini's Young Italy\n1834 — Zollverein (customs union)\n1848 — Year of Revolutions\n1861 — Italy unified\n1866-71 — Germany unified","exam":["Bismarck unified Germany TOP-DOWN (military); Mazzini tried BOTTOM-UP (people's movement) — contrast both approaches","Frankfurt Parliament failed: educated liberals could not mobilize peasants/workers — no popular power base","Napoleon's paradox: spread revolutionary ideals but also spread French imperialism — local nationalisms arose against him"]},{"id":2,"num":"Ch 2","subj":"hist","title":"Nationalism in India","oneshot":["Satyagraha: truth-force + non-violence; persuade oppressor, not defeat — Gandhi's revolutionary method","Non-Cooperation Movement (1920-22): boycott courts, schools, foreign goods; ended after Chauri Chaura violence","Civil Disobedience Movement (1930-34): Dandi March March 12, 240 miles — Gandhi broke salt law","Quit India Movement (1942): 'Do or Die'; most radical; Gandhi arrested; nationwide revolt"],"keypts":["Rowlatt Act (1919): imprisonment without trial for 2 years — 'Black Act'; triggered mass protests","Jallianwala Bagh (April 13, 1919): General Dyer fired on unarmed crowd; ~1000+ killed; turned moderates to nationalists","Simon Commission (1927): all-white; 'Simon Go Back' protests unified diverse Indians","INC Lahore Session (1929): Poorna Swaraj declared; Jan 26 = Independence Day pledge","Khilafat Movement (1920): Ali brothers led Muslims into Non-Cooperation — rare Hindu-Muslim unity","Chauri Chaura (Feb 1922): crowd burnt police chowki killing 22 constables → Gandhi suspended NCM","Gandhi-Irwin Pact (1931): CDM suspended; Gandhi attended 2nd Round Table Conference London","Different participants: Peasants (Awadh), Tribals (Alluri Sitarama Raju), Women — all different grievances"],"formulas":"TIMELINE:\n1919 — Rowlatt Act; Jallianwala Bagh\n1920 — Non-Cooperation begins\n1922 — Chauri Chaura; NCM suspended\n1929 — Lahore Session; Poorna Swaraj\n1930 — Dandi March (March 12); CDM\n1931 — Gandhi-Irwin Pact\n1942 — Quit India: Do or Die","exam":["Gandhi suspended NCM after Chauri Chaura: non-violence must be maintained; violence delegitimizes the movement","Salt chosen for CDM: affected every Indian equally regardless of class, religion, region — perfect symbol","Non-cooperation had two phases: constructive (khadi, Hindu-Muslim unity) and destructive (boycotts)"]},{"id":3,"num":"Ch 3","subj":"hist","title":"Making of a Global World","oneshot":["Silk Routes: ancient trade network connecting Asia, Middle East, Africa, Europe — goods, ideas, religions, diseases","Corn Laws repealed (Britain 1846): cheap imports ruined British farmers → rural migration → industrialization","Great Depression (1929): Wall Street crash; banks failed; 25% US unemployment; global trade fell 65%","Bretton Woods (1944): established IMF and World Bank; created US dollar-based post-WW2 monetary order"],"keypts":["Columbus discovered Americas (1492): colonization; smallpox killed 90% of indigenous people","Indentured labour: Indians/Chinese to Caribbean, Fiji, Mauritius after 1833 — 5-year contracts; called girmitiya","Rinderpest (Africa 1890s): killed 90% cattle; starving Africans sold land cheaply to colonial powers","Henry Ford (1908): assembly line for Model T; mass production; higher wages; consumer culture created","1920s USA: hire-purchase (buy on credit); advertising boom; then 1929 crash wiped everything","WW1 effects on India: India became lender to Britain; jute/cotton exports boomed; but inflation, forced recruitment","Post-WW2: USA dominant creditor; Marshall Plan rebuilt Europe; Bretton Woods gave monetary stability","Hosay festival (Trinidad): Indian workers blended Hindu + Muslim traditions — new syncretic culture"],"formulas":"KEY DATES:\n1492 — Columbus; Americas colonized\n1830s — Indentured labour begins\n1890s — Rinderpest, Africa\n1908 — Ford Model T\n1929 — Great Depression (October)\n1944 — Bretton Woods Conference\n1991 — India LPG reforms","exam":["Depression hit India: agricultural prices fell 50%+ → peasants couldn't pay taxes → debt → joined CDM 1930","Indentured labour = new system of slavery: no freedom, physical punishment, thousands of miles from home","Bretton Woods designed to prevent another 1930s Depression: fixed exchange rates, IMF as lender of last resort"]},{"id":4,"num":"Ch 4","subj":"hist","title":"Print Culture and the Modern World","oneshot":["Gutenberg press (c.1448): movable metal type; first printed Bible — 180 copies in 3 years vs years per copy by hand","China: woodblock printing from 594 AD; Bi Sheng's movable type (11th century); Buddhist texts mass-printed","India: Portuguese in Goa (1556, first press); Bengal Gazette = first Indian newspaper (1780, James Hicky)","Luther's 95 Theses printed and spread across Europe in 15 days → Protestant Reformation succeeded via print"],"keypts":["Gutenberg adapted screw press from wine-making technology + metal movable type — brilliant synthesis","Erasmus feared printing would spread 'vanity and indecency' — conservatives always fear new communication","Chapbooks (Britain): cheap penny pamphlets for common people; literacy spread downward through society","Tilak's Kesari (Marathi) and Maratha (English): fired nationalist sentiment; reached lakhs of readers","Raja Ram Mohan Roy used Sambad Kaumudi to campaign against sati; print enabled reform at scale","Ulemas used print to spread Islamic interpretations; fatwa distributed widely; religious debate democratized","Rashsundari Devi (1876): first autobiography in Bengali — women became readers and then writers","Vernacular Press Act (1878): colonial censorship; actually amplified resistance by creating press martyrs"],"formulas":"KEY PRESSES:\nGutenberg: c.1448 Germany\nIndia first press: 1556 Goa\nBengal Gazette: 1780 (first Indian paper)\nSamachar Darpan: 1818 Bengali\nKesari & Maratha: Tilak nationalist press\nVernacular Press Act: 1878 censorship","exam":["Print capitalism (Benedict Anderson): print created national reading communities → imagined national identity → nationalism","Censorship paradox: VPA 1878 proved British feared Indian print — suppression only amplified resistance","Women and print: conservative opposition failed; print opened intellectual space → women became authors"]},{"id":5,"num":"Ch 1","subj":"geo","title":"Resources and Development","oneshot":["Resource: anything used to satisfy human needs when technology allows and cultural acceptance exists","Biotic: living (forests, animals) | Abiotic: non-living (minerals, water, soil) | Renewable vs Non-renewable","Agenda 21: Rio Earth Summit 1992; sustainable resource use; every nation makes its own Agenda 21","Land degradation: overgrazing, mining, waterlogging, soil salinity, industrial effluents, urbanization"],"keypts":["Resource types: Individual (farms), Community (ponds), National (forests/minerals), International (oceanic >200km)","5 soil types: Alluvial (most widespread, Indo-Gangetic), Black/Regur (Deccan, cotton), Red/Yellow (iron oxide), Laterite (leached), Arid (Rajasthan)","Alluvial soil: Khadar (newer, flood plains, fertile) vs Bhangar (older, elevated, kankar nodules, less fertile)","Soil erosion: Sheet erosion (rain), Gully erosion (Chambal ravines), Wind erosion (arid areas)","Conservation: contour ploughing, terrace farming, shelter belts (Rajasthan), strip cropping, intercropping","Black soil: self-ploughing property (swells wet, cracks dry); rich in Ca, Mg, K — ideal for cotton","Red/Yellow soil: iron oxide gives colour; moderate fertility; Odisha, Chhattisgarh, Jharkhand","Laterite soil: heavily leached by heavy rain; suitable for cashew, tea, coffee; W. Ghats, NE India"],"formulas":"SOIL PROPERTIES:\nAlluvial: Most fertile, widespread; wheat/rice/sugarcane\nBlack (Regur): Cotton; self-ploughing; Ca+Mg+K\nRed/Yellow: Iron oxide; moderate fertility\nLaterite: Heavily leached; tea/cashew/coffee\nArid: Sandy, coarse; drought-resistant crops","exam":["Black soil for cotton: holds moisture during growth, self-ploughs (swells wet, cracks dry), Ca-rich","Khadar vs Bhangar: Khadar = newer alluvium, river flood plains, more fertile; Bhangar = older, higher, kankar","Agenda 21: India must develop sustainable resource plan balancing present needs with future availability"]},{"id":6,"num":"Ch 2","subj":"geo","title":"Forest and Wildlife Resources","oneshot":["India: 4 biodiversity hotspots; 47,000 plant species; 89,000 animal species; 8% of world's biodiversity","Forest types: Reserved (53%, strictest), Protected (29%, some rights), Unclassed (18%, least protected)","Chipko Movement (1970s Uttarakhand): villagers hugged trees; Gaura Devi led; 15-year logging ban followed","Project Tiger (1973): India's flagship conservation — tiger population significantly recovered"],"keypts":["Biodiversity threats: habitat destruction, poaching, invasive species, pollution, climate change","Forest types: Tropical Evergreen (>200cm), Deciduous (100-200cm), Thorn (<50cm), Mangrove (coastal)","90% of India's forests under government; tribal communities depend on forests but often have limited rights","JFM (Joint Forest Management): community + government partnership; started Odisha 1988; communities share benefits","Sacred groves (Dev Van): traditionally protected; Rajasthan, MP, Meghalaya; incredible biodiversity preserved","Bishnoi community: Amrita Devi Bishnoi sacrificed life protecting trees 1730; 363 Bishnois died that day","Wildlife Protection Act (1972): legal protection; CITES bans international trade in endangered species","Biodiversity hotspots: Western Ghats, Eastern Himalayas, Indo-Burma, Sundaland (Andaman & Nicobar)"],"formulas":"FOREST PROTECTION LEVELS:\nReserved (53%): Strictest — no community rights\nProtected (29%): Some rights allowed\nUnclassed (18%): Government + community land\n\nENDANGERED:\nBlack Buck, Crocodile, Indian Wild Ass\nIndian Rhino, Lion-tailed Macaque, Sangai Deer","exam":["Chipko significance: first grassroots environmental movement; community protection more effective than state","JFM works because: communities who live in forests are best guardians; direct incentive when they share benefits","Sacred groves show: traditional communities conserved biodiversity for centuries before modern conservation law"]},{"id":7,"num":"Ch 3","subj":"geo","title":"Water Resources","oneshot":["96.5% water in oceans; only 2.5% fresh; 70% of fresh water frozen — only ~1% usable by humans","India: 4% of world's water, 16% of population; water stress growing despite adequate average rainfall","Dams = multi-purpose: irrigation, hydroelectricity, flood control, navigation, drinking water, recreation","Traditional harvesting: kuls (HP), johads/khadins (Rajasthan), tankas, bamboo drip (Meghalaya), tanks (S. India)"],"keypts":["Water scarcity: over-extraction (Punjab water table falls 1m/year), pollution, seasonal variation, unequal distribution","Major dams: Bhakra Nangal (Sutlej, Punjab/HP), Hirakud (Mahanadi, Odisha), Tehri (Bhagirathi, UK — HIGHEST), Nagarjuna Sagar (Krishna, AP)","Nehru called dams 'temples of modern India' — linked to industrial progress and national development","Narmada Bachao Andolan: Medha Patkar led; 250,000+ displaced, mostly tribal; Sardar Sarovar Dam controversy","Dam problems: displacement (tribals worst affected), ecosystem disruption, siltation, methane, seismicity","Tamil Nadu made rooftop rainwater harvesting MANDATORY by law (2001) — legislative water conservation","Bamboo drip irrigation (Meghalaya): 200-year-old Khasi technology; precise delivery to roots; zero energy cost","Inter-state conflicts: Cauvery (Karnataka-TN), Ravi-Beas (Punjab-Haryana-Rajasthan) — water scarcity causes politics"],"formulas":"INDIA WATER DATA:\nAnnual precipitation: 4000 BCM\nUsable water: 1123 BCM\n\nDAM LOCATIONS:\nBhakra Nangal → Sutlej (Punjab/HP)\nHirakud → Mahanadi (Odisha)\nTehri (highest) → Bhagirathi (UK)\nNagarjuna Sagar → Krishna (AP)\nSardar Sarovar → Narmada (Gujarat)","exam":["Dams: double-edged — provide water/power BUT displace communities; NBA highlights fundamental development vs justice conflict","Traditional conservation (johads, kulhs, tanks) is cheaper, more equitable, more sustainable than mega-dams","Water scarcity causes inter-state conflicts: Cauvery dispute decades-long; water will be 21st century's oil"]},{"id":8,"num":"Ch 4","subj":"geo","title":"Agriculture","oneshot":["3 seasons: Kharif (June-Oct, monsoon — rice/cotton/maize), Rabi (Nov-Apr, winter — wheat/gram), Zaid (summer)","Green Revolution (1960s): HYV seeds + fertilizers + irrigation; Punjab/Haryana/UP; India became food self-sufficient","White Revolution (Operation Flood): dairy revolution; Dr. Verghese Kurien; Amul cooperative; India top milk producer","Agriculture employs ~50% of workforce but contributes only ~15% of GDP — productivity must increase"],"keypts":["Farming types: Subsistence (intensive, shifting/Jhum NE India), Commercial (plantation, mixed, dry land)","Plantation: single crop, large estate, capital-intensive; tea (Assam), rubber (Kerala), coffee (Karnataka)","Major crops: Rice (WB, UP, AP, Punjab), Wheat (Punjab, Haryana, UP), Cotton (Maharashtra, Gujarat), Jute (WB)","Kharif crops: Rice, Cotton, Jute, Maize, Groundnut | Rabi: Wheat, Gram, Mustard, Barley","Land reforms: zamindari abolition (1950s), tenancy reforms, land ceiling, Bhoodan movement (Vinoba Bhave)","ICAR: Indian Council of Agricultural Research; develops HYV seeds, pest-resistant strains","Green Revolution problems: regional inequality (only Punjab/Haryana), soil degradation, groundwater depletion","Jhumming: slash-and-burn in NE India; sustainable only at low population density; government discouraging it"],"formulas":"CROPPING CALENDAR:\nKharif: June-September → harvested Oct-Nov\nRabi: Oct-Nov → harvested March-April\nZaid: March-June (summer crops)\n\nGREEN REVOLUTION:\nStates: Punjab + Haryana + UP (wheat belt)\nProblems: Regional inequality, soil degradation, water depletion","exam":["Green Revolution pros: food self-sufficiency, famine prevention, farmer income rise — CONS: soil degradation, groundwater fall, regional inequality, farmer debt","Jhumming: sustainable only for small populations; environmental problems with increasing population pressure","India's challenge: 50% in agriculture for 15% of GDP — raise productivity OR move workers to industry/services"]},{"id":9,"num":"Ch 5","subj":"geo","title":"Minerals and Energy Resources","oneshot":["Mineral: naturally occurring, definite chemical composition; takes millions of years to form — non-renewable","Ferrous metallic: iron ore, manganese | Non-ferrous: copper, bauxite, gold | Non-metallic: mica, limestone","Conventional energy: coal, petroleum, natural gas, hydro, nuclear | Non-conventional: solar, wind, tidal, biomass","India's National Solar Mission targets 100GW; Rajasthan has highest potential — 320+ sunny days per year"],"keypts":["Iron ore: Jharkhand (Singhbhum), Odisha (Keonjhar), Chhattisgarh (Bailadila); Magnetite ~72% Fe, Hematite 60-70%","Coal: Gondwana fields (80%) — Jharkhand (Jharia, Raniganj), Odisha, WB; Raniganj = oldest (1774)","Petroleum: Mumbai High (60-65% of production), Digboi (Assam, oldest 1867), Ankleshwar (Gujarat); India imports 85%","Mica: Jharkhand (Koderma = world's largest), AP, Rajasthan; used in electrical/electronics industries","Bauxite: Odisha (Panchpatmali = largest), Jharkhand, MP; raw material for aluminium","Nuclear: Uranium at Jaduguda (Jharkhand); Thorium in Kerala coast = 25% of WORLD's thorium reserves!","Wind energy: Tamil Nadu (Nagarkoil = highest), Gujarat, Rajasthan, Karnataka; India 4th in world","Chota Nagpur Plateau = 'mineral heartland of India' — coal + iron + mica + copper + bauxite"],"formulas":"COAL TYPES (quality high→low):\nAnthracite > Bituminous > Lignite > Peat\n\nMINERAL REGIONS:\nChota Nagpur = richest mineral region\nDeccan Plateau = iron, manganese, mica\nAravalli = copper, zinc, lead\nKerala coast = thorium (monazite)\n\nINDIA = 25% of world's thorium reserves","exam":["Thorium matters: India's 3-stage nuclear program plans thorium as ultimate fuel; could power India for centuries","Mineral conservation: recycle metals, develop substitutes, efficient extraction — minerals are non-renewable","Renewable energy imperative: coal and oil are finite and polluting; India must transition to solar and wind"]},{"id":10,"num":"Ch 6","subj":"geo","title":"Manufacturing Industries","oneshot":["Manufacturing: transforms raw materials into finished goods; adds value; drives economic development","Location factors: raw materials, power, labour, capital, transport, market, water, government policy","4 industrial regions: Mumbai-Pune (W), Hugli (E), Bangalore-Chennai (S), Chota Nagpur (Central-East)","IT/Software: Bangalore = Silicon Valley of India; ~$200B exports; TCS, Infosys, Wipro are global companies"],"keypts":["Textile: oldest industry; Ahmedabad and Mumbai ('Manchester of India'); India 2nd largest textile producer","Iron & Steel: 'basic industry' — supports all others; Jamshedpur (TISCO 1907 oldest), Bhilai, Rourkela, Bokaro","Jamshedpur: ideal location — Jharia coal (32km) + Singhbhum iron ore (80km) + Subarnarekha river + Kolkata market","Automobile: Chennai = 'Detroit of India'; Gurgaon, Mumbai-Pune; Ford, Hyundai, BMW, Maruti have plants","Sugar: UP + Maharashtra = 70%; seasonal (cane must be processed within 24hrs); moving northward","Industrial pollution: water (effluents), air (smoke, SO₂), land (solid waste) — Ganga severely polluted","Bhopal Gas Tragedy (Dec 1984): Union Carbide MIC gas leak; 15,000+ killed; worst industrial disaster","SEZs and Make in India: government policy to attract manufacturing investment to boost secondary sector"],"formulas":"VALUE CHAIN:\nRaw material → Manufacturing → Finished good\nValue added = Revenue − Input cost\n\nINDUSTRY TYPES:\nBasic: iron/steel (supports all others)\nCapital goods: machinery, tools\nConsumer: textiles, food, electronics\n\nChota Nagpur = heavy industry cluster","exam":["Iron and steel = basic industry: steel enables machinery, railways, bridges — every other industry depends on it","Jamshedpur site analysis: raw material proximity + power + water + transport + market = textbook industrial location","Industrial pollution control: zero liquid discharge, electrostatic precipitators, green belts — laws exist but enforcement weak"]},{"id":11,"num":"Ch 1","subj":"polsci","title":"Power Sharing","oneshot":["Power sharing: distributing governmental authority so no single entity monopolizes power","Belgium: Dutch 59%, French 40%, German 1%; Brussels French 80%, Dutch 20%; 4 constitutional amendments 1970-93","Sri Lanka: Sinhala 74% (Buddhist), Tamil 18%; Sinhala Only Act (1956) → majoritarian → 30-year civil war","Belgian model: equal French+Dutch ministers; independent state govts; Brussels equal govt; community govt for culture"],"keypts":["Sri Lanka's majoritarian measures: Sinhala Only Act 1956; preferential university/job treatment for Sinhalas; Buddhism promoted","Tamil alienation: felt denied equal rights → TULF demanded Eelam → LTTE → Civil War 1983-2009; 80,000+ killed","Prudential reasons: reduces conflict, ensures stability, produces better outcomes than majority rule","Moral reasons: citizens' democratic right to participate; sharing power IS the spirit of democracy","4 forms: (1) Horizontal — organs (legislature/executive/judiciary); (2) Vertical — levels; (3) Social groups; (4) Political parties","Checks and balances: each organ checks the others; prevents any branch becoming all-powerful","Coalition government: multiple parties share power; must compromise; common when no party wins majority"],"formulas":"4 FORMS OF POWER SHARING:\n1. Horizontal → Legislature, Executive, Judiciary\n2. Vertical (Federal) → Central, State, Local\n3. Social groups → Community governments\n4. Political parties → Coalition, lobbying\n\nBelgium: Negotiated → Peace\nSri Lanka: Majoritarianism → Civil war","exam":["Belgium vs Sri Lanka: accommodation through power sharing → peace; majoritarianism → 30-year civil war (1983-2009)","Majoritarianism ≠ democracy: winning majority does not give right to suppress minorities","Power sharing is not weakness: distributing power prevents tyranny, builds trust, makes system stronger"]},{"id":12,"num":"Ch 2","subj":"polsci","title":"Federalism","oneshot":["Federalism: power constitutionally divided between central and state governments; both operate independently","India = 'Union of States' (not Federation) — holding-together federation; Centre stronger","3 Lists: Union (97 subjects), State (66 subjects), Concurrent (47 subjects, Centre prevails); Residuary → Centre","73rd Amendment (1992): Panchayati Raj constitutionally mandatory; 3-tier structure; 1/3 seats for women"],"keypts":["Coming-together: USA, Australia, Switzerland — independent states voluntarily united; states relatively stronger","Holding-together: India, Spain, Belgium — large country divided; Centre stronger; designed to prevent fragmentation","Federal features: written constitution, 3 lists, independent judiciary (SC as umpire), bicameral Parliament","Non-federal features: Governor (Centre-appointed), Emergency provisions, Centre can reorganise states, single citizenship","74th Amendment (1992): Urban local bodies — municipalities for towns, corporations for cities","Finance Commission: determines tax revenue sharing between Centre and States; appointed every 5 years","Gram Sabha: all adult voters of village; foundation of Panchayati Raj; elects Gram Panchayat","Decentralisation transfers power from Centre/State to local governments closest to people"],"formulas":"3 LISTS:\nUnion: 97 subjects (defence, foreign, currency)\nState: 66 subjects (police, agriculture, health)\nConcurrent: 47 subjects (education, forest)\nResiduary → Centre\n\nLOCAL GOVT:\nRural: Gram Panchayat → Panchayat Samiti → Zila Parishad\nUrban: Ward → Municipality/Corporation","exam":["India is quasi-federal: more federal than unitary BUT Centre clearly dominant (residuary, Governor, Emergency)","73rd Amendment significance: constitutional status for panchayats, mandatory elections, women's 1/3 reservation","Coalition era (1989-2014): no single party had majority; coalition forced power-sharing between Centre and regional parties"]},{"id":13,"num":"Ch 3","subj":"polsci","title":"Democracy and Diversity","oneshot":["Civil Rights Movement (USA 1954-68): Rosa Parks (1955 bus boycott), MLK Jr., Civil Rights Act 1964","Mexico Olympics 1968: Tommie Smith (gold) & John Carlos (bronze) raised Black Power salute — iconic protest image","Overlapping divisions (dangerous): same group disadvantaged across multiple dimensions — like Northern Ireland","Cross-cutting divisions (safer): groups opposing each other on one issue align on another — reduces intensity"],"keypts":["Three factors determining outcome: (1) identity perception (exclusive vs multiple), (2) political leaders' approach, (3) constitutional arrangements","Yugoslavia: Milosevic exploited Serb nationalism exclusively → ethnic cleansing → breakup into 6 countries → civil wars","India advantage: multiple overlapping identities (religion + language + caste + region) cross-cut → no single identity dominates","Northern Ireland: Catholics (poor, nationalist) vs Protestants (wealthy, unionist) — overlapping economic + religious divisions","Rosa Parks: refused to give bus seat in Montgomery 1955; sparked 381-day bus boycott; Supreme Court struck down segregation","Carom board analogy: game works when pieces of different colours mix; if all one colour goes to one side, game breaks down","Social differences can be expressed politically in democracy without leading to conflict if managed well","Belgium: language cuts across class lines (cross-cutting) → manageable; N. Ireland: religion + economics overlap → dangerous"],"formulas":"DIVISION OUTCOMES:\nOverlapping → Explosive conflict potential\nCross-cutting → Manageable tension\n\nFACTORS:\n1. Identity perception (exclusive vs multiple)\n2. Political leaders' approach\n3. Constitutional framework","exam":["Yugoslavia failed: Milosevic made Serb identity the ONLY legitimate identity; suppressed cross-cutting identities → civil war","Why India relatively successful: constitution protects minorities; multiple parties represent diverse groups; elections provide outlet","Democracy is the ONLY system that can manage diversity without violence — but needs institutions to protect all groups"]},{"id":14,"num":"Ch 4","subj":"polsci","title":"Gender, Religion and Caste","oneshot":["Gender division: social construct (not biological); society assigns different public/private roles to men and women","Patriarchy: male-dominated society; women subordinated; unequal wages, property rights, political representation","Communalism: using religion as exclusive political identity; one religion claims superiority; used against other groups","Caste in politics: caste influences voting; parties build caste-based coalitions; Dalit mobilization transformed politics"],"keypts":["Feminist movements: fought for equal wages, property rights, voting rights, education — changed legal frameworks globally","Women in politics: globally <10% of legislators; India ~12% Lok Sabha; Nordic countries 30-40%","73rd/74th Amendments: 1/3 panchayat/municipal seats reserved for women; some states now 50%","Secular state: no official religion; state treats all religions equally; Art. 25-28 protect all religious freedom","Communalism threatens democracy: creates division and violence; 1947 Partition, 1984 riots, 1992 post-Babri — communal cost","Caste and democracy: hierarchical system is undemocratic BUT caste-based mobilization brought representation to oppressed groups","Art. 15: No discrimination (religion, race, caste, sex) | Art. 17: Untouchability abolished and punishable","Mandal Commission (1979): recommended 27% OBC reservation; implemented 1990; major political watershed"],"formulas":"CONSTITUTIONAL PROVISIONS:\nArt. 14: Equality before law\nArt. 15: No discrimination\nArt. 17: Untouchability abolished\nArt. 25-28: Religious freedom\n\nWOMEN IN LEGISLATURES:\nIndia Lok Sabha: ~12%\nNordic countries: 30-40%\nWorld average: <15%","exam":["Caste census: last 1931; Mandal Commission estimated OBCs = 52%; 27% reservation politically contentious still","Gender pay gap: women earn 20-30% less globally for similar work — reflects patriarchal assumptions about women's labour","Religion in politics: constitutional secularism allows religious practice but Representation of People Act prohibits using religion for votes"]},{"id":15,"num":"Ch 5","subj":"polsci","title":"Political Parties","oneshot":["Political party: organized group with shared ideology that contests elections to capture power and shape policy","Functions: contest elections, frame policies, form government, play opposition, express and shape public opinion","National party: 6% votes in 4 states OR 2% LS seats from 3 states OR 4 LS seats — recognition by Election Commission","Pressure groups: FICCI, trade unions, farmers' groups — influence power without seeking power directly"],"keypts":["INC: centrist; founded 1885; led independence movement; Nehru-Gandhi dynasty; pluralist ideology","BJP: right-wing Hindu nationalism; founded 1980 (from Jana Sangh); Vajpayee, Modi; NDA alliances","BSP: Dalit/oppressed classes movement; Kanshi Ram (1984); Mayawati; social justice focus; UP base","CPM: Marxist-Leninist; Kerala and West Bengal historically; Jyoti Basu, EMS Namboodiripad","Challenges: dynastic politics (INC, SP, RJD, DMK), money-muscle power, criminalization, lack of internal democracy","Reforms needed: RTI for parties, mandatory internal elections, criminal disqualification, campaign finance transparency","India's multi-party system reflects diversity; coalition era 1989-2014; BJP single-party majority 2014 and 2019","One-party (China): authoritarian | Two-party (USA/UK): stable | Multi-party (India/France): diverse but coalitions needed"],"formulas":"PARTY RECOGNITION:\nNational: 6%+ in 4 states OR 2% LS seats from 3 states\nState: 6%+ in state elections\n\nPARTY vs PRESSURE GROUP:\nParty → seeks power (contests elections)\nPressure group → influences those with power","exam":["India's multi-party system: many parties represent different regions, religions, castes; coalition era forced power-sharing","Dynastic politics: INC (Nehru→Indira→Rajiv→Sonia→Rahul) — limits meritocracy, reduces leadership diversity","Electoral reforms implemented: EVMs, VVPAT, model code of conduct, expenditure limits — but enforcement remains weak"]},{"id":16,"num":"Ch 6","subj":"polsci","title":"Outcomes of Democracy","oneshot":["Democracy produces: accountable government, peaceful power transfer, political equality, minority rights protection","Democracy does NOT guarantee: economic growth, social equality, corruption-free governance","Popular legitimacy: losing side accepts election results — unique to democracy; prevents post-election civil conflict","RTI Act 2005: citizens can demand information from any government body within 30 days — landmark transparency law"],"keypts":["Arguments FOR: peaceful conflict resolution, citizens' dignity, freedom, equality of opportunity, accountability","Arguments AGAINST: slow decisions, panders to vote banks, corruption possible, weak leadership, populism over policy","Economic outcomes: no strong evidence democracies grow faster; but political stability attracts long-term investment","Social outcomes: democracy reduced extreme forms of caste discrimination and gender injustice in India — not eliminated","NREGA 2005: 100 days guaranteed rural employment; democratic demand fulfilled; ~200 million households benefited","RTE 2009: free education ages 6-14; universal elementary education — democratic pressure delivered this right","Transparency: democracies more open than autocracies; free press and RTI are best anti-corruption tools","Churchill: 'Democracy is the worst form of government, except for all the others'"],"formulas":"ACCOUNTABILITY TOOLS:\nElections → Citizens evaluate performance\nRTI 2005 → Demand government information\nFree press → Public scrutiny\nJudiciary → Check on power\nCAG → Audit government spending\n\nDEMOCRATIC OUTCOMES:\nRTI 2005 | NREGA 2005 | RTE 2009","exam":["Popular legitimacy: even losers accept result → peaceful power transfer → political stability → economic confidence","Tyranny of majority: even democracies can oppress minorities without constitutional protections — India's minority provisions essential","Why democracy despite flaws: peaceful succession, accountability, dignity — no better alternative has been found yet"]},{"id":17,"num":"Ch 1","subj":"eco","title":"Development","oneshot":["Development: process of growing better; includes material goals (income, goods) AND non-material (freedom, dignity)","Per capita income = Total National Income ÷ Total Population; main World Bank criterion for classifying countries","HDI: UNDP measure combining life expectancy + education + per capita income — more comprehensive than income alone","Sustainable development: meeting present needs without compromising future generations' ability to meet theirs (Brundtland 1987)"],"keypts":["World Bank (2019): >$12,056 per capita = high income; India = lower middle income (~$2000)","HDI rank: India ~132 of 192 ('medium human development'); Norway tops; HDI focuses on people, not just money","Life expectancy: India ~69.7 years; Kerala ~77 years — good proxy for healthcare quality","IMR (Infant Mortality Rate): deaths under 1 year per 1000 live births; India ~29; Kerala ~7 (world-class)","Literacy rate: India ~77.7%; Kerala ~94% (best); Bihar ~63% (lowest); critical for human capital","Kerala vs Punjab: Kerala lower per capita income BUT higher literacy + life expectancy → income ≠ development","Net Attendance Ratio: % of class 6-10 children actually attending school; measures educational access in practice","BMI: weight(kg)/height²(m²); below 18.5 = underweight/malnourished; proxy for nutritional development"],"formulas":"PER CAPITA INCOME = Total National Income / Total Population\n\nHDI SCALE:\n0.8+ = Very High (Norway, Denmark)\n0.7-0.8 = High\n0.55-0.7 = Medium (India ~0.633)\n<0.55 = Low\n\nINDIA:\nLife expectancy: ~69.7 years\nLiteracy: ~77.7%\nIMR: ~29 per 1000 live births","exam":["Kerala vs Punjab: Kerala invests in public health and education → better human development despite lower income","HDI vs per capita income: income only captures economic dimension; HDI adds health and education — more complete picture","Sustainability crisis: India's groundwater depletion, deforestation threaten future development — present growth undermining future welfare"]},{"id":18,"num":"Ch 2","subj":"eco","title":"Sectors of Indian Economy","oneshot":["Primary sector: uses natural resources (agriculture, fishing, mining, forestry)","Secondary sector: transforms raw materials into products (manufacturing, construction)","Tertiary sector: services facilitating production and distribution (banking, IT, transport, education, healthcare)","Unorganised sector: 93% of India's 500 million workers; no labour law protection, no job security"],"keypts":["GDP paradox: Primary employs ~50% but only 15% of GDP; Tertiary employs ~30% but contributes ~60% of GDP","Structural transformation: as economy develops, primary share falls, tertiary rises — India needs faster transition","Disguised unemployment: more workers than needed; removing some won't reduce output; common in family farms","Seasonal unemployment: only available in certain seasons; agricultural labourers idle in off-season","NREGA (2005): 100 days guaranteed wage employment per rural household; 50%+ women participants","Formal sector: ~7% of workers; higher wages, security, social benefits | Informal: 93%, lower wages, no security","Sunrise industries: IT, pharma, telecom, biotech — rapidly growing, high value-added","Services paradox: tertiary sector largest in GDP but doesn't employ proportionally — structural imbalance"],"formulas":"SECTOR SHARES (approx):\nPrimary: employs 50%, contributes 15% GDP\nSecondary: employs 20%, contributes 25% GDP\nTertiary: employs 30%, contributes 60% GDP\n\nUNEMPLOYMENT TYPES:\nDisguised: extra workers, zero marginal product\nSeasonal: only certain months (agriculture)\nStructural: skills mismatch with available jobs","exam":["Services paradox: tertiary biggest in GDP but not in employment; need manufacturing to absorb agricultural workforce","NREGA: first legal employment guarantee in India; transformed rural distress; women's participation >50%","Formalisation challenge: 93% informal workers lack basic protections — need universal social security, easy compliance"]},{"id":19,"num":"Ch 3","subj":"eco","title":"Money and Credit","oneshot":["Barter problem: double coincidence of wants — both parties must want what the other offers simultaneously","Money functions: medium of exchange, unit of account, store of value, standard of deferred payment","Formal credit: banks/cooperatives; 5-12% interest; collateral needed; RBI-regulated; legally protected","Informal credit: moneylenders; 30-60%+ interest; unregulated; debt traps; exploitative but accessible to poor"],"keypts":["RBI: central bank; issues currency; controls money supply via repo rate, CRR, SLR; banker to banks and government","Bank loans need collateral (property, gold, FDs); poor excluded from formal credit → financial exclusion","Demand deposits: withdrawable on demand; function as money through cheques, NEFT, UPI — expand money supply","Debt trap: borrow at high interest; crop fails; can't repay; re-borrow; interest exceeds income; sell land; bonded labour","SHGs: 15-20 rural poor (mostly women); save regularly; lend at ~12% vs moneylenders' 30-60%; 95%+ repayment","Grameen Bank (Bangladesh): Muhammad Yunus; pioneered microfinance; Nobel Prize 2006; SHG model inspired by it","NABARD: apex institution supporting agricultural and rural credit through cooperative banks and SHG linkage","Credit multiplier: bank keeps CRR with RBI, lends rest; that loan deposited again → money supply multiplied"],"formulas":"RBI TOOLS:\nRepo Rate: rate RBI lends to banks\nReverse Repo: rate RBI borrows from banks\nCRR: % deposits kept with RBI\nSLR: % in approved securities\n\nINTEREST RATES:\nFormal (banks): 5-12% per year\nInformal (moneylenders): 30-60%+ per year\nSHGs: ~12% per year","exam":["Why poor can't access formal credit: no collateral, no credit history, complex docs, no nearby bank → stuck with moneylenders","RBI controls inflation: raise repo rate → banks borrow less → lend less → money supply falls → prices stabilize","SHG model works: peer pressure ensures repayment; group support helps businesses; women's empowerment is byproduct"]},{"id":20,"num":"Ch 4","subj":"eco","title":"Globalisation and the Indian Economy","oneshot":["Globalisation: integration of economies, markets, production, capital across national borders — single global market","MNC: company controlling production in multiple countries; seeks cheapest inputs and largest markets","LPG reforms (India 1991): Liberalisation + Privatisation + Globalisation; PM Narasimha Rao + FM Manmohan Singh","WTO (1995): promotes free trade; 164 members; reduces tariffs; resolves trade disputes between nations"],"keypts":["Global value chains: iPhone designed USA, chips Taiwan, assembled China, software India — product crosses 10+ borders","Technology enablers: internet, mobile phones, container shipping (cost fell 90% since 1950s)","India's 1991 LPG: tariffs 350% → 30%; licence raj reduced; FDI allowed; GDP growth jumped to 6-7% average","Positive effects: IT boom ($200B exports, TCS/Infosys global), pharma exports (40% global generics), consumer choice","Negative effects: small industry disruption (Chinese toys/electronics), contract jobs, farmer pressure, inequality widened","SEZ (Special Economic Zone): liberal tax/trade rules; attracts FDI; India has 400+ SEZs","Fair Trade: ensures producers get fair stable prices despite commodity price volatility; labelling system for consumers","MNCs in developing world: bring capital and technology but may exploit cheap labour and repatriate profits"],"formulas":"GLOBALISATION ENABLERS:\n1. ICT: internet, mobile, satellites\n2. Transport: container ships, air cargo\n3. Trade policy: WTO, FTAs, removal of barriers\n\nINDIA TRADE:\nExports: IT software, pharma, gems, textiles\nImports: Crude oil (35%), electronics, gold, machinery\n\nLPG = Liberalisation + Privatisation + Globalisation","exam":["Globalisation's India story: winners (IT workers, exporters, consumers) vs losers (small manufacturers, traditional artisans, farmers)","Why India leads in services but not manufacturing: cheap English-speaking graduates for IT; manufacturing needs infrastructure reform","Fair globalisation requires: strong labour laws, agricultural support, skill development, social safety nets for all Indians"]}];
export const SSC_MCQS: SscMCQ[] = [{"id":1,"ch":1,"subj":"hist","diff":"easy","q":"The female allegory representing France during 19th century nationalism was:","opts":["Germania","Marianne","Helvetia","Britannia"],"ans":1,"exp":"Marianne — a popular French name — represented the French Republic. Germania represented Germany. These female allegories gave abstract nations a human identity that citizens could rally behind."},{"id":2,"ch":1,"subj":"hist","diff":"easy","q":"Zollverein (1834) was a customs union that:","opts":["Created a military alliance","Removed tariff barriers between German states","Established Frankfurt Parliament","United Germany under Prussia politically"],"ans":1,"exp":"Zollverein led by Prussia in 1834 removed internal tariffs, creating a single German market and common currency. This economic integration preceded political unification (1871) by 37 years. Economic self-interest proved a more powerful driver of unity than nationalist ideology alone."},{"id":3,"ch":1,"subj":"hist","diff":"medium","q":"Who called Germany and Italy 'geographical expressions'?","opts":["Napoleon Bonaparte","Otto von Bismarck","Metternich","Mazzini"],"ans":2,"exp":"Metternich, Austrian Chancellor, used this phrase to dismiss nationalism as dangerous liberal fantasy. He represented the conservative order restored by Congress of Vienna (1815) and actively suppressed nationalist movements across Europe."},{"id":4,"ch":2,"subj":"hist","diff":"easy","q":"The Rowlatt Act (1919) was opposed because it:","opts":["Imposed high taxes","Allowed imprisonment without trial for 2 years","Banned the INC","Divided Bengal"],"ans":1,"exp":"The Rowlatt Act ('Black Act') allowed imprisonment without trial for 2 years for suspected revolutionaries. Gandhi called it a fundamental violation of civil liberties — wartime emergency powers extended into peacetime. He organised nationwide hartals, beginning his first mass agitation."},{"id":5,"ch":2,"subj":"hist","diff":"easy","q":"Gandhi suspended Non-Cooperation Movement (1922) after violence at:","opts":["Lahore","Amritsar","Chauri Chaura","Bardoli"],"ans":2,"exp":"At Chauri Chaura (UP), February 1922, an angry crowd burnt a police chowki killing 22 constables. Gandhi immediately suspended NCM — believing non-violence must be maintained even at political cost. 'A violent movement loses its moral authority.'"},{"id":6,"ch":2,"subj":"hist","diff":"medium","q":"Gandhi chose salt for the 1930 Civil Disobedience Movement because:","opts":["Salt was British's most profitable export","Salt affected every Indian equally — rich or poor, Hindu or Muslim","Salt was the easiest law to break","British had taxed salt since Mughal era"],"ans":1,"exp":"Salt was a universal necessity — every Indian needed it regardless of class or religion. Breaking the salt law was symbolic and accessible — anyone anywhere could make salt from seawater. The Dandi March (240 miles, 24 days) gained massive international attention for India's cause."},{"id":7,"ch":2,"subj":"hist","diff":"easy","q":"Jallianwala Bagh massacre (April 13, 1919) took place in:","opts":["Lahore","Delhi","Amritsar","Bombay"],"ans":2,"exp":"General Dyer ordered troops to fire on an unarmed Baisakhi crowd at Jallianwala Bagh, Amritsar. Exits were blocked; 379-1000+ killed. The massacre destroyed faith in 'benevolent' British rule and turned moderates into nationalists."},{"id":8,"ch":3,"subj":"hist","diff":"medium","q":"The Great Depression (1929) began with:","opts":["A severe drought in USA","World War I reparations","Wall Street stock market crash","Banking crisis in Germany"],"ans":2,"exp":"The Great Depression was triggered by the Wall Street crash in October 1929. US banks failed, unemployment reached 25%, global trade fell 65%. In India, agricultural prices crashed and economic desperation helped fuel the Civil Disobedience Movement (1930)."},{"id":9,"ch":3,"subj":"hist","diff":"medium","q":"Bretton Woods Conference (1944) established:","opts":["United Nations and NATO","IMF and World Bank","WTO and G20","GATT and UNCTAD"],"ans":1,"exp":"Bretton Woods (New Hampshire, 1944) created the IMF (to maintain stable exchange rates) and World Bank (for development finance). These institutions shaped the post-WW2 monetary order and still operate today."},{"id":10,"ch":4,"subj":"hist","diff":"easy","q":"The first book printed by Gutenberg's press was:","opts":["A newspaper","The Quran","The Bible","A Greek poem collection"],"ans":2,"exp":"Gutenberg printed 180 copies of the Bible in approximately 3 years — compared to years per copy by hand. His press adapted the screw-press technology from wine-making, combined with metal movable type. A revolutionary achievement that transformed communication in Europe."},{"id":11,"ch":5,"subj":"geo","diff":"easy","q":"Which soil type is best suited for cotton cultivation?","opts":["Alluvial soil","Red and yellow soil","Black soil (Regur)","Laterite soil"],"ans":2,"exp":"Black soil (Regur) is ideal for cotton: it retains moisture well, has self-ploughing property (swells when wet, cracks when dry), and is rich in Ca, Mg, and K. Found mainly in the Deccan Plateau (Maharashtra, MP, Gujarat, parts of AP)."},{"id":12,"ch":5,"subj":"geo","diff":"easy","q":"The most widespread soil type in India is:","opts":["Black soil","Red and yellow soil","Alluvial soil","Laterite soil"],"ans":2,"exp":"Alluvial soil covers ~44% of India's total land area. Deposited by rivers (Indus, Ganga, Brahmaputra) across the northern plains, it is India's most fertile soil. Khadar (newer, flood plains, more fertile) vs Bhangar (older, elevated, kankar nodules)."},{"id":13,"ch":6,"subj":"geo","diff":"easy","q":"The Chipko Movement (1970s, Uttarakhand) was aimed at:","opts":["Conserving wildlife","Preventing deforestation by hugging trees","Protesting against dams","Saving water resources"],"ans":1,"exp":"'Chipko' means 'to cling/hug'. Villagers led by Gaura Devi hugged trees to prevent contractors from cutting them. India's first major grassroots environmental movement; led to a 15-year ban on tree felling in the Himalayas."},{"id":14,"ch":7,"subj":"geo","diff":"easy","q":"India's HIGHEST dam — Tehri Dam — is built on which river?","opts":["Sutlej","Mahanadi","Bhagirathi","Krishna"],"ans":2,"exp":"Tehri Dam on the Bhagirathi River, Uttarakhand (~261m) is India's highest dam. Bhakra Nangal = Sutlej (Punjab/HP); Hirakud = Mahanadi (Odisha); Nagarjuna Sagar = Krishna (AP); Sardar Sarovar = Narmada (Gujarat)."},{"id":15,"ch":8,"subj":"geo","diff":"easy","q":"Which of these is a KHARIF crop?","opts":["Wheat","Gram","Mustard","Cotton"],"ans":3,"exp":"Kharif crops are sown with SW monsoon (June-July), harvested Oct-Nov: Rice, Cotton, Jute, Maize, Groundnut, Soybean. Rabi crops (sown Oct-Nov, harvested March-April): Wheat, Gram, Mustard, Barley."},{"id":16,"ch":8,"subj":"geo","diff":"medium","q":"'Jhumming' (shifting cultivation) is practiced mainly in:","opts":["Punjab and Haryana","North-East India","Rajasthan","Andhra Pradesh"],"ans":1,"exp":"Jhumming (Jhum cultivation): slash-and-burn practiced by tribal communities in NE India (Nagaland, Mizoram, Meghalaya, Assam). Forest cleared, crops grown 2-3 years until soil exhausted, then abandoned for recovery. Unsustainable with increasing population."},{"id":17,"ch":9,"subj":"geo","diff":"easy","q":"The largest petroleum-producing region in India is:","opts":["Digboi (Assam)","Ankleshwar (Gujarat)","Mumbai High (offshore)","Barmer (Rajasthan)"],"ans":2,"exp":"Mumbai High offshore field contributes approximately 60-65% of India's domestic crude oil. Digboi (Assam, 1867) is the oldest field. India still imports ~85% of petroleum requirements despite domestic production."},{"id":18,"ch":9,"subj":"geo","diff":"medium","q":"India holds ~25% of world's reserves of which nuclear fuel?","opts":["Uranium","Plutonium","Thorium","Radium"],"ans":2,"exp":"India has the world's largest thorium reserves found in monazite sands along Kerala, Tamil Nadu, and AP coasts. Thorium is planned as the ultimate fuel in India's 3-stage nuclear program — could provide energy for centuries."},{"id":19,"ch":10,"subj":"geo","diff":"easy","q":"Ahmedabad is called 'Manchester of India' because of its:","opts":["IT industry","Cotton textile industry","Iron and steel","Automobiles"],"ans":1,"exp":"Ahmedabad earned 'Manchester of India' for its large-scale cotton textile industry. Like Manchester, it had access to Gujarat's cotton, humid climate, river water, and cheap labour. The first cotton mill was established in 1861."},{"id":20,"ch":10,"subj":"geo","diff":"hard","q":"The Bhopal Gas Tragedy (1984) involved leakage of:","opts":["Chlorine gas","Ammonia","Methyl Isocyanate (MIC)","Sulfur dioxide"],"ans":2,"exp":"MIC leaked from Union Carbide's pesticide plant in Bhopal, Dec 2-3, 1984. World's worst industrial disaster — 15,000+ killed immediately, 600,000+ affected. Led to stricter environmental laws and global discussion of corporate liability."},{"id":21,"ch":11,"subj":"polsci","diff":"easy","q":"Belgium amended its constitution how many times between 1970 and 1993?","opts":["Two times","Three times","Four times","Six times"],"ans":2,"exp":"Belgium amended its constitution FOUR TIMES (1970, 1980, 1988, 1993). Key changes: equal French and Dutch ministers in central govt; independent regional governments; Brussels equal-representation govt; community govt for cultural/educational matters. Peaceful accommodation prevented civil war."},{"id":22,"ch":11,"subj":"polsci","diff":"easy","q":"Sri Lanka's 'Sinhala Only Act' was passed in:","opts":["1947","1956","1972","1983"],"ans":1,"exp":"1956: Sinhala Only Act made Sinhala the sole official language, excluding Tamil (18% of population). This majoritarian move led to Tamil alienation, discrimination, formation of LTTE, and civil war (1983-2009) killing 80,000+."},{"id":23,"ch":11,"subj":"polsci","diff":"medium","q":"Power sharing among legislature, executive, and judiciary is called:","opts":["Vertical distribution","Horizontal distribution of power","Community government","Coalition government"],"ans":1,"exp":"Horizontal distribution: legislature makes laws, executive implements, judiciary interprets and can strike down laws. Each checks and balances the others. No single organ becomes all-powerful — prevents tyranny."},{"id":24,"ch":12,"subj":"polsci","diff":"easy","q":"India's Constitution divides legislative powers through how many lists?","opts":["One list","Two lists","Three lists","Four lists"],"ans":2,"exp":"Three Lists: Union List (97 subjects — defence, foreign affairs, currency), State List (66 subjects — police, agriculture), Concurrent List (47 subjects — education, forests). Residuary powers go to Centre."},{"id":25,"ch":12,"subj":"polsci","diff":"medium","q":"The 73rd Constitutional Amendment (1992) made which system constitutionally mandatory?","opts":["State elections","Panchayati Raj (3-tier local government)","Parliamentary elections","Rajya Sabha elections"],"ans":1,"exp":"73rd Amendment (1992) made Panchayati Raj mandatory in all states: Gram Panchayat → Panchayat Samiti → Zila Parishad. Required 5-year elections, SC/ST reservations, 1/3 seats for women. 74th Amendment covered urban local bodies."},{"id":26,"ch":13,"subj":"polsci","diff":"easy","q":"Tommie Smith and John Carlos raised a Black Power salute at:","opts":["1960 Rome Olympics","1964 Tokyo Olympics","1968 Mexico City Olympics","1972 Munich Olympics"],"ans":2,"exp":"At the 1968 Mexico City Olympics, Smith (gold) and Carlos (bronze) raised black-gloved fists on the podium during the US anthem, protesting racial discrimination. Both were suspended. Australian silver medalist Peter Norman wore an OPHR badge in solidarity."},{"id":27,"ch":14,"subj":"polsci","diff":"easy","q":"Article 17 of the Indian Constitution deals with:","opts":["Right to free speech","Abolition of untouchability","Right to education","Freedom of religion"],"ans":1,"exp":"Article 17 abolishes 'untouchability' and makes its practice punishable by law. Protection of Civil Rights Act (1955) and SC/ST Atrocities Act (1989) provide legal protection. Despite constitutional abolition, social discrimination continues in practice."},{"id":28,"ch":15,"subj":"polsci","diff":"medium","q":"A party is recognised as 'national' if it secures at least ___% votes in LS elections in 4 states:","opts":["4%","6%","8%","10%"],"ans":1,"exp":"National party: (a) 6%+ votes in LS elections in 4 states, OR (b) 2%+ LS seats from 3 states, OR (c) 4 LS seats. Current national parties: INC, BJP, BSP, CPM, NCP, AITC, NCP(SP). Recognition gives advantages like official symbols and free broadcast time."},{"id":29,"ch":15,"subj":"polsci","diff":"medium","q":"The main difference between a political party and a pressure group:","opts":["Parties have more members","Parties seek power; pressure groups influence those with power","Pressure groups contest elections","Parties only represent business interests"],"ans":1,"exp":"Political parties directly seek power — contest elections, form governments, make laws. Pressure groups (FICCI, trade unions) do NOT contest elections — they lobby and influence those in power to adopt certain policies."},{"id":30,"ch":16,"subj":"polsci","diff":"medium","q":"The Right to Information (RTI) Act was passed in India in:","opts":["2000","2002","2005","2010"],"ans":2,"exp":"RTI Act 2005: citizens can demand information from any government body within 30 days. Landmark transparency law — reduced corruption by exposing government files and spending. Inspired by MKSS movement in Rajasthan led by Aruna Roy."},{"id":31,"ch":17,"subj":"eco","diff":"easy","q":"Per capita income is calculated as:","opts":["Total Exports / Population","Total National Income / Total Population","Total Tax Revenue / Population","Total Savings / Population"],"ans":1,"exp":"Per Capita Income = Total National Income ÷ Total Population. World Bank uses this to classify countries. KEY LIMITATION: it's an average that hides inequality — a country can have high per capita income with most wealth concentrated in few hands."},{"id":32,"ch":17,"subj":"eco","diff":"easy","q":"HDI (Human Development Index) is published by:","opts":["World Bank","IMF","UNDP","WTO"],"ans":2,"exp":"UNDP publishes the annual Human Development Report with HDI rankings. HDI combines: life expectancy, education (mean + expected years of schooling), and GNI per capita (PPP). India ranks ~132 of 192 ('medium human development')."},{"id":33,"ch":18,"subj":"eco","diff":"easy","q":"Which of these belongs to the TERTIARY sector?","opts":["Agriculture and fishing","Manufacturing and construction","Banking, IT, and transport","Mining and quarrying"],"ans":2,"exp":"Tertiary sector = services: banking, insurance, IT, transport, communication, retail, education, healthcare. Contributes ~60% of India's GDP — largest share. India is primarily a service economy."},{"id":34,"ch":18,"subj":"eco","diff":"medium","q":"'Disguised unemployment' means:","opts":["Workers hiding employment status","More workers than needed; removing some won't reduce output","Workers employed but not paid","Unemployment only in cities"],"ans":1,"exp":"Disguised unemployment: marginal productivity of extra workers = zero. 5 family members doing work that 2 can do — 3 are disguisedly unemployed. Appear employed but produce nothing additional. Very common in Indian subsistence agriculture."},{"id":35,"ch":19,"subj":"eco","diff":"easy","q":"The main problem with the barter system was:","opts":["Lack of goods","Double coincidence of wants","Inflation","Long distances"],"ans":1,"exp":"Double coincidence of wants: for barter, Person A must want what B offers AND B must want what A offers — simultaneously. This is extremely difficult to arrange. Money solves this by acting as universal medium everyone accepts."},{"id":36,"ch":19,"subj":"eco","diff":"easy","q":"Currency notes in India are issued by:","opts":["Finance Ministry","State Bank of India","Reserve Bank of India","SEBI"],"ans":2,"exp":"RBI issues all currency notes (Rs 2, 5, 10, 20, 50, 100, 200, 500, 2000). Exception: Rs 1 coin issued by Finance Ministry. RBI is 'banker's bank' and 'government's bank', controls money supply and maintains financial stability."},{"id":37,"ch":19,"subj":"eco","diff":"medium","q":"Self Help Groups (SHGs) primarily help by:","opts":["Building roads","Providing microfinance at lower interest rates","Distributing food ration","Running government schools"],"ans":1,"exp":"SHGs (15-20 rural poor, mostly women) save small amounts regularly and pool for member loans at ~12% interest — far lower than moneylenders' 30-60%. No collateral needed; 95%+ repayment rates. Inspired by Grameen Bank (Bangladesh, Muhammad Yunus, Nobel 2006)."},{"id":38,"ch":20,"subj":"eco","diff":"easy","q":"India's 'LPG reforms' (1991) stand for:","opts":["Liquefied Petroleum Gas prices","Liberalisation, Privatisation, Globalisation","Labour, Planning, Growth","Land, Poverty, Governance"],"ans":1,"exp":"India's 1991 economic reforms: L=Liberalisation (removing licence raj), P=Privatisation (opening to private investment), G=Globalisation (reducing tariffs from 350% to ~30%, allowing FDI). PM Narasimha Rao + FM Manmohan Singh. Transformed India from closed to market-oriented economy."},{"id":39,"ch":20,"subj":"eco","diff":"medium","q":"WTO primarily aims to:","opts":["Lend money to poor countries","Promote free trade and reduce trade barriers","Control global exchange rates","Regulate MNCs"],"ans":1,"exp":"WTO (World Trade Organisation, founded 1995): promotes free international trade by reducing tariffs, quotas, and non-tariff barriers. 164 member countries. Also resolves trade disputes between members."},{"id":40,"ch":20,"subj":"eco","diff":"hard","q":"A company controlling production in multiple countries is called:","opts":["Cooperative society","Public sector enterprise","Multinational Corporation (MNC)","Regional trading bloc"],"ans":2,"exp":"MNC: company owning or controlling production in multiple countries. Examples: Ford, Apple, Samsung, Amazon, TCS. Invest (FDI) in developing countries for cheap labour, raw materials, or large markets. Bring capital and technology but may exploit cheap labour and repatriate profits."}];
export const SSC_SHORT_QA: SscQA[] = [{"id":1,"ch":1,"subj":"hist","marks":2,"q":"What was Satyagraha? Explain its key principles.","a":"Satyagraha (Truth-Force/Soul-Force): Gandhi's philosophy of non-violent resistance to injustice.\n\nKEY PRINCIPLES:\n1. TRUTH: The cause must be genuinely just; not for selfish interest\n2. NON-VIOLENCE: No physical force — even against oppressors\n3. SUFFERING: Accepting pain demonstrates strength of conviction\n4. PERSUASION: Aim is to convert opponents, not defeat them\n5. SELF-DISCIPLINE: Satyagrahi must control impulses even under provocation\n\nWHY REVOLUTIONARY:\n• Physical force was NOT necessary to fight injustice — truth itself was powerful\n• Could mobilize women, students, and peasants who couldn't fight militarily\n• Gained international moral sympathy — exposed British brutality to the world\n\nKey campaigns: Champaran 1917, Non-Cooperation 1920, Civil Disobedience 1930, Quit India 1942"},{"id":2,"ch":2,"subj":"hist","marks":2,"q":"What were the effects of World War I on India?","a":"ECONOMIC EFFECTS:\n1. Raised custom duties → increased prices of goods\n2. Income tax introduced → burdened middle class\n3. Forced military recruitment from rural areas → anger\n4. Goods prices rose → hit lower and middle classes\n5. Crop failures (1918-19) → famine and influenza epidemic\n6. 12-13 million deaths from famine and disease linked to war\n\nPOLITICAL IMPACT:\n1. Britain promised Dominion Status for war support — then didn't deliver → betrayal\n2. Returning soldiers brought political awareness\n3. Economic hardships created masses ready to join Gandhi's movements\n4. Rowlatt Act (1919) extended war powers into peacetime → triggered Non-Cooperation Movement\n5. The war showed Indians could resist — Britain needed India militarily"},{"id":3,"ch":3,"subj":"hist","marks":2,"q":"How did the Great Depression (1929) affect India?","a":"AGRICULTURE (WORST AFFECTED):\n• Commodity prices (cotton, jute, wheat) fell by 50%+\n• Farmers sold more produce to pay the same fixed land revenue\n• Deep debt; moneylenders pressed for repayment\n• Bengal jute farmers worst hit\n\nINDUSTRY:\n• Textile mills closed; workers laid off\n• But tariff protection helped some domestic industries grow\n\nGOVERNMENT RESPONSE:\n• Refused to reduce land revenue → increased resentment\n• British policy prioritised British over Indian interests\n\nPOLITICAL IMPACT:\n• Desperate peasants and workers joined Civil Disobedience Movement 1930\n• Salt march resonated with all classes\n• Depression proved British rule served British interests, not India's"},{"id":4,"ch":4,"subj":"hist","marks":2,"q":"How did the printing press contribute to nationalism in India? Give 3 examples.","a":"1. NATIONALIST NEWSPAPERS:\n• Tilak's Kesari and Maratha: exposed British policies, fired nationalist sentiment\n• Maulana Azad's Al Hilal: mobilised Muslim nationalist opinion\n• Vernacular newspapers created reading publics in Hindi, Bengali, Tamil, Marathi\n\n2. SOCIAL REFORM:\n• Raja Ram Mohan Roy used Sambad Kaumudi to campaign against sati\n• Print enabled reformers to reach people across geography\n• Translated Western ideas of equality into Indian languages\n\n3. COLONIAL REACTION PROVES POWER:\n• Vernacular Press Act (1878): colonial govt censored Indian press — proves how feared print was\n• Newspapers became instruments of resistance; crackdowns created nationalist martyrs\n\nOVERALL: Print created a national reading community → 'imagined community' of nation"},{"id":5,"ch":5,"subj":"geo","marks":2,"q":"Distinguish between renewable and non-renewable resources with examples.","a":"RENEWABLE RESOURCES:\nDefinition: Replenished naturally in a short period; NOT permanently depleted by use\nExamples:\n• Solar energy: replenished every day — infinite potential\n• Wind energy: continuously available; using it doesn't reduce supply\n• Forests: if planted at same rate as cut, they regenerate\n• Water: replenished through the hydrological cycle\n\nNON-RENEWABLE RESOURCES:\nDefinition: Take millions of years to form; once used, cannot be regenerated — FINITE stock\nExamples:\n• Coal: formed over 300 million years from ancient forests; burning destroys it permanently\n• Petroleum: formed from marine organisms over millions of years; finite stock\n• Minerals (iron ore, copper, gold): geological formation took millions of years\n\nKEY: Sustainable development requires transitioning from non-renewable to renewable energy (Agenda 21, Rio 1992)"},{"id":6,"ch":7,"subj":"geo","marks":2,"q":"What are the advantages and disadvantages of multi-purpose river projects (dams)?","a":"ADVANTAGES:\n1. IRRIGATION: Year-round water supply; Bhakra Nangal transformed Punjab agriculture\n2. HYDROELECTRIC POWER: Clean renewable electricity (Tehri, Hirakud)\n3. FLOOD CONTROL: Regulates seasonal flooding downstream\n4. DRINKING WATER: Supplies towns and cities\n5. NAVIGATION: Deeper reservoirs for river transport\n\nDISADVANTAGES:\n1. DISPLACEMENT: Millions displaced without adequate rehabilitation\n   → Narmada Bachao Andolan: 250,000+ displaced by Sardar Sarovar\n2. ECOSYSTEM DAMAGE: River valleys destroyed; fish migration blocked\n3. SILTATION: Reservoirs fill with silt → reduced storage capacity\n4. METHANE EMISSIONS: Submerged vegetation decomposes → greenhouse gas\n5. SEISMICITY: Large water bodies can trigger earthquakes\n6. HIGH COST: Extremely expensive; often over budget"},{"id":7,"ch":8,"subj":"geo","marks":2,"q":"What is the Green Revolution? Describe its benefits and problems.","a":"GREEN REVOLUTION (1960s): HYV seeds + chemical fertilisers + irrigation\nCENTRES: Punjab, Haryana, Western UP\n\nBENEFITS:\n1. India became food self-sufficient — ended dependence on foreign food aid\n2. Wheat production tripled; Punjab became India's granary\n3. Reduced risk of famine\n4. Farmers' incomes increased in benefited regions\n5. Created jobs in fertiliser, pesticide, irrigation industries\n\nPROBLEMS:\n1. REGIONAL INEQUALITY: Only Punjab/Haryana/UP benefited; Eastern India left behind\n2. SOIL DEGRADATION: Overuse of chemicals depleted organic matter; salinity problems\n3. GROUNDWATER DEPLETION: Punjab water table falls 1 metre per year\n4. FARMER DEBT: Must buy HYV seeds every year; costly inputs\n5. HEALTH IMPACTS: Pesticide residues in food; cancer rates in Punjab 'cancer train' villages"},{"id":8,"ch":9,"subj":"geo","marks":2,"q":"Name main types of minerals in India with one example location each.","a":"FERROUS METALLIC:\n1. Iron Ore — Jharkhand (Singhbhum), Odisha (Keonjhar), Chhattisgarh (Bailadila)\n2. Manganese — Odisha, Karnataka, Madhya Pradesh\n\nNON-FERROUS METALLIC:\n3. Copper — Singhbhum (Jharkhand), Balaghat (MP)\n4. Bauxite — Odisha (Panchpatmali = largest), Jharkhand\n5. Gold — Kolar (Karnataka)\n\nNON-METALLIC:\n6. Mica — Jharkhand (Koderma = world's largest), AP, Rajasthan\n7. Limestone — MP, Rajasthan, Gujarat (for cement)\n\nENERGY:\n8. Coal — Jharkhand (Jharia) — Gondwana fields (80%)\n9. Petroleum — Mumbai High (largest, offshore)\n10. Thorium — Kerala coast = 25% of world's reserves\n\nKEY: Chota Nagpur Plateau = mineral heartland of India"},{"id":9,"ch":11,"subj":"polsci","marks":2,"q":"What is power sharing? Give prudential and moral reasons why it is desirable.","a":"POWER SHARING: Distributing governmental authority among different organs, levels, or groups so no single entity monopolizes power.\n\nPRUDENTIAL REASONS (practical):\n1. REDUCES CONFLICT: Groups with shared power feel invested → less reason to fight\n2. ENSURES STABILITY: All groups have stake → less risk of overthrow\n3. BETTER OUTCOMES: Diverse perspectives lead to more balanced policies\n4. LONG-TERM BENEFIT: Prevents short-term majority wins that create long-term instability\nExample: Belgium negotiated 4 amendments → peace vs Sri Lanka's majoritarianism → civil war\n\nMORAL REASONS (ethical):\n1. CITIZENS' RIGHT: People have right to be consulted on how they are governed\n2. SPIRIT OF DEMOCRACY: 'Rule by the people' — ALL sections must have a voice\n3. EQUAL DIGNITY: Every community deserves representation\n4. PREVENTS TYRANNY: Power sharing is the fundamental safeguard against authoritarian rule"},{"id":10,"ch":12,"subj":"polsci","marks":2,"q":"Distinguish between 'coming-together' and 'holding-together' federations.","a":"COMING-TOGETHER FEDERATIONS:\n• Independent states voluntarily unite to form a larger federation\n• All constituent states have EQUAL powers\n• States are relatively stronger; surrendered limited sovereignty for mutual benefit\n• Examples: USA (13 colonies, 1789), Australia, Switzerland\n\nHOLDING-TOGETHER FEDERATIONS:\n• A large diverse country divides power to maintain unity\n• Units often have DIFFERENT powers (asymmetric)\n• Centre is generally STRONGER than states\n• Designed to prevent fragmentation of a diverse nation\n• Examples: India, Spain, Belgium\n\nWHY INDIA IS HOLDING-TOGETHER:\n• Was a single colonial unit; not a union of independent states\n• Massive diversity needed central authority to maintain unity\n• Centre has residuary powers, appoints Governors, can declare Emergency\n• But states have guaranteed constitutional powers Centre cannot easily override"},{"id":11,"ch":14,"subj":"polsci","marks":2,"q":"What is communalism? How does it threaten democracy?","a":"COMMUNALISM: Using religion as the primary, exclusive basis for political identity; treating one community's interests as fundamentally opposed to all others.\n\nFORMS:\n• Communal ideology: 'My religion can only survive if it dominates'\n• Communal politics: demanding separate laws or territory based on religion\n• Communal violence: riots, targeted attacks on religious identity\n\nHOW IT THREATENS DEMOCRACY:\n1. MINORITY RIGHTS VIOLATED: When majority religion dominates, minorities are suppressed\n2. ELECTORAL MANIPULATION: Politicians create religious fear to win votes — deepens divisions\n3. VIOLENCE: Communal riots destroy social fabric; 1947 Partition, 1984 riots, 1992 post-Babri\n4. SECULARISM VIOLATED: Articles 14, 15, 25-28 guarantee equal treatment — communalism contradicts this\n5. NATIONAL UNITY AT RISK: Communalism can fragment the nation (India-Pakistan Partition example)"},{"id":12,"ch":15,"subj":"polsci","marks":2,"q":"What are the main challenges facing political parties in India?","a":"MAJOR CHALLENGES:\n\n1. DYNASTIC POLITICS:\n• Power inherited within families: INC (Nehru-Gandhi), SP (Mulayam-Akhilesh), RJD (Lalu-Tejashwi)\n• Limits meritocracy and leadership diversity\n\n2. MONEY AND MUSCLE POWER:\n• Elections expensive; spending limits violated with black money\n• 43% of MPs in 2019 had criminal cases pending\n\n3. LACK OF INTERNAL DEMOCRACY:\n• Leaders picked by families/seniors rather than party elections\n• Ordinary workers have little say in candidate selection\n\n4. CRIMINALIZATION:\n• MPs and MLAs with serious criminal cases continue to win\n• 'Winnability' prioritised over clean record by all parties\n\nREFORMS NEEDED: RTI for parties, mandatory internal elections, criminal disqualification, campaign finance transparency"},{"id":13,"ch":17,"subj":"eco","marks":2,"q":"Why is per capita income alone not a complete measure of development?","a":"INADEQUACY:\n\n1. HIDES INEQUALITY: Average income may be high but concentrated in few hands\n2. IGNORES HEALTH: A rich but unhealthy country has low life expectancy\n3. IGNORES EDUCATION: High income doesn't mean a literate, skilled population\n4. NON-MATERIAL ASPECTS MISSED: Freedom, dignity, security not captured by income\n\nKEY EXAMPLE:\n• Kerala: LOWER per capita income than Punjab BUT higher literacy (94%), longer life expectancy (77 yrs), better women's status\n• By income alone, Punjab is 'more developed' — but by human development, Kerala is ahead\n\nBETTER ALTERNATIVES:\n• HDI (life expectancy + education + income)\n• Infant Mortality Rate (IMR)\n• Literacy Rate\n• Body Mass Index (BMI) for nutrition\n• Multidimensional Poverty Index"},{"id":14,"ch":18,"subj":"eco","marks":2,"q":"Distinguish between organised and unorganised sectors of the Indian economy.","a":"ORGANISED SECTOR:\n• Registered enterprises following all labour laws\n• Workers have: minimum wage, PF (EPF), gratuity, health insurance (ESI)\n• Regular work, defined hours, formal contracts, job security\n• Examples: government jobs, banks, large factories\n• Size: approximately 7% of India's workforce\n\nUNORGANISED SECTOR:\n• Not registered; not covered by most labour laws\n• No minimum wage enforcement, no PF, no health insurance\n• Irregular work, no fixed hours, no contracts, no job security\n• Often exploitative wages and poor conditions\n• Examples: domestic workers, street vendors, construction labourers\n• Size: approximately 93% of India's ~500 million workers\n\nKEY CHALLENGE: India cannot achieve equitable development while 93% of workers lack basic protections — formalisation requires registration, universal social security, skill development"},{"id":15,"ch":19,"subj":"eco","marks":2,"q":"Distinguish between formal and informal credit. Why is informal credit problematic?","a":"FORMAL CREDIT:\n• Banks, cooperatives; 5-12% per year; RBI-regulated; requires collateral; legal protection\n\nINFORMAL CREDIT:\n• Moneylenders, traders, relatives; 30-60%+ per year; unregulated; no legal protection\n\nWHY INFORMAL CREDIT IS PROBLEMATIC:\n1. DEBT TRAPS: High interest means borrowers can never fully repay → perpetual debt cycle\n2. EXPLOITATION: Moneylenders take land as security → farmers lose land when crops fail\n3. BONDED LABOUR: Some borrowers work for lenders to repay debt\n4. NO LEGAL RECOURSE: Cannot approach courts against exploitation\n5. LIMITS INVESTMENT: Money spent on interest doesn't go to productive activities\n\nSOLUTIONS:\n• SHGs (12% interest, no collateral, 95%+ repayment)\n• NABARD rural credit support\n• Jan Dhan Yojana (universal bank accounts)\n• MUDRA loans (small business without collateral)"},{"id":16,"ch":20,"subj":"eco","marks":2,"q":"What is globalisation? How has it affected employment in India?","a":"GLOBALISATION: Increasing integration of economies, markets, production, and cultures across national borders.\nENABLED BY: Internet, container shipping, trade liberalisation (WTO), MNCs.\n\nPOSITIVE EFFECTS ON EMPLOYMENT:\n1. IT/BPO boom: Millions of high-paying software jobs; Bangalore/Hyderabad as global IT hubs\n2. Manufacturing exports: Garment, textile, auto components industries created jobs\n3. Higher wages: Global companies pay better than domestic firms\n4. Women's employment: Garment factories specifically employed many women\n\nNEGATIVE EFFECTS:\n1. Job displacement: Cheap Chinese imports undercut local manufacturers → factory closures\n2. Contract employment: MNCs use temporary workers → no job security, no benefits\n3. 'Race to the bottom': States weaken labour laws to attract MNC investment\n4. Regional inequality: IT jobs in cities; rural employment not transformed\n5. Agricultural pressure: Subsidised US/EU food imports can undercut Indian farmers"}];
export const SSC_LONG_QA: SscQA[] = [{"id":1,"ch":1,"subj":"hist","marks":5,"q":"Describe the role of Napoleon Bonaparte in spreading nationalism across Europe.","a":"Napoleon Bonaparte and European Nationalism\n\nINTRODUCTION:\nNapoleon was nationalism's most powerful carrier — simultaneously spreading revolutionary ideals AND provoking nationalist reactions through conquest. Historians call this 'the Napoleonic paradox.'\n\nNAPOLEON'S POSITIVE CONTRIBUTIONS:\n\n1. NAPOLEONIC CODE (Code Civil, 1804):\n• Abolished feudal privileges and hierarchy of birth\n• Established legal equality before the law for all citizens\n• Secured rights of property; abolished hereditary class privilege\n• Applied across Belgium, Holland, Switzerland, German and Italian states\n\n2. ADMINISTRATIVE MODERNISATION:\n• Uniform administrative divisions replaced fragmented princely states\n• Single currency, uniform weights, abolished internal tariffs\n• Modern bureaucracy replacing medieval Church and aristocratic governance\n\n3. STIRRED NATIONAL CONSCIOUSNESS:\n• Professional middle class and merchants experienced benefits of rational, unified governance\n• Saw the possibility of a modern secular national state as an ideal\n\nNAPOLEON'S PARADOX — CONQUEST PROVOKED REACTION NATIONALISM:\n\n1. RESISTANCE NATIONALISM:\n• In Germany, Spain, Italy — French occupation provoked fierce anti-French nationalism\n• 'Liberty, equality, fraternity' seemed hollow when French armies occupied their territories\n\n2. IN GERMANY: Fichte's 'Addresses to the German Nation' (1808); Arndt called for German unity against France; German identity crystallised against Napoleon\n\n3. IN SPAIN: Brutal guerrilla warfare against Napoleon → Spanish nationalism consolidated\n\n4. IN RUSSIA: 1812 invasion's failure → massive Russian national pride; Napoleon humiliated\n\nCONCLUSION:\nNapoleon was both propagator AND catalyst of European nationalism. He spread revolutionary values through administrative reforms and legal codes, but his imperial ambitions provoked the very national consciousness that ultimately destroyed his empire. Both roles advanced nationalism across Europe."},{"id":2,"ch":2,"subj":"hist","marks":5,"q":"Explain the events and outcomes of the Non-Cooperation Movement (1920-22).","a":"Non-Cooperation Movement (1920-22)\n\nBACKGROUND:\n• Rowlatt Act (1919) and Jallianwala Bagh massacre shocked the nation\n• Khilafat issue gave Gandhi opportunity for Hindu-Muslim unity\n• Gandhi proposed: non-cooperation with all British institutions\n\nMETHODS:\n1. Return of titles and honours given by British\n2. Boycott civil services, army, police, British courts\n3. Withdrawal from government-aided schools and colleges\n4. Boycott of foreign goods — burn foreign cloth\n5. Promote swadeshi — spinning and wearing khadi\n6. Boycott elections to legislative councils\n\nPARTICIPATION:\n• Middle class: boycotted schools, colleges, courts\n• Merchants: boycotted foreign goods; supported swadeshi\n• Peasants (Awadh — Baba Ramchandra): protested land rents\n• Tribals (AP — Alluri Sitarama Raju): protested forest laws\n• Workers: strikes in jute mills and mines\n• Women: participated in public politics for the FIRST TIME; broke purdah for national cause\n\nACHIEVEMENTS:\n1. First truly MASS movement — all classes, communities, regions\n2. Unprecedented Hindu-Muslim unity (Khilafat)\n3. Proved independence was practically achievable\n4. Khadi became national symbol of economic independence\n5. Brought Gandhi to centre of Indian politics as supreme mass leader\n\nSUSPENSION (February 1922) — CHAURI CHAURA:\n• Crowd burnt police chowki killing 22 constables\n• Gandhi immediately suspended NCM: 'Non-violence must be maintained even at political cost'\n• Gandhi arrested; 6-year sentence (released 1924)\n\nSIGNIFICANCE:\nNCM proved mass non-violent resistance was possible; laid groundwork for CDM (1930) and Quit India (1942)."},{"id":3,"ch":7,"subj":"geo","marks":5,"q":"Explain challenges facing water resources in India and describe traditional conservation methods.","a":"Water Resources — Challenges and Conservation\n\nINDIA'S WATER PARADOX:\n• 4000 BCM annual precipitation; only 1123 BCM usable\n• 4% of world's water but 16% of population → growing crisis\n\nCHALLENGES:\n1. UNEQUAL DISTRIBUTION: Wet Northeast floods; Rajasthan faces drought; 80% rain in 3-4 months\n2. GROUNDWATER DEPLETION: Punjab water table falls ~1m/year from intensive irrigation\n3. WATER POLLUTION: Industries dump effluents; only 30% of sewage treated\n4. INTER-STATE CONFLICTS: Cauvery (Karnataka-TN); Ravi-Beas (Punjab-Haryana-Rajasthan)\n5. CLIMATE CHANGE: Changing monsoon patterns; Himalayan glaciers shrinking\n\nTRADITIONAL CONSERVATION METHODS:\n\n1. JOHADS AND KUNDS (Rajasthan):\n• Johads: earthen check dams capturing monsoon runoff\n• Kunds: underground cylindrical cisterns for filtered rainwater storage\n• Community-maintained; adapted to semi-arid conditions\n• Revival: Tarun Bharat Sangh (Rajendra Singh) revived 8000+ johads; rivers flowed again\n\n2. BAMBOO DRIP IRRIGATION (Meghalaya):\n• 200-year-old Khasi tribal technology\n• Bamboo pipes channel stream water precisely to terraced fields\n• Delivers exactly the right amount to plant roots; zero energy cost\n• Serves multiple crop types; more sustainable than concrete canals\n\n3. KULHS (Himachal Pradesh):\n• Community-managed channels diverting mountain stream water to fields\n• Gravity-fed; require no pump energy\n• Village councils managed fair distribution equitably\n\n4. TANKS (South India) and ROOFTOP HARVESTING:\n• Large village ponds with sluice gates; some dating to 1000 AD\n• Tamil Nadu made rooftop rainwater harvesting MANDATORY by law (2001)\n\nLESSON: Community-based, locally adapted traditional systems are cheaper, more equitable, and more sustainable than mega-dams alone."},{"id":4,"ch":10,"subj":"geo","marks":5,"q":"Explain the factors determining industrial location in India with specific examples.","a":"Industrial Location — Determining Factors\n\nKEY PRINCIPLE: Industries maximise profits by minimising costs. Location decisions balance raw material costs, labour, power, transport, and market access.\n\n1. RAW MATERIAL PROXIMITY:\n• Iron and steel near coal and iron ore\n• Jamshedpur (TISCO, 1907): 32 km from Jharia coal, 80 km from Singhbhum iron ore, Subarnarekha river, Kolkata market — perfect location\n• Cotton textiles: Ahmedabad near Gujarat cotton; Mumbai near Maharashtra cotton\n\n2. POWER SUPPLY:\n• Steel plants near Damodar Valley coal-based power\n• IT parks in Bangalore: reliable power + fiber-optic connectivity\n\n3. LABOUR AVAILABILITY:\n• Mumbai cotton textiles: large migrant labour from Maharashtra, UP, Bihar\n• IT industry (Bangalore, Hyderabad): IITs, IIMs supply skilled English-speaking graduates\n\n4. TRANSPORT INFRASTRUCTURE:\n• Mumbai: largest port + rail hub → imported machinery, export goods\n• Chennai (automobile hub): connected to ports for component imports and car exports\n\n5. MARKET PROXIMITY:\n• Delhi-NCR automobiles: close to North India's massive market\n• Consumer goods locate near large populations\n\n6. CAPITAL AND FINANCIAL INFRASTRUCTURE:\n• Mumbai: financial capital; stock exchange, banks, venture capital\n\n7. GOVERNMENT POLICY:\n• SEZs attract foreign investment with liberal tax rules\n• Bokaro Steel: placed in backward Jharkhand by government policy\n\nMAJOR INDUSTRIAL REGIONS:\n• Mumbai-Pune: textiles, chemicals, pharmaceuticals, IT\n• Hugli (WB): jute, chemicals, engineering\n• Bangalore-Chennai: IT, aerospace, automobiles\n• Chota Nagpur: iron/steel, coal mining, heavy engineering"},{"id":5,"ch":11,"subj":"polsci","marks":5,"q":"Compare the Belgian and Sri Lankan models of managing ethnic diversity. What lessons do they teach?","a":"Belgium vs Sri Lanka — Managing Ethnic Diversity\n\nBELGIUM (Demographics: Dutch 59%, French 40%, German 1%; Brussels 80% French, 20% Dutch)\n\nBELGIAN ACCOMMODATION — 4 constitutional amendments (1970-1993):\n1. EQUAL CENTRAL GOVT: Equal French and Dutch ministers — neither community makes unilateral decisions\n2. INDEPENDENT STATE GOVTS: Regional governments have real powers Centre cannot override\n3. BRUSSELS SPECIAL GOVT: Equal-representation government for both communities in the capital\n4. COMMUNITY GOVERNMENT (3rd tier): Elected by language community; handles cultural/educational matters\n\nRESULT: Civil war avoided. Belgium united. Brussels became EU capital — gold standard of multicultural accommodation.\n\nSRI LANKA (Demographics: Sinhala 74% Buddhist, Tamil 18%, Christian 7%)\n\nSRI LANKA'S MAJORITARIAN MEASURES:\n1. SINHALA ONLY ACT (1956): Sole official language; Tamil excluded entirely\n2. PREFERENTIAL TREATMENT: Sinhala given preference in university/government jobs\n3. BUDDHIST PROMOTION: Constitution specially protected Buddhism\n4. DENIAL OF RIGHTS: Tamils felt denied equal rights and language\n\nRESULT: Tamil alienation → TULF demanded Eelam → LTTE formed → Civil War 1983-2009 → 80,000+ killed, 500,000+ displaced\n\nCOMPARATIVE LESSONS:\n| Feature | Belgium | Sri Lanka |\n| Approach | Negotiated accommodation | Majoritarian imposition |\n| Language policy | Both communities represented | Sinhala only |\n| Outcome | Peace, EU capital | 30-year civil war |\n\nFOUR LESSONS:\n1. Majoritarianism ≠ democracy: majority does NOT have right to suppress minorities\n2. Accommodation works: 4 amendments were expensive but far cheaper than war\n3. Timing matters: early accommodation prevents armed conflict\n4. For India: communal and caste tensions require Belgian-style accommodation"},{"id":6,"ch":12,"subj":"polsci","marks":5,"q":"Explain the federal features of India's Constitution. Is India truly federal?","a":"India's Federal Structure\n\nDEFINITION: Federalism = power constitutionally divided between central and state governments; both operate independently.\n\nINDIA = HOLDING-TOGETHER FEDERATION:\nConstitution uses 'Union of States' (not 'Federation') — deliberately centrally dominant.\n\nFEDERAL FEATURES:\n1. WRITTEN CONSTITUTION: Division of powers explicit; legally enforceable; cannot be changed unilaterally\n2. DIVISION OF POWERS (3 Lists): Union List (97 subjects), State List (66), Concurrent List (47); Residuary → Centre\n3. INDEPENDENT JUDICIARY: Supreme Court as umpire in Centre-State disputes; judicial review\n4. BICAMERAL PARLIAMENT: Rajya Sabha represents states at national level\n5. FINANCE COMMISSION: Determines revenue sharing between Centre and States every 5 years\n6. DECENTRALISATION: 73rd Amendment (1992) — Panchayati Raj mandatory; 3-tier structure; women's 1/3 reservation\n\nCENTRALISING (NON-FEDERAL) FEATURES:\n1. GOVERNOR: Appointed by Centre; acts as Centre's agent in states\n2. EMERGENCY PROVISIONS: Art. 352, 356, 360 — suspend federalism; Centre takes over\n3. UNEQUAL RAJYA SABHA: Not equal to Lok Sabha in powers (unlike US Senate)\n4. CENTRE REORGANISES STATES: Parliament can change boundaries unilaterally (Telangana 2014)\n5. SINGLE CITIZENSHIP: No state citizenship; only Indian citizenship\n6. RESIDUARY TO CENTRE: Any subject not listed → Centre (reverses usual federal practice)\n\nASSESSMENT:\nIndia is 'QUASI-FEDERAL' (KC Wheare) — more federal than unitary (3 lists, written constitution, independent judiciary) but Centre clearly dominant. Deliberate design choice in 1947: unity required for newly independent, massively diverse country."},{"id":7,"ch":19,"subj":"eco","marks":5,"q":"Explain the role of credit in India's economy. Why do different people get different credit terms?","a":"Credit in the Indian Economy\n\nMEANING: Credit = loan of money for a period, to be repaid with interest. Enables spending beyond current income; investment in productive activities.\n\nROLE OF CREDIT:\n1. AGRICULTURE: Farmers need credit for seeds, fertiliser, equipment before harvest\n2. MANUFACTURING: Working capital to pay wages, buy materials before selling\n3. TRADE: Stock goods now, sell later, pay supplier later\n4. HOUSING: Mortgage loans enable home ownership for middle class\n5. EDUCATION: Student loans invest in human capital\n\nTWO SOURCES OF CREDIT:\n\nFORMAL SECTOR:\n• Banks, cooperatives; 5-12% per year; RBI-regulated\n• Requires collateral (property, gold, FDs); complex documentation\n• Legal protection available\n\nINFORMAL SECTOR:\n• Moneylenders, traders; 30-60%+ per year\n• Unregulated, no oversight; exploitative terms\n• Accessible to those without collateral\n\nWHY DIFFERENT TERMS FOR DIFFERENT PEOPLE:\n1. COLLATERAL: Urban salaried workers have property → formal loans; rural poor have none → moneylenders\n2. INCOME REGULARITY: Permanent salaried = low risk; seasonal agricultural workers = high risk\n3. CREDIT HISTORY: Urban middle class has banking record; rural poor have no credit history\n4. GEOGRAPHIC ACCESS: 60% of bank branches in cities; rural areas underserved\n5. LITERACY: Complex documents exclude those with low literacy\n\nDEBT TRAPS:\n• Borrow at 40-60% → crop fails → can't repay → re-borrow → interest exceeds income → sell land → bonded labour\n\nSOLUTIONS:\n• SHGs: 12% interest, no collateral, 95%+ repayment\n• Jan Dhan Yojana: 50 crore bank accounts opened\n• MUDRA loans: small business without collateral\n• RBI Priority Sector Lending: banks must lend 40% to agriculture/weaker sections"},{"id":8,"ch":20,"subj":"eco","marks":5,"q":"What is globalisation? Explain its positive and negative effects on the Indian economy.","a":"Globalisation and the Indian Economy\n\nDEFINITION: Globalisation = increasing integration of economies, markets, production, and cultures across national borders.\n\nFACTORS ENABLING GLOBALISATION:\n1. ICT: Internet, mobile phones, satellites — real-time global business\n2. TRANSPORT: Container shipping cost fell 90% since 1950s; air cargo for high-value goods\n3. TRADE LIBERALISATION: WTO (1995), India's LPG reforms (1991)\n4. MNCs: 65,000+ multinationals linking global production chains\n\nGLOBAL VALUE CHAINS: iPhone designed USA, chips Taiwan, assembled China, software India — single product crosses 10+ borders\n\nINDIA'S INTEGRATION:\n• 1991 LPG reforms: tariffs 350% → 30%; FDI allowed; GDP growth 3.5% → 6-7% average\n\nPOSITIVE EFFECTS:\n1. IT REVOLUTION: $200B+ exports; TCS/Infosys/Wipro are global companies; 5 million+ employed\n2. PHARMA EXPORTS: 40% of global generic drugs; $25B+ exports; affordable medicines for Africa\n3. CONSUMER BENEFITS: Greater variety at lower prices; technology accessible to middle class\n4. EMPLOYMENT: Export-oriented garments, auto components created millions of jobs\n5. GROWTH: Poverty fell from 45% (1993) to 22% (2011)\n\nNEGATIVE EFFECTS:\n1. DOMESTIC INDUSTRY DISRUPTION: Cheap Chinese toys, electronics undercut local manufacturers\n2. EMPLOYMENT QUALITY: Contract workers with no security; race to the bottom on labour laws\n3. AGRICULTURAL IMPACT: US/EU subsidised food imports undercut Indian farmers; Bt cotton farmer debt\n4. INEQUALITY WIDENED: IT workers gained enormously; unskilled workers gained little or lost\n\nCONCLUSION: Globalisation is India's double-edged sword — net beneficiary overall (growth, poverty reduction) but benefits unequally distributed. Fair globalisation requires strong labour laws, agricultural support, social safety nets, and Fair Trade practices."}];
export const SSC_FLASHCARDS: SscFlashcard[] = [{"id":1,"ch":1,"subj":"hist","q":"What was Zollverein (1834)?","a":"Prussian-led customs union removing tariff barriers between 39 German states. Created unified market, common currency, standard weights. Economic integration preceded political unification (1871) by 37 years. KEY INSIGHT: Economic self-interest is a stronger driver of unity than ideology alone. 'Trade routes before battle routes.'"},{"id":2,"ch":2,"subj":"hist","q":"Why did Gandhi choose SALT for the 1930 protest?","a":"Salt = universal necessity. Every Indian — poor or rich, Hindu or Muslim — needed salt. British had monopolised and taxed it. Making salt from seawater was simple enough for anyone anywhere to do. The Dandi March (240 miles, 24 days) gained massive international attention. Perfect symbolic act: the humblest challenge to the mightiest empire."},{"id":3,"ch":2,"subj":"hist","q":"What happened at Chauri Chaura (1922) and why did Gandhi react the way he did?","a":"February 1922: Crowd burnt police chowki killing 22 constables. Gandhi IMMEDIATELY suspended entire Non-Cooperation Movement despite protests from Nehru, CR Das. HIS REASONING: 'Non-violence must be maintained — a violent movement loses its moral authority.' Shows Gandhi's absolute commitment to non-violence as both strategy AND principle, not just tactics."},{"id":4,"ch":3,"subj":"hist","q":"What was indentured labour? Why called 'new system of slavery'?","a":"After slavery abolished (1833), Indians/Chinese sent to Caribbean, Fiji, Mauritius under 5-year contracts. Called 'girmitiya' (from 'agreement'). 'New slavery' because: no freedom to leave, physical punishment allowed, thousands of miles from family. YET: workers preserved culture — Hosay festival in Trinidad blends Hindu + Muslim traditions. Human resilience under impossible conditions."},{"id":5,"ch":4,"subj":"hist","q":"How did Vernacular Press Act (1878) accidentally HELP Indian nationalism?","a":"Colonial govt censored Indian-language newspapers. PARADOX: This made newspapers 'martyrs' — drew more readers and sympathy; proved British FEARED print; created underground distribution networks; politicised Indians who saw censorship as proof of British tyranny. You cannot suppress ideas with censorship — you only amplify them. Act was repealed in 1882 having completely failed."},{"id":6,"ch":5,"subj":"geo","q":"Name 5 soil types and best crop for each.","a":"1. ALLUVIAL (Indo-Gangetic, most widespread): Wheat, rice, sugarcane. 2. BLACK/REGUR (Deccan): COTTON — self-ploughing, retains moisture, Ca+Mg+K. 3. RED/YELLOW (Odisha/Chhattisgarh): Iron oxide, moderate fertility, rice/wheat. 4. LATERITE (W.Ghats, NE): Heavily leached; cashew, tea, coffee. 5. ARID (Rajasthan): Sandy, coarse; drought-resistant crops. EXAM TRICK: Black = Cotton; Alluvial = most widespread and fertile."},{"id":7,"ch":6,"subj":"geo","q":"What is JFM (Joint Forest Management) and why does it work?","a":"JFM: Partnership where communities protect assigned forest area and SHARE the benefits (timber, non-timber products, wages). Started Odisha 1988. WHY IT WORKS: Communities who LIVE in forests notice encroachments first; have generational knowledge; have direct incentive when they share benefits. 97% of JFM forests show improved tree density. Chipko showed community-only protection works; JFM adds government legal backing."},{"id":8,"ch":7,"subj":"geo","q":"What is NBA and what conflict does it represent?","a":"Narmada Bachao Andolan: Movement against large Narmada dams (Sardar Sarovar). Led by Medha Patkar. 250,000+ people (mostly Adivasi/tribal) displaced without adequate rehabilitation. REPRESENTS: Conflict between 'development' (dams for irrigation + power) and 'justice' (rights of communities to not be displaced). WHO benefits from dams? Cities and farmers downstream. WHO pays? Tribal communities who lose homes and forests. Challenges our definition of 'national interest'."},{"id":9,"ch":8,"subj":"geo","q":"Green Revolution: Benefits vs Problems in one shot.","a":"BENEFITS: Food self-sufficiency (ended 'ship to mouth'); wheat production tripled; Punjab = India's granary; famine risk greatly reduced; farmers' incomes rose. PROBLEMS: Regional inequality (only Punjab/Haryana/UP benefited); soil degradation; Punjab water table falls 1m/year; HYV seeds must be repurchased annually (farmer debt); pesticide health impacts (cancer train). SHORT-TERM food security achieved but LONG-TERM agricultural sustainability threatened."},{"id":10,"ch":9,"subj":"geo","q":"Why does India's 25% thorium reserve matter?","a":"India holds ~25% of world's thorium in Kerala/TN/AP coastal monazite sands. Thorium can fuel nuclear reactors. India's 3-Stage Nuclear Program has thorium as Stage 3 ultimate fuel. If thorium reactors developed: energy for CENTURIES without importing fuel. This is why India refuses to sign NPT — to protect its nuclear program. Currently Stage 1 (uranium) and Stage 2 (plutonium breeders) operational; Stage 3 under development at BARC."},{"id":11,"ch":11,"subj":"polsci","q":"Belgian model in 4 points — memorise this!","a":"1. EQUAL CENTRAL GOVT: Equal French + Dutch ministers; no unilateral decisions — consensus required. 2. INDEPENDENT STATE GOVTS: Flemish, Walloon, Brussels have real power Centre cannot override. 3. BRUSSELS SPECIAL GOVT: Equal representation for BOTH communities in the capital. 4. COMMUNITY GOVT (3rd tier): Elected by language community; handles cultural/educational matters across geographic regions. RESULT: Peace. Belgium united. Brussels = EU capital. Gold standard of multicultural accommodation."},{"id":12,"ch":12,"subj":"polsci","q":"73rd Amendment (1992) — why is it so significant?","a":"Made Panchayati Raj CONSTITUTIONALLY MANDATORY in all Indian states. Created 3-tier: Gram Panchayat → Panchayat Samiti → Zila Parishad. Mandated 5-year elections (no more indefinite postponement). Reserved 1/3 seats for women (many states now 50%). SC/ST reservations. Transferred 29 functions to panchayats. SIGNIFICANCE: World's largest grassroots democracy; constitutional status for local government; empowered women and marginalised communities. India now has 3 million elected women representatives at panchayat level!"},{"id":13,"ch":14,"subj":"polsci","q":"What is patriarchy and how does it affect democracy?","a":"PATRIARCHY: Social system where men hold primary power; women subordinated in family, economy, politics. Manifests as: unequal wages, limited property rights, domestic violence, political underrepresentation. IN DEMOCRACY: A democracy where 50% of citizens (women) are excluded is INCOMPLETE. India's Lok Sabha: ~12% women (world average <15%). Women's reservation in panchayats (1/3) has TRANSFORMED local governance — women leaders build toilets, schools, roads — proven more effective in many areas than men."},{"id":14,"ch":15,"subj":"polsci","q":"Party vs Pressure Group — key difference?","a":"POLITICAL PARTY: Directly seeks power — contests elections, forms governments, makes laws. Examples: INC, BJP, BSP. PRESSURE GROUP: Does NOT contest elections — lobbies and influences those who ARE in power. Examples: FICCI (industry), trade unions (workers), farmers' associations. KEY: When a pressure group contests elections, it TRANSFORMS into a political party. Function determines category, not size or membership."},{"id":15,"ch":16,"subj":"polsci","q":"What is 'popular legitimacy' — democracy's greatest strength?","a":"POPULAR LEGITIMACY: People accept the authority of the democratically elected government even if they personally voted against it, because the PROCESS (free, fair elections) was accepted as legitimate. UNIQUE TO DEMOCRACY: Even the LOSING SIDE accepts the result and doesn't overthrow the winner. In dictatorships, power is held by force, not consent. WHY IT MATTERS: This is why democracies have peaceful power transfers while authoritarian regimes have coups. Churchill: 'Democracy is the worst form of government, except for all the others.'"},{"id":16,"ch":17,"subj":"eco","q":"Kerala vs Punjab — the key development lesson.","a":"PUNJAB: Higher per capita income. 'Green Revolution' agricultural wealth. KERALA: Lower per capita income. Gulf remittances. BUT KERALA WINS: Life expectancy 77+ years (Punjab 70), IMR 7 vs 20+, Literacy 94% vs 77%, Women's education and empowerment. WHY? Kerala invests in public health and education for decades. LESSON: Development requires POLICY CHOICES, not just income growth. Income is a MEANS to development, not development itself. This is the core lesson of HDI — the biggest thing to remember from this chapter!"},{"id":17,"ch":18,"subj":"eco","q":"India's 'services paradox' explained simply.","a":"Tertiary (services) sector = 60% of GDP but employs only 30% of workers. Primary (agriculture) = 15% of GDP but employs 50% of workers. PROBLEM: Half of India's people work in the lowest-productivity sector. SOLUTION NEEDED: Transfer workers from low-productivity agriculture to higher-productivity industry and services. This is 'structural transformation' — what all developed countries did. China did it through manufacturing (100M+ workers moved to factories). India needs its own path via services + manufacturing."},{"id":18,"ch":19,"subj":"eco","q":"How do SHGs solve rural credit problems?","a":"SHG (15-20 rural poor, mostly women) save small amounts (₹25-100/week) → pool for group lending → members borrow at ~12% vs moneylenders' 30-60%. NO COLLATERAL needed — peer pressure ensures repayment; 95%+ repayment rates. NABARD supports SHG-bank linkage. Inspired by Grameen Bank (Muhammad Yunus, Nobel 2006). India has 1.2 CRORE SHGs with 14.2 crore women members! Proves poor are creditworthy when systems are DESIGNED FOR THEM, not against them."},{"id":19,"ch":20,"subj":"eco","q":"What is an SEZ and why create them?","a":"SEZ (Special Economic Zone): Geographic area with different (more liberal) economic rules — no import tariffs, tax holidays, simplified regulations, relaxed labour laws, world-class govt-built infrastructure. WHY: Attract FDI from MNCs; boost exports; create jobs; transfer technology. CHINA'S SHENZHEN (1980): Transformed fishing village of 30,000 into megacity of 12 million and global manufacturing hub. INDIA: 400+ SEZs but many underperform. CRITICISM: Tax revenue forgone; land acquisition displaces farmers; race to bottom on labour rights."},{"id":20,"ch":20,"subj":"eco","q":"What is Fair Trade and why does it matter?","a":"FAIR TRADE: Movement ensuring producers in developing countries get stable, fair prices regardless of global price crashes. How: Fair Trade certified products (coffee, tea, chocolate, cotton) carry a label; consumers pay a small premium; premium goes directly to producer communities as guaranteed minimum price. WHAT IT FIXES: Globalisation's main injustice — market power held by MNCs who squeeze maximum margin from poor farmers. Fairtrade coffee from Ethiopia means farmers get stable income even when global prices crash. LESSON: Globalisation's benefits CAN be distributed more fairly through consumer choice and transparency."}];

